-- TheOutHaven production application schema baseline.
--
-- The original core database predates Git migration tracking. This baseline is
-- generated from the verified Oregon application schema and then layers in the
-- permanent Virginia post-cutover changes recovered from Virginia's migration ledger.
-- Historical migrations are retained under supabase/migrations_archive/ for audit.
--
-- Intentionally excluded:
--   * migration_work and source_* migration helper schemas
--   * Virginia-only toh_*migration* cutover helper tables/functions
--   * Supabase migration-history rows
--   * pg_cron jobs (the extension is enabled, but Virginia must remain at 0 jobs)
--   * production table data

create extension if not exists "btree_gist" with schema public;
create extension if not exists "dblink" with schema extensions;
create extension if not exists "http" with schema extensions;
create extension if not exists "pg_cron";
create extension if not exists "pg_net" with schema public;
create extension if not exists "pg_stat_statements";
create extension if not exists "pg_trgm" with schema public;
create extension if not exists "pgcrypto" with schema extensions;
create extension if not exists "postgis" with schema extensions;
create extension if not exists "postgres_fdw" with schema extensions;
create extension if not exists "supabase_vault" with schema vault;
create extension if not exists "unaccent" with schema public;
create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists "vector" with schema public;




SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "fraud_internal";


ALTER SCHEMA "fraud_internal" OWNER TO "postgres";


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE SCHEMA IF NOT EXISTS "private";


ALTER SCHEMA "private" OWNER TO "postgres";


CREATE TYPE "public"."career_job_status" AS ENUM (
    'draft',
    'open',
    'paused',
    'closed',
    'filled',
    'archived'
);


ALTER TYPE "public"."career_job_status" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."decision_blocks_sensitive_action"("p_decision" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select coalesce(p_decision->>'decision','allow') in ('step_up_verification','manual_review','hold','block');
$$;


ALTER FUNCTION "fraud_internal"."decision_blocks_sensitive_action"("p_decision" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."emit_signal"("p_subject_type" "text", "p_subject_id" "text", "p_rule_key" "text", "p_signal_type" "text", "p_category" "text", "p_source" "text", "p_severity" smallint, "p_score_delta" integer, "p_evidence" "jsonb", "p_dedupe_key" "text", "p_related_subject_type" "text" DEFAULT NULL::"text", "p_related_subject_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
begin
  insert into public.fraud_signals(
    subject_type, subject_id, related_subject_type, related_subject_id,
    rule_key, signal_type, category, source, severity, score_delta,
    confidence, evidence, dedupe_key, observed_at
  ) values (
    p_subject_type, p_subject_id, p_related_subject_type, p_related_subject_id,
    p_rule_key, p_signal_type, p_category, p_source,
    greatest(1, least(5, p_severity)), greatest(-100, least(100, p_score_delta)),
    1.0, coalesce(p_evidence,'{}'::jsonb), p_dedupe_key, now()
  ) on conflict (dedupe_key) where dedupe_key is not null do nothing;
end;
$$;


ALTER FUNCTION "fraud_internal"."emit_signal"("p_subject_type" "text", "p_subject_id" "text", "p_rule_key" "text", "p_signal_type" "text", "p_category" "text", "p_source" "text", "p_severity" smallint, "p_score_delta" integer, "p_evidence" "jsonb", "p_dedupe_key" "text", "p_related_subject_type" "text", "p_related_subject_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."guard_event_publication"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
declare
  v_decision jsonb;
  v_connect text;
begin
  if new.status='scheduled' and (old.status is distinct from new.status or coalesce(old.searchable,false)=false and coalesce(new.searchable,false)=true) then
    v_decision := public.fraud_decide_subject('event',new.id::text);
    if fraud_internal.decision_blocks_sensitive_action(v_decision) then raise exception 'fraud_review_required:event'; end if;

    if new.location_id is not null then
      v_decision := public.fraud_decide_subject('location',new.location_id::text);
      if fraud_internal.decision_blocks_sensitive_action(v_decision) then raise exception 'fraud_review_required:location'; end if;
      select stripe_connect_account_id into v_connect from public.locations where id=new.location_id;
    elsif new.organization_id is not null then
      v_decision := public.fraud_decide_subject('organizer',new.organization_id::text);
      if fraud_internal.decision_blocks_sensitive_action(v_decision) then raise exception 'fraud_review_required:organizer'; end if;
      select stripe_connect_account_id into v_connect from public.organizations where id=new.organization_id;
    end if;

    if v_connect is not null and btrim(v_connect) <> '' then
      v_decision := public.fraud_decide_subject('payout','connect-account:' || v_connect);
      if fraud_internal.decision_blocks_sensitive_action(v_decision) then raise exception 'fraud_review_required:payout'; end if;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "fraud_internal"."guard_event_publication"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."guard_event_ticket_order_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
declare
  v_event public.events;
  v_decision jsonb;
  v_velocity_count integer := 0;
  v_identity_key text;
begin
  select * into v_event from public.events where id = new.event_id;
  if v_event.id is null then return new; end if;

  v_decision := public.fraud_decide_subject('event', v_event.id::text);
  if fraud_internal.decision_blocks_sensitive_action(v_decision) then
    raise exception using errcode = '42501', message = 'fraud_review_required:event';
  end if;

  if v_event.location_id is not null then
    v_decision := public.fraud_decide_subject('location', v_event.location_id::text);
    if fraud_internal.decision_blocks_sensitive_action(v_decision) then
      raise exception using errcode = '42501', message = 'fraud_review_required:location';
    end if;
  elsif v_event.organization_id is not null then
    v_decision := public.fraud_decide_subject('organizer', v_event.organization_id::text);
    if fraud_internal.decision_blocks_sensitive_action(v_decision) then
      raise exception using errcode = '42501', message = 'fraud_review_required:organizer';
    end if;
  end if;

  if new.purchaser_user_id is not null then
    v_decision := public.fraud_decide_subject('user', new.purchaser_user_id::text);
    if fraud_internal.decision_blocks_sensitive_action(v_decision) then
      raise exception using errcode = '42501', message = 'fraud_review_required:user';
    end if;

    v_identity_key := 'ticket:user:' || new.purchaser_user_id::text;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_identity_key, 0));
    select count(*) into v_velocity_count
    from public.event_ticket_orders o
    where o.purchaser_user_id = new.purchaser_user_id
      and o.created_at >= now() - interval '15 minutes';
  elsif new.purchaser_email is not null and btrim(new.purchaser_email) <> '' then
    v_identity_key := 'ticket:email:' || lower(btrim(new.purchaser_email));
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_identity_key, 0));
    select count(*) into v_velocity_count
    from public.event_ticket_orders o
    where lower(btrim(o.purchaser_email)) = lower(btrim(new.purchaser_email))
      and o.created_at >= now() - interval '15 minutes';
  elsif new.purchaser_phone is not null
        and regexp_replace(new.purchaser_phone, '[^0-9]', '', 'g') <> '' then
    v_identity_key := 'ticket:phone:' || regexp_replace(new.purchaser_phone, '[^0-9]', '', 'g');
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_identity_key, 0));
    select count(*) into v_velocity_count
    from public.event_ticket_orders o
    where regexp_replace(coalesce(o.purchaser_phone, ''), '[^0-9]', '', 'g') = regexp_replace(new.purchaser_phone, '[^0-9]', '', 'g')
      and o.created_at >= now() - interval '15 minutes';
  end if;

  if v_velocity_count >= 6 then
    raise exception using errcode = '42501', message = 'fraud_velocity_block:ticket_order';
  end if;

  if new.provider_account_id is not null and btrim(new.provider_account_id) <> '' then
    v_decision := public.fraud_decide_subject('payout', 'connect-account:' || new.provider_account_id);
    if fraud_internal.decision_blocks_sensitive_action(v_decision) then
      raise exception using errcode = '42501', message = 'fraud_review_required:payout';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "fraud_internal"."guard_event_ticket_order_insert"() OWNER TO "postgres";


