CREATE OR REPLACE FUNCTION "fraud_internal"."on_business_claim_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
declare
  v_actor_count integer := 0;
  v_score integer;
  v_severity smallint;
begin
  if new.user_id is not null then
    select count(*) into v_actor_count
    from public.business_claims c
    where c.user_id = new.user_id
      and c.created_at >= now() - interval '60 minutes';
  elsif new.owner_email is not null and btrim(new.owner_email) <> '' then
    select count(*) into v_actor_count
    from public.business_claims c
    where lower(btrim(c.owner_email)) = lower(btrim(new.owner_email))
      and c.created_at >= now() - interval '60 minutes';
  end if;

  if v_actor_count >= 3 then
    v_severity := case when v_actor_count >= 6 then 5 else 4 end;
    v_score := case when v_severity = 5 then 55 else 35 end;

    perform fraud_internal.emit_signal(
      'claim', new.id::text, 'claim_velocity', 'claim_velocity', 'account_takeover',
      'db_realtime', v_severity, v_score,
      jsonb_build_object('actor_claims_60m',v_actor_count),
      'claim-velocity:' || new.id::text,
      'location', new.location_id::text
    );

    if new.user_id is not null then
      perform fraud_internal.emit_signal(
        'user', new.user_id::text, 'claim_velocity', 'claim_velocity', 'account_takeover',
        'db_realtime', v_severity, v_score,
        jsonb_build_object('actor_claims_60m',v_actor_count),
        'claim-user-velocity:' || new.user_id::text || ':' || to_char(date_trunc('hour',now()),'YYYYMMDDHH24'),
        'claim', new.id::text
      );
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "fraud_internal"."on_business_claim_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."on_claim_challenge_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
declare
  v_ip_count integer := 0;
begin
  if new.ip_hash is not null and btrim(new.ip_hash) <> '' then
    insert into public.fraud_identity_links(identity_type,identity_hash,subject_type,subject_id,source,confidence,last_seen_at,metadata)
    values ('ip_hash',new.ip_hash,'claim',new.id::text,'claim_verification',1.0,now(),jsonb_build_object('location_id',new.location_id))
    on conflict(identity_type,identity_hash,subject_type,subject_id)
    do update set last_seen_at=excluded.last_seen_at, metadata=excluded.metadata;

    select count(distinct c.id) into v_ip_count
    from public.claim_verification_challenges c
    where c.ip_hash = new.ip_hash and c.created_at >= now() - interval '60 minutes';

    if v_ip_count >= 3 then
      perform fraud_internal.emit_signal(
        'claim',new.id::text,'claim_ip_velocity','claim_ip_velocity','account_takeover','db_realtime',
        case when v_ip_count >= 6 then 5 else 4 end,
        case when v_ip_count >= 6 then 65 else 45 end,
        jsonb_build_object('claim_challenges_same_ip_60m',v_ip_count),
        'claim-ip-velocity:' || new.id::text || ':' || to_char(date_trunc('hour',now()),'YYYYMMDDHH24'),
        'location',new.location_id::text
      );
    end if;
  end if;

  if tg_op = 'UPDATE' and coalesce(new.attempt_count,0) >= 5 and coalesce(old.attempt_count,0) < 5 then
    perform fraud_internal.emit_signal(
      'claim',new.id::text,'claim_otp_bruteforce','otp_bruteforce','account_takeover','db_realtime',5,60,
      jsonb_build_object('attempt_count',new.attempt_count,'contact_match',new.contact_match),
      'claim-otp-bruteforce:' || new.id::text,
      'location',new.location_id::text
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "fraud_internal"."on_claim_challenge_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."on_event_material_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
begin
  if (coalesce(old.searchable,false) or lower(coalesce(old.status,'')) in ('scheduled','published','active','live','approved'))
     and (
       new.location_id is distinct from old.location_id
       or new.starts_at is distinct from old.starts_at
       or new.ends_at is distinct from old.ends_at
       or new.price_min is distinct from old.price_min
       or new.price_max is distinct from old.price_max
       or new.external_url is distinct from old.external_url
       or new.capacity is distinct from old.capacity
     ) then
    perform fraud_internal.emit_signal(
      'event', new.id::text, 'event_material_change', 'material_change_after_publish', 'content_integrity',
      'db_realtime', 3, 25,
      jsonb_build_object(
        'location_changed',new.location_id is distinct from old.location_id,
        'time_changed',(new.starts_at is distinct from old.starts_at or new.ends_at is distinct from old.ends_at),
        'price_changed',(new.price_min is distinct from old.price_min or new.price_max is distinct from old.price_max),
        'ticket_url_changed',new.external_url is distinct from old.external_url,
        'capacity_changed',new.capacity is distinct from old.capacity
      ),
      'event-material-change:' || new.id::text || ':' || txid_current()::text,
      'location', new.location_id::text
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "fraud_internal"."on_event_material_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "fraud_internal"."on_event_ticket_order_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'fraud_internal'
    AS $$
declare
  v_count integer := 0;
  v_severity smallint;
  v_score integer;
  v_bucket text;
begin
  if new.purchaser_user_id is not null then
    select count(*) into v_count from public.event_ticket_orders o
    where o.purchaser_user_id=new.purchaser_user_id and o.created_at >= now()-interval '15 minutes';
  elsif new.purchaser_email is not null and btrim(new.purchaser_email) <> '' then
    select count(*) into v_count from public.event_ticket_orders o
    where lower(btrim(o.purchaser_email))=lower(btrim(new.purchaser_email)) and o.created_at >= now()-interval '15 minutes';
  elsif new.purchaser_phone is not null and btrim(new.purchaser_phone) <> '' then
    select count(*) into v_count from public.event_ticket_orders o
    where regexp_replace(o.purchaser_phone,'[^0-9]','','g')=regexp_replace(new.purchaser_phone,'[^0-9]','','g') and o.created_at >= now()-interval '15 minutes';
  end if;

  if v_count >= 5 then
    v_severity := case when v_count >= 10 then 5 when v_count >= 7 then 4 else 3 end;
    v_score := case when v_severity=5 then 60 when v_severity=4 then 45 else 30 end;
    perform fraud_internal.emit_signal(
      'order',new.id::text,'ticket_order_velocity','ticket_order_velocity','payments','db_realtime',
      v_severity,v_score,jsonb_build_object('matching_ticket_orders_15m',v_count),
      'ticket-order-velocity:' || new.id::text,
      'event',new.event_id::text
    );

    if new.purchaser_user_id is not null then
      v_bucket := to_char(now(),'YYYYMMDDHH24') || ':' || ((extract(minute from now())::int / 15)::text);
      perform fraud_internal.emit_signal(
        'user',new.purchaser_user_id::text,'user_velocity','ticket_order_velocity','account_integrity','db_realtime',
        v_severity,v_score,jsonb_build_object('matching_ticket_orders_15m',v_count),
        'user-ticket-order-velocity:' || new.purchaser_user_id::text || ':' || v_bucket,
        'order',new.id::text
      );
    end if;
  end if;
  return new;
end;
$$;


