CREATE OR REPLACE FUNCTION "private"."dispatch_tracked_edge_request"("p_job_key" "text", "p_function_name" "text", "p_url" "text", "p_headers" "jsonb" DEFAULT '{}'::"jsonb", "p_body" "jsonb" DEFAULT '{}'::"jsonb", "p_timeout_milliseconds" integer DEFAULT 55000) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'pg_catalog', 'pg_temp'
    AS $$
declare
  run_id uuid;
  network_request_id bigint;
  started_at timestamptz := clock_timestamp();
begin
  if nullif(btrim(p_job_key), '') is null
     or nullif(btrim(p_function_name), '') is null
     or nullif(btrim(p_url), '') is null then
    raise exception 'Tracked Edge request requires job key, function name, and URL';
  end if;

  insert into public.cron_job_runs(
    job_key,
    job_name,
    function_name,
    source,
    status,
    started_at,
    created_at,
    message,
    metadata
  ) values (
    p_job_key,
    p_job_key,
    p_function_name,
    'pg_net_tracked',
    'running',
    started_at,
    started_at,
    p_job_key || ' request dispatched.',
    jsonb_build_object('truthful_http_monitoring', true)
  )
  returning id into run_id;

  insert into public.cron_jobs(
    job_key,
    job_name,
    route_path,
    source,
    is_active,
    last_status,
    last_started_at,
    last_message,
    updated_at
  ) values (
    p_job_key,
    p_job_key,
    'supabase/functions/' || p_function_name,
    'edge_function',
    true,
    'running',
    started_at,
    p_job_key || ' request dispatched.',
    started_at
  )
  on conflict (job_key) do update set
    last_status = 'running',
    last_started_at = excluded.last_started_at,
    last_message = excluded.last_message,
    updated_at = excluded.updated_at;

  network_request_id := net.http_post(
    url := p_url,
    headers := jsonb_build_object('Content-Type', 'application/json') || coalesce(p_headers, '{}'::jsonb),
    body := coalesce(p_body, '{}'::jsonb) || jsonb_build_object('_cron_run_id', run_id),
    timeout_milliseconds := greatest(1000, least(coalesce(p_timeout_milliseconds, 55000), 120000))
  );

  update public.cron_job_runs
  set request_id = network_request_id,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('request_id', network_request_id)
  where id = run_id;

  return network_request_id;
exception when others then
  if run_id is not null then
    update public.cron_job_runs
    set status = 'failed',
        finished_at = clock_timestamp(),
        completed_at = clock_timestamp(),
        duration_ms = greatest(0, floor(extract(epoch from (clock_timestamp() - started_at)) * 1000)::integer),
        transport_status = 'dispatch_error',
        error_message = sqlerrm,
        message = p_job_key || ' dispatch failed.',
        reconciled_at = clock_timestamp()
    where id = run_id;
  end if;
  raise;
end
$$;


ALTER FUNCTION "private"."dispatch_tracked_edge_request"("p_job_key" "text", "p_function_name" "text", "p_url" "text", "p_headers" "jsonb", "p_body" "jsonb", "p_timeout_milliseconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."reconcile_tracked_edge_requests"("p_stale_after" interval DEFAULT '00:10:00'::interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net', 'pg_catalog', 'pg_temp'
    AS $$
declare
  response_row record;
  completed_count integer := 0;
  is_success boolean;
  final_error text;
  response_json jsonb;
begin
  for response_row in
    select
      runs.id,
      runs.job_key,
      runs.started_at,
      responses.status_code,
      responses.timed_out,
      responses.error_msg,
      responses.content,
      responses.created
    from public.cron_job_runs runs
    join net._http_response responses on responses.id = runs.request_id
    where runs.source = 'pg_net_tracked'
      and runs.status in ('running', 'started')
  loop
    response_json := private.try_parse_jsonb(response_row.content);
    is_success := response_row.status_code between 200 and 299
      and not coalesce(response_row.timed_out, false)
      and response_row.error_msg is null
      and not private.response_declares_failure(response_row.content);

    final_error := case
      when coalesce(response_row.timed_out, false) then 'pg_net request timed out'
      when response_row.error_msg is not null then response_row.error_msg
      when response_row.status_code is null then 'pg_net returned no HTTP status'
      when response_row.status_code not between 200 and 299 then 'Edge Function returned HTTP ' || response_row.status_code
      when private.response_declares_failure(response_row.content) then 'Edge Function response declared failure'
      when response_json is null then 'Edge Function returned a non-JSON response'
      else null
    end;

    if response_json is null then
      is_success := false;
    end if;

    update public.cron_job_runs
    set status = case when is_success then 'success' else 'failed' end,
        finished_at = response_row.created,
        completed_at = response_row.created,
        duration_ms = greatest(0, floor(extract(epoch from (response_row.created - response_row.started_at)) * 1000)::integer),
        http_status = response_row.status_code,
        transport_status = case
          when coalesce(response_row.timed_out, false) then 'timeout'
          when response_row.error_msg is not null then 'transport_error'
          when response_json is null then 'invalid_response'
          when is_success then 'completed'
          else 'http_error'
        end,
        response_excerpt = left(response_row.content, 1000),
        details = coalesce(response_json, details, '{}'::jsonb),
        error_message = final_error,
        message = case when is_success
          then response_row.job_key || ' completed successfully.'
          else response_row.job_key || ' failed.'
        end,
        reconciled_at = clock_timestamp()
    where id = response_row.id;

    update public.cron_jobs
    set last_status = case when is_success then 'success' else 'failed' end,
        last_completed_at = case when is_success then response_row.created else last_completed_at end,
        last_failed_at = case when is_success then last_failed_at else response_row.created end,
        last_duration_ms = greatest(0, floor(extract(epoch from (response_row.created - response_row.started_at)) * 1000)::integer),
        last_message = case when is_success
          then response_row.job_key || ' completed successfully.'
          else response_row.job_key || ' failed.'
        end,
        last_details = coalesce(response_json, last_details, '{}'::jsonb),
        last_error = final_error,
        updated_at = clock_timestamp()
    where job_key = response_row.job_key;

    completed_count := completed_count + 1;
  end loop;

  with stale as (
    update public.cron_job_runs
    set status = 'failed',
        finished_at = clock_timestamp(),
        completed_at = clock_timestamp(),
        duration_ms = greatest(0, floor(extract(epoch from (clock_timestamp() - started_at)) * 1000)::integer),
        transport_status = 'response_missing',
        error_message = 'No pg_net response was available before the reconciliation deadline',
        message = job_key || ' failed without a correlated response.',
        reconciled_at = clock_timestamp()
    where source = 'pg_net_tracked'
      and status in ('running', 'started')
      and started_at < clock_timestamp() - greatest(p_stale_after, interval '2 minutes')
    returning job_key, completed_at, duration_ms, error_message
  ), updated_registry as (
    update public.cron_jobs jobs
    set last_status = 'failed',
        last_failed_at = stale.completed_at,
        last_duration_ms = stale.duration_ms,
        last_message = stale.job_key || ' failed without a correlated response.',
        last_error = stale.error_message,
        updated_at = clock_timestamp()
    from stale
    where jobs.job_key = stale.job_key
    returning jobs.job_key
  )
  select completed_count + count(*) into completed_count from updated_registry;

  return completed_count;
end
$$;


ALTER FUNCTION "private"."reconcile_tracked_edge_requests"("p_stale_after" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."response_declares_failure"("p_content" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  parsed jsonb;
begin
  if nullif(btrim(p_content), '') is null then
    return false;
  end if;

  begin
    parsed := p_content::jsonb;
  exception when others then
    return false;
  end;

  return lower(coalesce(parsed ->> 'success', 'true')) = 'false'
    or lower(coalesce(parsed ->> 'ok', 'true')) = 'false';
end
$$;


ALTER FUNCTION "private"."response_declares_failure"("p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."run_cleanup_expired_auth_email_tokens_cron"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  started_at timestamptz := clock_timestamp();
  deleted_count integer := 0;
  result jsonb;
begin
  deleted_count := public.cleanup_expired_auth_email_tokens();
  result := jsonb_build_object(
    'processed', deleted_count,
    'deleted', deleted_count,
    'fixed', deleted_count,
    'failed', 0
  );

  insert into public.cron_job_runs(job_key, job_name, status, source, started_at, completed_at, finished_at, duration_ms, checked_count, success_count, failed_count, message, details)
  values ('cleanup-expired-auth-email-tokens', 'Cleanup Expired Auth Email Tokens', 'success', 'pg_cron_sql', started_at, clock_timestamp(), clock_timestamp(), greatest(0, floor(extract(epoch from (clock_timestamp() - started_at))*1000)::integer), deleted_count, deleted_count, 0, 'Expired auth email token cleanup completed.', result);

  update public.cron_jobs
  set last_status='success', last_completed_at=clock_timestamp(), last_duration_ms=greatest(0, floor(extract(epoch from (clock_timestamp() - started_at))*1000)::integer), last_message='Expired auth email token cleanup completed.', last_details=result, last_error=null, updated_at=clock_timestamp()
  where job_key='cleanup-expired-auth-email-tokens';

  return result;
exception when others then
  insert into public.cron_job_runs(job_key, job_name, status, source, started_at, completed_at, finished_at, duration_ms, failed_count, error_message, message, details)
  values ('cleanup-expired-auth-email-tokens', 'Cleanup Expired Auth Email Tokens', 'failed', 'pg_cron_sql', started_at, clock_timestamp(), clock_timestamp(), greatest(0, floor(extract(epoch from (clock_timestamp() - started_at))*1000)::integer), 1, sqlerrm, 'Expired auth email token cleanup failed.', jsonb_build_object('failed',1));
  update public.cron_jobs set last_status='failed', last_failed_at=clock_timestamp(), last_error=sqlerrm, last_message='Expired auth email token cleanup failed.', updated_at=clock_timestamp() where job_key='cleanup-expired-auth-email-tokens';
  raise;
end;
$$;


