CREATE OR REPLACE FUNCTION "public"."admin_get_pg_cron_snapshot"() RETURNS TABLE("jobid" bigint, "jobname" "text", "schedule" "text", "active" boolean, "command_kind" "text", "last_status" "text", "last_start_time" timestamp with time zone, "last_end_time" timestamp with time zone, "last_return_message" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with recent_runs as materialized (
    select
      d.runid,
      d.jobid,
      d.status,
      d.start_time,
      d.end_time,
      d.return_message
    from cron.job_run_details d
    order by d.runid desc
    limit 25000
  ),
  latest_run as (
    select distinct on (r.jobid)
      r.jobid,
      r.runid,
      r.status,
      r.start_time,
      r.end_time,
      r.return_message
    from recent_runs r
    order by r.jobid, r.runid desc
  )
  select
    j.jobid::bigint,
    j.jobname::text,
    j.schedule::text,
    j.active,
    case when j.command ilike '%functions/v1/%' or j.command ilike '%net.http%' then 'http' else 'sql' end::text,
    r.status::text,
    r.start_time,
    r.end_time,
    r.return_message::text
  from cron.job j
  left join latest_run r on r.jobid = j.jobid
  order by j.jobname;
$$;


ALTER FUNCTION "public"."admin_get_pg_cron_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_health_kpis"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_source" "text" DEFAULT NULL::"text") RETURNS TABLE("total_searches" bigint, "healthy_searches" bigint, "searches_with_issues" bigint, "failed_searches" bigint, "slow_searches" bigint, "no_results" bigint, "no_pairs" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with classified as (
    select s.success = false as failed,
      coalesce(s.had_issue, false) or s.success = false or s.no_results_reason is not null or s.no_pairs_reason is not null or exists (
        -- Legacy fallback: normalized query plus a narrow time window. Future writers should
        -- put search_event_id in health.debug for direct correlation.
        select 1 from public.search_health_events h where h.created_at between s.created_at - interval '5 minutes' and s.created_at + interval '5 minutes'
          and lower(regexp_replace(trim(h.raw_query), '\s+', ' ', 'g')) = lower(regexp_replace(trim(coalesce(s.normalized_query,s.raw_query)), '\s+', ' ', 'g'))
      ) as issue,
      s.timing_ms > 5000 or lower(coalesce(s.speed_status, '')) = any(array['slow','critical','failed','timeout','degraded']) as slow,
      s.no_results_reason is not null or s.result_count = 0 as no_results,
      s.no_pairs_reason is not null as no_pairs
    from public.search_events s where s.created_at >= p_from and s.created_at <= p_to and (p_source is null or s.source = p_source)
  ) select count(*), count(*) filter (where not failed and not issue), count(*) filter (where issue), count(*) filter (where failed), count(*) filter (where slow), count(*) filter (where no_results), count(*) filter (where no_pairs) from classified;
$$;


ALTER FUNCTION "public"."admin_search_health_kpis"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_profile_review_queue"("p_search" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_page_size" integer DEFAULT 25, "p_offset" integer DEFAULT 0) RETURNS TABLE("location_id" "uuid", "name" "text", "location_type" "text", "state" "text", "city" "text", "primary_domain" "text", "canonical_terms" "text"[], "confidence" numeric, "profile_version" integer, "generated_at" timestamp with time zone, "severity" "text", "blocking_reasons" "text"[], "warning_reasons" "text"[], "filtered_count" bigint, "total_needs_review_count" bigint, "blocking_count" bigint, "warning_count" bigint, "reason_options" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with reviewed as (
    select
      p.location_id,
      coalesce(l.name, l.restaurant_name, l.activity_name, p.location_id::text) as name,
      coalesce(l.location_type, '') as location_type,
      coalesce(l.state, '') as state,
      coalesce(l.city, l.borough, '') as city,
      coalesce(p.primary_domain, '') as primary_domain,
      coalesce(p.canonical_terms, '{}'::text[]) as canonical_terms,
      p.confidence,
      p.profile_version,
      p.generated_at,
      array(
        select distinct reason
        from unnest(
          coalesce(p.review_reasons, '{}'::text[])
          || case when nullif(p.primary_domain, '') is null then array['Missing primary domain'] else '{}'::text[] end
          || case when cardinality(coalesce(p.canonical_terms, '{}'::text[])) = 0 then array['Missing canonical terms'] else '{}'::text[] end
          || case when coalesce(p.profile_version, 0) < 4 then array['Stale profile version'] else '{}'::text[] end
        ) as reason
        where reason ~* '(missing primary domain|domain conflict|unsupported domain|restaurant.*activity.*conflict|nightlife.*family|missing canonical terms|no canonical terms|invalid classification|stale profile version)'
        order by reason
      ) as blocking_reasons,
      array(
        select distinct reason
        from unnest(
          coalesce(p.review_reasons, '{}'::text[])
          || case when coalesce(p.confidence, 0) < 0.55 then array['Low confidence'] else '{}'::text[] end
        ) as reason
        where reason <> ''
          and not (reason ~* '(missing primary domain|domain conflict|unsupported domain|restaurant.*activity.*conflict|nightlife.*family|missing canonical terms|no canonical terms|invalid classification|stale profile version)')
        order by reason
      ) as warning_reasons,
      concat_ws(' ', l.name, l.restaurant_name, l.activity_name, l.location_type, l.city, l.borough, l.state, p.primary_domain, array_to_string(p.canonical_terms, ' ')) as search_blob
    from public.location_search_profiles p
    left join public.locations l on l.id = p.location_id
    where p.needs_review is true
  ), classified as (
    select *, case when cardinality(blocking_reasons) > 0 then 'blocking' when cardinality(warning_reasons) > 0 then 'warning' else 'none' end as review_severity
    from reviewed
  ), filtered as (
    select * from classified
    where (coalesce(nullif(trim(p_search), ''), '') = '' or search_blob ilike '%' || replace(replace(replace(trim(p_search), '\\', '\\\\'), '%', '\%'), '_', '\_') || '%' escape '\')
      and (coalesce(nullif(p_severity, ''), 'all') = 'all' or review_severity = p_severity)
      and (coalesce(nullif(p_reason, ''), '') = '' or p_reason = any(blocking_reasons) or p_reason = any(warning_reasons))
  ), totals as (
    select
      (select count(*) from filtered) as filtered_count,
      (select count(*) from classified) as total_needs_review_count,
      (select count(*) from filtered where review_severity = 'blocking') as blocking_count,
      (select count(*) from filtered where review_severity = 'warning') as warning_count,
      coalesce((select array_agg(distinct reason order by reason) from classified c cross join lateral unnest(c.blocking_reasons || c.warning_reasons) as reason), '{}'::text[]) as reason_options
  )
  , paged as (
    select *
    from filtered
    order by confidence asc nulls first, location_id
    limit least(greatest(p_page_size, 1), 100)
    offset greatest(p_offset, 0)
  )
  select p.location_id, p.name, p.location_type, p.state, p.city, p.primary_domain, p.canonical_terms, p.confidence, p.profile_version, p.generated_at,
    p.review_severity as severity, p.blocking_reasons, p.warning_reasons,
    t.filtered_count, t.total_needs_review_count, t.blocking_count, t.warning_count, t.reason_options
  from paged p cross join totals t
  union all
  select null::uuid, null::text, null::text, null::text, null::text, null::text, '{}'::text[], null::numeric, null::integer, null::timestamptz,
    'none'::text, '{}'::text[], '{}'::text[], t.filtered_count, t.total_needs_review_count, t.blocking_count, t.warning_count, t.reason_options
  from totals t
  where not exists (select 1 from paged);
$$;


ALTER FUNCTION "public"."admin_search_profile_review_queue"("p_search" "text", "p_severity" "text", "p_reason" "text", "p_page_size" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_pg_cron_active"("p_job_name" "text", "p_active" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_job_id bigint;
begin
  select j.jobid into v_job_id from cron.job j where j.jobname = p_job_name limit 1;
  if v_job_id is null then return false; end if;
  perform cron.alter_job(v_job_id, active => p_active);
  return true;
end;
$$;


ALTER FUNCTION "public"."admin_set_pg_cron_active"("p_job_name" "text", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_reservation_booking_confirmation_mode"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_mode text;
begin
  if coalesce(new.source, '') not in ('theouthaven', 'theouthaven_reschedule') then
    return new;
  end if;

  select coalesce(reservation_settings #>> '{booking,confirmationMode}', 'instant')
    into v_mode
  from public.locations
  where id = new.location_id;

  if v_mode = 'approval' then
    new.status := 'pending';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_reservation_booking_confirmation_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_reservation_guarantee_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_enabled boolean;
  v_cutoff integer;
  v_grace integer;
  v_late_type text;
  v_late_cents integer;
  v_no_show_type text;
  v_no_show_cents integer;
begin
  if coalesce(new.source, '') not in ('theouthaven','theouthaven_reschedule') then
    return new;
  end if;

  select
    reservation_guarantee_enabled,
    reservation_cancel_cutoff_hours,
    reservation_no_show_grace_minutes,
    reservation_late_cancel_fee_type,
    reservation_late_cancel_fee_cents,
    reservation_no_show_fee_type,
    reservation_no_show_fee_cents
  into
    v_enabled,
    v_cutoff,
    v_grace,
    v_late_type,
    v_late_cents,
    v_no_show_type,
    v_no_show_cents
  from public.locations
  where id = new.location_id;

  new.no_show_grace_minutes := coalesce(v_grace, 15);
  new.deposit_required := false;
  new.deposit_amount := 0;
  new.deposit_status := 'not_required';

  if coalesce(v_enabled, false) then
    new.guarantee_required := true;
    new.guarantee_status := case when coalesce(new.guarantee_status, 'not_required') = 'active' then 'active' else 'pending' end;
    new.guarantee_cancel_cutoff_hours := coalesce(v_cutoff, 6);
    new.guarantee_late_cancel_fee_type := coalesce(v_late_type, 'per_person');
    new.guarantee_late_cancel_fee_cents := coalesce(v_late_cents, 1000);
    new.guarantee_no_show_fee_type := coalesce(v_no_show_type, 'per_person');
    new.guarantee_no_show_fee_cents := coalesce(v_no_show_cents, 2000);
    if new.guarantee_status <> 'active' then
      new.status := 'pending';
    end if;
  else
    new.guarantee_required := false;
    new.guarantee_status := 'not_required';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_reservation_guarantee_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_location_website_ai_generation"("p_location_id" "uuid", "p_generation_type" "text", "p_provider" "text", "p_model" "text", "p_request_key" "text", "p_estimated_cost_micros" bigint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_policy public.business_website_ai_policy%rowtype;
  v_website_id uuid;
  v_month_start timestamptz := date_trunc('month', now());
  v_running integer := 0;
  v_initial integer := 0;
  v_redesign integer := 0;
  v_cost bigint := 0;
  v_usage_id uuid;
begin
  if p_generation_type not in ('design_match', 'initial_build', 'full_redesign', 'section_rewrite', 'seo_copy') then
    raise exception 'website_ai_generation_type_not_allowed';
  end if;

  if coalesce(p_estimated_cost_micros, 0) < 0 then
    raise exception 'website_ai_invalid_cost_estimate';
  end if;

  insert into public.business_website_ai_policy(location_id)
  values (p_location_id)
  on conflict (location_id) do nothing;

  select * into v_policy
  from public.business_website_ai_policy
  where location_id = p_location_id
  for update;

  select id into v_website_id
  from public.business_websites
  where location_id = p_location_id
  limit 1;

  if v_website_id is null then
    raise exception 'website_ai_website_not_found';
  end if;

  select count(*) into v_running
  from public.business_website_ai_usage
  where location_id = p_location_id and status = 'running';

  if v_running >= v_policy.max_concurrent_generations then
    raise exception 'website_ai_generation_already_running';
  end if;

  if p_generation_type = 'initial_build' then
    select count(*) into v_initial
    from public.business_website_ai_usage
    where location_id = p_location_id
      and generation_type = 'initial_build'
      and status = 'succeeded';
    if v_initial >= v_policy.initial_builds_included then
      raise exception 'website_ai_initial_build_limit_reached';
    end if;
  end if;

  if p_generation_type = 'full_redesign' then
    select count(*) into v_redesign
    from public.business_website_ai_usage
    where location_id = p_location_id
      and generation_type = 'full_redesign'
      and status = 'succeeded'
      and created_at >= v_month_start;
    if v_redesign >= v_policy.full_redesigns_per_month then
      raise exception 'website_ai_redesign_limit_reached';
    end if;
  end if;

  select coalesce(sum(estimated_cost_micros), 0)::bigint into v_cost
  from public.business_website_ai_usage
  where location_id = p_location_id
    and status in ('running', 'succeeded')
    and created_at >= v_month_start;

  if v_cost + coalesce(p_estimated_cost_micros, 0) > v_policy.max_estimated_cost_micros_per_location_month then
    raise exception 'website_ai_monthly_cost_limit_reached';
  end if;

  insert into public.business_website_ai_usage(
    website_id,
    location_id,
    generation_type,
    status,
    provider,
    model,
    request_key,
    estimated_cost_micros
  ) values (
    v_website_id,
    p_location_id,
    p_generation_type,
    'running',
    nullif(p_provider, ''),
    nullif(p_model, ''),
    nullif(p_request_key, ''),
    coalesce(p_estimated_cost_micros, 0)
  )
  returning id into v_usage_id;

  return v_usage_id;
end;
$$;


ALTER FUNCTION "public"."begin_location_website_ai_generation"("p_location_id" "uuid", "p_generation_type" "text", "p_provider" "text", "p_model" "text", "p_request_key" "text", "p_estimated_cost_micros" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."book_large_group_live"("p_location_id" "uuid", "p_location_type" "text", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_reservation_date" "date", "p_reservation_time" time without time zone, "p_party_size" integer, "p_duration_minutes" integer, "p_occasion" "text", "p_prix_fixe_interest" "text", "p_notes" "text", "p_customer_token" "text", "p_customer_token_expires_at" timestamp with time zone) RETURNS TABLE("reservation_id" "uuid", "reservation_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_day integer;
  v_open time;
  v_close time;
  v_slot_duration integer := 90;
  v_max_capacity integer := 100;
  v_max_party_size integer := 20;
  v_is_closed boolean := false;
  v_used integer := 0;
  v_locked integer := 0;
  v_id uuid;
begin
  if p_party_size < 6 then raise exception 'Large group bookings require at least 6 guests'; end if;
  if p_duration_minutes < 30 or p_duration_minutes > 720 then raise exception 'Invalid duration'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_location_id::text || '|' || p_reservation_date::text || '|' || p_reservation_time::text, 0));

  v_day := extract(dow from p_reservation_date)::integer;
  select open_time, close_time, coalesce(slot_duration_minutes,90), coalesce(max_capacity,100), coalesce(max_party_size,20), coalesce(is_closed,false)
    into v_open, v_close, v_slot_duration, v_max_capacity, v_max_party_size, v_is_closed
  from public.location_capacity
  where location_id = p_location_id and day_of_week = v_day
  limit 1;

  if v_is_closed then raise exception 'Location is closed on this day'; end if;
  if p_party_size > v_max_party_size then raise exception 'Party size exceeds the configured maximum of %', v_max_party_size; end if;
  if v_open is not null and v_close is not null then
    if p_reservation_time < v_open or (p_reservation_time + make_interval(mins => p_duration_minutes)) > v_close then
      raise exception 'Requested time is outside the location availability window';
    end if;
  end if;

  select coalesce(sum(coalesce(r.party_size,2)),0)::integer into v_used
  from public.location_reservations r
  where r.location_id = p_location_id
    and r.reservation_date = p_reservation_date
    and r.status in ('pending','confirmed','checked_in','waiting','arrived','seated')
    and p_reservation_time < (r.reservation_time + make_interval(mins => coalesce(r.duration_minutes,r.turn_time_minutes,v_slot_duration)))
    and r.reservation_time < (p_reservation_time + make_interval(mins => p_duration_minutes));

  delete from public.reservation_slot_locks where expires_at < now();
  select coalesce(sum(coalesce(l.party_size,2)),0)::integer into v_locked
  from public.reservation_slot_locks l
  where l.location_id = p_location_id
    and l.reservation_date = p_reservation_date
    and l.reservation_time = p_reservation_time
    and l.expires_at > now();

  if v_used + v_locked + p_party_size > v_max_capacity then
    raise exception 'That time is no longer available for this party size';
  end if;

  insert into public.location_reservations (
    location_id, location_type, customer_name, customer_email, customer_phone,
    reservation_date, reservation_time, party_size, status, source, booking_kind,
    occasion, prix_fixe_interest, group_booking_notes, special_request, special_requests,
    duration_minutes, customer_token, customer_token_expires_at, updated_at
  ) values (
    p_location_id, coalesce(nullif(p_location_type,''),'restaurant'), p_customer_name, p_customer_email, nullif(p_customer_phone,''),
    p_reservation_date, p_reservation_time, p_party_size, 'confirmed', 'public_large_group_live', 'large_group',
    nullif(p_occasion,''), p_prix_fixe_interest, nullif(p_notes,''),
    concat_ws(E'\n', case when nullif(p_occasion,'') is not null then 'Occasion: ' || p_occasion end, 'Prix-fixe interest: ' || p_prix_fixe_interest, nullif(p_notes,'')),
    concat_ws(E'\n', case when nullif(p_occasion,'') is not null then 'Occasion: ' || p_occasion end, 'Prix-fixe interest: ' || p_prix_fixe_interest, nullif(p_notes,'')),
    p_duration_minutes, p_customer_token, p_customer_token_expires_at, now()
  ) returning id into v_id;

  return query select v_id, 'confirmed'::text;
end;
$$;


ALTER FUNCTION "public"."book_large_group_live"("p_location_id" "uuid", "p_location_type" "text", "p_customer_name" "text", "p_customer_email" "text", "p_customer_phone" "text", "p_reservation_date" "date", "p_reservation_time" time without time zone, "p_party_size" integer, "p_duration_minutes" integer, "p_occasion" "text", "p_prix_fixe_interest" "text", "p_notes" "text", "p_customer_token" "text", "p_customer_token_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_user_access_workspace_location"("p_user_id" "uuid", "p_location_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_profile public.team_member_profiles%rowtype;
  v_is_admin boolean;
begin
  select exists(select 1 from public.admin_users where user_id = p_user_id and role in ('superadmin','admin','manager')) into v_is_admin;
  if v_is_admin then return true; end if;
  select * into v_profile from public.team_member_profiles where user_id = p_user_id and status in ('active','training') limit 1;
  if not found then return false; end if;
  if exists(select 1 from public.locations where id = p_location_id and (created_by_team_member_id = v_profile.id or created_source in ('workspace','ambassador'))) then return true; end if;
  if exists(select 1 from public.ambassador_site_visits where user_id = p_user_id and location_id = p_location_id) then return true; end if;
  if exists(select 1 from public.ambassador_social_outreach where user_id = p_user_id and location_id = p_location_id) then return true; end if;
  if exists(select 1 from public.team_follow_ups where user_id = p_user_id and location_id = p_location_id) then return true; end if;
  if exists(select 1 from public.workspace_tasks where assigned_to_user_id = p_user_id and location_id = p_location_id) then return true; end if;
  return false;
end;
$$;


ALTER FUNCTION "public"."can_user_access_workspace_location"("p_user_id" "uuid", "p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_location_analytics"("location_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  user_email text;
  has_access boolean := false;
begin
  if public.is_location_analytics_admin() then
    return true;
  end if;

  user_email := lower(coalesce(auth.jwt() ->> 'email', ''));

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'locations'
      and column_name = 'owner_user_id'
  ) then
    execute '
      select exists (
        select 1
        from public.locations
        where id = $1
          and owner_user_id = auth.uid()
      )'
    into has_access
    using location_uuid;

    if has_access then
      return true;
    end if;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'locations'
      and column_name = 'user_id'
  ) then
    execute '
      select exists (
        select 1
        from public.locations
        where id = $1
          and user_id = auth.uid()
      )'
    into has_access
    using location_uuid;

    if has_access then
      return true;
    end if;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'locations'
      and column_name = 'claimed_by_user_id'
  ) then
    execute '
      select exists (
        select 1
        from public.locations
        where id = $1
          and claimed_by_user_id = auth.uid()
      )'
    into has_access
    using location_uuid;

    if has_access then
      return true;
    end if;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'locations'
      and column_name = 'claimed_by_email'
  ) then
    execute '
      select exists (
        select 1
        from public.locations
        where id = $1
          and lower(coalesce(claimed_by_email, '''')) = $2
      )'
    into has_access
    using location_uuid, user_email;

    if has_access then
      return true;
    end if;
  end if;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'locations'
      and column_name = 'owner_email'
  ) then
    execute '
      select exists (
        select 1
        from public.locations
        where id = $1
          and lower(coalesce(owner_email, '''')) = $2
      )'
    into has_access
    using location_uuid, user_email;

    if has_access then
      return true;
    end if;
  end if;

  return false;
end;
$_$;


ALTER FUNCTION "public"."can_view_location_analytics"("location_uuid" "uuid") OWNER TO "postgres";


