    "cover_letter" "text",
    "status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "stage" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "score" numeric,
    "source" "text" DEFAULT 'careers_page'::"text",
