    "last_contacted_at" timestamp with time zone,
    "submitted_at" timestamp with time zone DEFAULT "now"(),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "career_applications_stage_check" CHECK (("stage" = ANY (ARRAY['submitted'::"text", 'portfolio_review'::"text", 'under_review'::"text", 'shortlisted'::"text", 'interview_requested'::"text", 'interview_scheduled'::"text", 'interview_completed'::"text", 'content_test'::"text", 'offer_pending'::"text", 'offer_sent'::"text", 'hired'::"text", 'not_selected'::"text", 'withdrawn'::"text", 'talent_pool'::"text"])))
);


ALTER TABLE "public"."career_applications" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."career_set_application_stage"("p_application_id" "uuid", "p_stage" "text", "p_changed_by" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."career_applications"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare v_old_stage text; v_row public.career_applications;
begin
  if p_stage not in ('submitted','portfolio_review','under_review','shortlisted','interview_requested','interview_scheduled','interview_completed','content_test','offer_pending','offer_sent','hired','not_selected','withdrawn','talent_pool') then raise exception 'invalid career application stage'; end if;
  select stage into v_old_stage from public.career_applications where id = p_application_id for update;
  if not found then raise exception 'career application not found'; end if;
  update public.career_applications set stage = p_stage, status = p_stage, updated_at = now() where id = p_application_id returning * into v_row;
  if v_old_stage is distinct from p_stage then insert into public.career_application_stage_history(application_id,from_stage,to_stage,changed_by,change_reason) values (p_application_id,v_old_stage,p_stage,p_changed_by,coalesce(p_reason,'Career workflow stage update')); end if;
  return v_row;
end; $$;


