    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "priority" integer DEFAULT 100 NOT NULL,
    "reasons" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "api_calls" integer DEFAULT 0 NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "suggestion_id" "uuid",
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "match_diagnostics" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "location_enrichment_run_items_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'review'::"text", 'completed'::"text", 'unchanged'::"text", 'skipped'::"text", 'no_match'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


