COMMENT ON COLUMN "public"."location_enrichment_run_items"."match_diagnostics" IS 'Structured Google match diagnostics for rejected candidates, including confidence, thresholds, evidence, and the best candidate.';



CREATE OR REPLACE FUNCTION "public"."claim_location_enrichment_items"("p_run_id" "uuid", "p_limit" integer DEFAULT 5) RETURNS SETOF "public"."location_enrichment_run_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select id
    from public.location_enrichment_run_items
    where run_id = p_run_id and status = 'pending'
    order by priority asc, created_at asc
    limit greatest(1, least(p_limit,25))
    for update skip locked
  )
  update public.location_enrichment_run_items i
     set status='processing', attempts=attempts+1, started_at=coalesce(started_at,now()), updated_at=now()
  from candidates c
  where i.id = c.id
  returning i.*;
end $$;


