    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "error" "text",
    "review_reasons" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "profile_version" integer,
    "profile_hash" "text",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "lease_expires_at" timestamp with time zone,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_owner" "text",
    "last_error" "jsonb",
    "result" "jsonb",
    CONSTRAINT "location_search_profile_run_items_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text", 'skipped'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."location_search_profile_run_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_location_search_profile_items"("p_worker" "text", "p_limit" integer DEFAULT 50, "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."location_search_profile_run_items"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  with candidates as (
    select i.id
    from public.location_search_profile_run_items i
    join public.location_search_profile_runs r
      on r.id = i.run_id
    where r.cancellation_requested_at is null
      and i.attempts < i.max_attempts
      and (
        (
          i.status in ('pending', 'failed')
          and i.available_at <= now()
        )
        or (
          i.status = 'processing'
          and i.lease_expires_at < now()
        )
      )
    order by i.created_at
    for update skip locked
    limit least(
      greatest(coalesce(p_limit, 50), 1),
      250
    )
  ),
  claimed as (
    update public.location_search_profile_run_items i
    set
      status = 'processing',
      attempts = i.attempts + 1,
      attempt_count = greatest(
        coalesce(i.attempt_count, 0),
        i.attempts + 1
      ),
      lease_owner = p_worker,
      locked_by = p_worker,
      locked_at = now(),
      lease_expires_at =
        now() + make_interval(
          secs => greatest(coalesce(p_lease_seconds, 120), 30)
        ),
      started_at = coalesce(i.started_at, now()),
      updated_at = now()
    from candidates c
    where i.id = c.id
    returning i.*
  )
  select *
  from claimed;
$$;


ALTER FUNCTION "public"."claim_location_search_profile_items"("p_worker" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


