    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "location_search_profile_refresh_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'succeeded'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."location_search_profile_refresh_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."location_search_profile_refresh_queue" IS 'Durable queue for rebuilding canonical search profiles, including activity coverage recovery.';



CREATE OR REPLACE FUNCTION "public"."claim_location_search_profile_refresh_queue"("p_worker" "text", "p_limit" integer DEFAULT 50, "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."location_search_profile_refresh_queue"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  with candidates as (
    select q.id
    from public.location_search_profile_refresh_queue q
    where q.attempts < q.max_attempts
      and (
        (
          q.status = 'pending'
          and q.available_at <= now()
        )
        or (
          q.status = 'processing'
          and q.lease_expires_at is not null
          and q.lease_expires_at < now()
        )
      )
    order by
      q.available_at,
      q.created_at,
      q.id
    for update skip locked
    limit least(
      greatest(coalesce(p_limit, 50), 1),
      250
    )
  ),
  claimed as (
    update public.location_search_profile_refresh_queue q
    set
      status = 'processing',
      attempts = q.attempts + 1,
      locked_at = now(),
      locked_by = p_worker,
      lease_expires_at =
        now()
        + make_interval(
            secs => greatest(
              coalesce(p_lease_seconds, 120),
              30
            )
          ),
      updated_at = now()
    from candidates c
    where q.id = c.id
    returning q.*
  )
  select *
  from claimed;
$$;


ALTER FUNCTION "public"."claim_location_search_profile_refresh_queue"("p_worker" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


