    CONSTRAINT "locations_deposit_opt_in_check" CHECK (((NOT "deposits_enabled") OR (COALESCE("default_deposit_amount", (0)::numeric) >= 0.50))),
    CONSTRAINT "locations_description_backfill_status_check" CHECK ((("description_backfill_status" IS NULL) OR ("description_backfill_status" = ANY (ARRAY['generated'::"text", 'skipped'::"text", 'failed'::"text"])))),
    CONSTRAINT "locations_duplicate_self_check" CHECK ((("duplicate_of" IS NULL) OR ("duplicate_of" <> "id"))),
    CONSTRAINT "locations_duplicate_state_check" CHECK (((("duplicate_of" IS NULL) AND (COALESCE("duplicate_status", ''::"text") <> 'duplicate'::"text")) OR (("duplicate_of" IS NOT NULL) AND ("duplicate_status" = 'duplicate'::"text") AND (COALESCE("is_searchable", false) = false) AND (COALESCE("is_hidden", false) = true) AND (COALESCE("publish_ready", false) = false)))),
    CONSTRAINT "locations_google_business_status_check" CHECK ((("google_business_status" IS NULL) OR ("google_business_status" = ANY (ARRAY['BUSINESS_STATUS_UNSPECIFIED'::"text", 'OPERATIONAL'::"text", 'CLOSED_TEMPORARILY'::"text", 'CLOSED_PERMANENTLY'::"text", 'FUTURE_OPENING'::"text"])))),
    CONSTRAINT "locations_included_domain_connection_status_check" CHECK (("included_domain_connection_status" = ANY (ARRAY['not_started'::"text", 'pending_dns'::"text", 'pending_verification'::"text", 'connected'::"text", 'failed'::"text"]))),
    CONSTRAINT "locations_large_group_confirmation_mode_check" CHECK (("large_group_confirmation_mode" = ANY (ARRAY['instant'::"text", 'approval'::"text"]))),
    CONSTRAINT "locations_large_group_deposit_type_check" CHECK (("large_group_deposit_type" = ANY (ARRAY['flat'::"text", 'per_person'::"text"]))),
    CONSTRAINT "locations_large_group_fee_type_check" CHECK ((("large_group_late_cancel_fee_type" = ANY (ARRAY['flat'::"text", 'per_person'::"text"])) AND ("large_group_no_show_fee_type" = ANY (ARRAY['flat'::"text", 'per_person'::"text"])))),
    CONSTRAINT "locations_large_group_payment_mode_check" CHECK (("large_group_payment_mode" = ANY (ARRAY['none'::"text", 'card_guarantee'::"text", 'deposit'::"text"]))),
    CONSTRAINT "locations_large_group_prix_fixe_mode_check" CHECK (("large_group_prix_fixe_mode" = ANY (ARRAY['none'::"text", 'optional'::"text", 'required'::"text"]))),
    CONSTRAINT "locations_location_type_check" CHECK (("location_type" = ANY (ARRAY['restaurant'::"text", 'activity'::"text"]))),
