    CONSTRAINT "locations_profile_managed_by_check" CHECK (("profile_managed_by" = ANY (ARRAY['system'::"text", 'import'::"text", 'google'::"text", 'admin'::"text", 'owner'::"text"]))),
    CONSTRAINT "locations_reservation_fee_type_check" CHECK ((("reservation_late_cancel_fee_type" = ANY (ARRAY['flat'::"text", 'per_person'::"text"])) AND ("reservation_no_show_fee_type" = ANY (ARRAY['flat'::"text", 'per_person'::"text"])))),
    CONSTRAINT "locations_reservation_outreach_status_check" CHECK (("reservation_outreach_status" = ANY (ARRAY['not_contacted'::"text", 'contacted'::"text", 'interested'::"text", 'not_interested'::"text", 'claimed'::"text", 'onboarded'::"text"]))),
    CONSTRAINT "locations_reservation_source_check" CHECK (("reservation_source" = ANY (ARRAY['internal'::"text", 'external'::"text", 'both'::"text", 'none'::"text"]))),
    CONSTRAINT "locations_reserve_policy_amounts_check" CHECK (((("reservation_cancel_cutoff_hours" >= 0) AND ("reservation_cancel_cutoff_hours" <= 168)) AND ("reservation_late_cancel_fee_cents" >= 0) AND ("reservation_no_show_fee_cents" >= 0) AND (("large_group_min_party_size" >= 2) AND ("large_group_min_party_size" <= 500)) AND (("large_group_max_party_size" >= "large_group_min_party_size") AND ("large_group_max_party_size" <= 500)) AND ("large_group_deposit_amount_cents" >= 0) AND (("large_group_default_duration_minutes" >= 30) AND ("large_group_default_duration_minutes" <= 1440)))),
    CONSTRAINT "locations_reserve_policy_timing_check" CHECK (((("reservation_no_show_grace_minutes" >= 0) AND ("reservation_no_show_grace_minutes" <= 180)) AND (("large_group_cancel_cutoff_hours" >= 0) AND ("large_group_cancel_cutoff_hours" <= 336)) AND (("large_group_no_show_grace_minutes" >= 0) AND ("large_group_no_show_grace_minutes" <= 180)) AND ("large_group_late_cancel_fee_cents" >= 0) AND ("large_group_no_show_fee_cents" >= 0))),
    CONSTRAINT "locations_stripe_connect_account_api_version_check" CHECK ((("stripe_connect_account_api_version" IS NULL) OR ("stripe_connect_account_api_version" = ANY (ARRAY['v1'::"text", 'v2'::"text"])))),
    CONSTRAINT "locations_stripe_connect_due_counts_check" CHECK ((("stripe_connect_currently_due_count" >= 0) AND ("stripe_connect_past_due_count" >= 0) AND ("stripe_connect_future_due_count" >= 0)))
);


