CREATE TABLE IF NOT EXISTS "public"."search_anchor_reconciliation_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "location_id" "uuid" NOT NULL,
    "event_type" "text" DEFAULT 'update'::"text" NOT NULL,
    "reason_code" "text" DEFAULT 'location_changed'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "priority" integer DEFAULT 50 NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "processed_at" timestamp with time zone,
    "last_error" "text",
    "source_updated_at" timestamp with time zone,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "search_anchor_reconciliation_attempts_check" CHECK ((("attempts" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 20)))),
    CONSTRAINT "search_anchor_reconciliation_event_type_check" CHECK (("event_type" = ANY (ARRAY['insert'::"text", 'update'::"text", 'delete'::"text", 'manual'::"text", 'nightly_reconciliation'::"text"]))),
    CONSTRAINT "search_anchor_reconciliation_priority_check" CHECK ((("priority" >= 0) AND ("priority" <= 100))),
    CONSTRAINT "search_anchor_reconciliation_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text", 'dead_letter'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."search_anchor_reconciliation_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_search_anchor_reconciliation_batch"("p_limit" integer DEFAULT 100, "p_worker" "text" DEFAULT 'search-anchor-reconciliation'::"text") RETURNS SETOF "public"."search_anchor_reconciliation_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  with claimable as (
    select q.id
    from public.search_anchor_reconciliation_queue q
    where q.status in ('pending', 'failed')
      and q.available_at <= now()
      and q.attempts < q.max_attempts
      and (
        q.locked_at is null
        or q.locked_at < now() - interval '15 minutes'
      )
    order by
      q.priority desc,
      q.available_at asc,
      q.created_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 250))
  )
  update public.search_anchor_reconciliation_queue q
  set
    status = 'processing',
    attempts = q.attempts + 1,
    locked_at = now(),
    locked_by = coalesce(
      nullif(trim(p_worker), ''),
      'search-anchor-reconciliation'
    ),
    last_error = null,
    updated_at = now()
  from claimable
  where q.id = claimable.id
  returning q.*;
end;
$$;


ALTER FUNCTION "public"."claim_search_anchor_reconciliation_batch"("p_limit" integer, "p_worker" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."worker_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_type" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "payload_version" integer DEFAULT 1 NOT NULL,
    "result" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "checkpoint" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "idempotency_key" "text",
    "priority" integer DEFAULT 100 NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "progress_current" integer DEFAULT 0 NOT NULL,
    "progress_total" integer,
    "run_after" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_owner" "text",
    "lease_expires_at" timestamp with time zone,
    "heartbeat_at" timestamp with time zone,
    "parent_job_id" "uuid",
    "created_by_label" "text",
    "created_by" "uuid",
    "last_error" "text",
    "cancellation_requested_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    CONSTRAINT "worker_jobs_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "worker_jobs_max_attempts_check" CHECK (("max_attempts" > 0)),
    CONSTRAINT "worker_jobs_payload_version_check" CHECK (("payload_version" > 0)),
    CONSTRAINT "worker_jobs_progress_bounds_check" CHECK ((("progress_total" IS NULL) OR ("progress_current" <= "progress_total"))),
    CONSTRAINT "worker_jobs_progress_current_check" CHECK (("progress_current" >= 0)),
    CONSTRAINT "worker_jobs_progress_total_check" CHECK ((("progress_total" IS NULL) OR ("progress_total" >= 0))),
    CONSTRAINT "worker_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'succeeded'::"text", 'failed'::"text", 'dead_letter'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."worker_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_worker_jobs"("p_worker" "text", "p_limit" integer DEFAULT 5, "p_job_types" "text"[] DEFAULT NULL::"text"[], "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."worker_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select id
    from public.worker_jobs
    where (
      (status = 'queued' and run_after <= now())
      or
      (status = 'running' and lease_expires_at is not null and lease_expires_at <= now())
    )
      and (p_job_types is null or job_type = any(p_job_types))
    order by priority asc, run_after asc, created_at asc
    limit greatest(1, least(p_limit, 25))
    for update skip locked
  )
  update public.worker_jobs j
  set
    status = 'running',
    attempt_count = attempt_count + 1,
    started_at = coalesce(started_at, now()),
    updated_at = now(),
    lease_owner = p_worker,
    lease_expires_at = now() + make_interval(secs => p_lease_seconds),
    heartbeat_at = now()
  from candidates c
  where j.id = c.id
  returning j.*;
end
$$;


ALTER FUNCTION "public"."claim_worker_jobs"("p_worker" "text", "p_limit" integer, "p_job_types" "text"[], "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_expired_auth_email_tokens"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  deleted_count integer;
begin
  delete from public.auth_email_tokens
  where expires_at < now() - interval '7 days'
     or used_at < now() - interval '7 days';

  get diagnostics deleted_count = row_count;

  return deleted_count;
end;
$$;


ALTER FUNCTION "public"."cleanup_expired_auth_email_tokens"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_expired_auth_email_tokens"() IS 'Deletes used or expired custom auth email tokens after a retention window.';



CREATE OR REPLACE FUNCTION "public"."cleanup_search_ranking_rollout_data"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  settings
    public.search_ranking_retention_settings%rowtype;
  experiments_deleted integer := 0;
  alerts_deleted integer := 0;
  audit_deleted integer := 0;
begin
  select *
  into settings
  from public.search_ranking_retention_settings
  where id = true;

  if not coalesce(
    settings.enabled,
    false
  ) then
    return jsonb_build_object(
      'enabled',
      false,
      'experiments_deleted',
      0,
      'alerts_deleted',
      0,
      'audit_deleted',
      0
    );
  end if;

  delete from public.search_ranking_experiments
  where created_at
    < now() - make_interval(
      days => settings.experiment_retention_days
    );

  get diagnostics experiments_deleted = row_count;

  delete from public.search_ranking_rollout_alerts
  where created_at
    < now() - make_interval(
      days => settings.alert_retention_days
    )
    and acknowledged_at is not null;

  get diagnostics alerts_deleted = row_count;

  delete from public.search_ranking_rollout_audit_log
  where created_at
    < now() - make_interval(
      days => settings.audit_retention_days
    );

  get diagnostics audit_deleted = row_count;

  return jsonb_build_object(
    'enabled',
    true,
    'experiments_deleted',
    experiments_deleted,
    'alerts_deleted',
    alerts_deleted,
    'audit_deleted',
    audit_deleted
  );
end;
$$;


ALTER FUNCTION "public"."cleanup_search_ranking_rollout_data"() OWNER TO "postgres";


