CREATE OR REPLACE FUNCTION "public"."complete_partner_pro_included_domain"("p_operation_id" "uuid", "p_gateway_order_id" "text", "p_gateway_response_code" "text", "p_gateway_expiration_date" timestamp with time zone) RETURNS "public"."domain_registration_operations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_operation public.domain_registration_operations%rowtype;
begin
  select * into v_operation from public.domain_registration_operations where id=p_operation_id for update;
  if not found then raise exception 'operation_not_found'; end if;
  if v_operation.status='active' then return v_operation; end if;
  update public.domain_registration_operations set status='active',gateway_order_id=p_gateway_order_id,gateway_response_code=p_gateway_response_code,gateway_expiration_date=p_gateway_expiration_date,error_code=null,updated_at=now() where id=p_operation_id returning * into v_operation;
  update public.locations set included_domain_name=v_operation.domain_name,included_domain_claimed_at=coalesce(included_domain_claimed_at,now()),included_domain_status='active',included_domain_registered_at=coalesce(included_domain_registered_at,now()),included_domain_renewal_due_at=p_gateway_expiration_date where id=v_operation.location_id;
  return v_operation;
end;$$;


