CREATE OR REPLACE FUNCTION "public"."complete_search_anchor_reconciliation"("p_queue_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.search_anchor_reconciliation_queue
  set
    status = 'completed',
    processed_at = now(),
    locked_at = null,
    locked_by = null,
    last_error = null,
    payload = payload || coalesce(p_payload, '{}'::jsonb),
    updated_at = now()
  where id = p_queue_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."complete_search_anchor_reconciliation"("p_queue_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_search_ranking_rollout_run"("rollout_run_id" "uuid", "actor_user_id" "uuid", "final_status" "text", "reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  snapshot jsonb;
begin
  if final_status not in (
    'completed',
    'rolled_back',
    'cancelled'
  ) then
    raise exception
      'Invalid final rollout status';
  end if;

  select to_jsonb(r)
  into snapshot
  from
    public.search_ranking_rollout_completion_readiness_v1 r
  limit 1;

  update public.search_ranking_rollout_runs
  set
    status = final_status,
    completed_at = now(),
    completion_reason = reason,
    final_snapshot = coalesce(
      snapshot,
      '{}'::jsonb
    ),
    updated_at = now()
  where id = rollout_run_id
    and status = 'active';

  if not found then
    raise exception
      'Active rollout run not found';
  end if;

  insert into public.search_ranking_rollout_audit_log (
    rollout_run_id,
    actor_user_id,
    action,
    reason,
    metadata
  )
  values (
    rollout_run_id,
    actor_user_id,
    'rollout_run_' || final_status,
    reason,
    coalesce(
      snapshot,
      '{}'::jsonb
    )
  );
end;
$$;


ALTER FUNCTION "public"."complete_search_ranking_rollout_run"("rollout_run_id" "uuid", "actor_user_id" "uuid", "final_status" "text", "reason" "text") OWNER TO "postgres";


