CREATE OR REPLACE FUNCTION "public"."crm_location_matches_territory"("p_location_id" "uuid", "p_territory_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  loc record;
  scope_type_row record;
begin
  select
    lower(trim(coalesce(market,''))) as market,
    lower(trim(coalesce(state,''))) as state,
    lower(trim(coalesce(city,''))) as city,
    lower(trim(coalesce(zip_code, postal_code, ''))) as zip,
    lower(trim(coalesce(borough,''))) as borough,
    lower(trim(coalesce(neighborhood,''))) as neighborhood
  into loc
  from public.locations
  where id = p_location_id;

  if not found then return false; end if;

  for scope_type_row in
    select distinct scope_type
    from public.crm_territory_scopes
    where territory_id = p_territory_id
  loop
    if not exists (
      select 1
      from public.crm_territory_scopes s
      where s.territory_id = p_territory_id
        and s.scope_type = scope_type_row.scope_type
        and lower(trim(s.normalized_value)) = case s.scope_type
          when 'market' then loc.market
          when 'state' then loc.state
          when 'city' then loc.city
          when 'town' then loc.city
          when 'zip' then loc.zip
          when 'borough' then loc.borough
          when 'neighborhood' then loc.neighborhood
          else '__unsupported__'
        end
    ) then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


ALTER FUNCTION "public"."crm_location_matches_territory"("p_location_id" "uuid", "p_territory_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_normalize_email_array"("input_addresses" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    array_agg(distinct lower(btrim(address)))
      filter (
        where nullif(btrim(address), '') is not null
      ),
    '{}'::text[]
  )
  from unnest(coalesce(input_addresses, '{}'::text[])) as address;
$$;


