CREATE OR REPLACE FUNCTION "public"."crm_snapshot_forecast"("p_snapshot_date" "date" DEFAULT CURRENT_DATE, "p_period_key" "text" DEFAULT "to_char"((CURRENT_DATE)::timestamp with time zone, 'YYYY-MM'::"text")) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare affected integer;
begin
 insert into public.crm_forecast_snapshots(snapshot_date,period_key,owner_user_id,team_key,pipeline_key,pipeline_amount,weighted_amount,best_case_amount,commit_amount,closed_amount,opportunity_count)
 select p_snapshot_date,p_period_key,owner_user_id,assigned_team,pipeline_key,
 coalesce(sum(amount) filter(where status='open' and forecast_category<>'omitted'),0),coalesce(sum(weighted_amount) filter(where status='open' and forecast_category<>'omitted'),0),
 coalesce(sum(amount) filter(where forecast_category='best_case'),0),coalesce(sum(amount) filter(where forecast_category='commit'),0),coalesce(sum(amount) filter(where status='won'),0),count(*)
 from public.crm_opportunities where archived_at is null and expected_close_date >= date_trunc('month',p_snapshot_date)::date and expected_close_date < (date_trunc('month',p_snapshot_date)+interval '1 month')::date group by owner_user_id,assigned_team,pipeline_key
 on conflict(snapshot_date,period_key,coalesce(owner_user_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(team_key,''),coalesce(pipeline_key,'')) do update set pipeline_amount=excluded.pipeline_amount,weighted_amount=excluded.weighted_amount,best_case_amount=excluded.best_case_amount,commit_amount=excluded.commit_amount,closed_amount=excluded.closed_amount,opportunity_count=excluded.opportunity_count,metadata=jsonb_build_object('refreshed_at',now());
 get diagnostics affected=row_count; return affected;
end $$;


ALTER FUNCTION "public"."crm_snapshot_forecast"("p_snapshot_date" "date", "p_period_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."crm_snapshot_forecast"("p_snapshot_date" "date", "p_period_key" "text") IS 'Idempotent daily forecast snapshot; fixed search_path; service role only.';



CREATE OR REPLACE FUNCTION "public"."crm_sync_location_territory_assignments"("p_location_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  root_user uuid;
  root_member uuid;
  terr record;
  access_row record;
begin
  select root_owner_user_id into root_user
  from public.crm_territory_settings
  limit 1;

  if root_user is not null then
    select id into root_member
    from public.team_member_profiles
    where user_id = root_user and status in ('active','training')
    limit 1;

    if root_member is not null then
      insert into public.team_location_assignments(
        location_id, team_member_id, assigned_by, assignment_type, priority, status, reason, campaign, updated_at
      ) values (
        p_location_id, root_member, root_user, 'territory_auto', 'normal', 'active', 'Automatic root territory ownership', 'territory_auto', now()
      )
      on conflict (location_id, team_member_id, assignment_type) where status='active'
      do update set updated_at = excluded.updated_at;
    end if;
  end if;

  for terr in
    select t.id, t.owner_user_id
    from public.crm_territories t
    where t.status='active'
      and public.crm_location_matches_territory(p_location_id, t.id)
  loop
    for access_row in
      select a.user_id
      from public.crm_territory_access a
      where a.territory_id = terr.id
        and a.status='active'
      union
      select terr.owner_user_id
      where terr.owner_user_id is not null
    loop
      insert into public.team_location_assignments(
        location_id, team_member_id, assigned_by, assignment_type, priority, status, reason, campaign, updated_at
      )
      select
        p_location_id,
        tmp.id,
        coalesce(root_user, access_row.user_id),
        'territory_auto',
        'normal',
        'active',
        'Automatic territory match',
        'territory_auto',
        now()
      from public.team_member_profiles tmp
      where tmp.user_id = access_row.user_id
        and tmp.status in ('active','training')
      on conflict (location_id, team_member_id, assignment_type) where status='active'
      do update set updated_at = excluded.updated_at;
    end loop;
  end loop;

  update public.team_location_assignments tla
  set status='inactive', updated_at=now(), notes=coalesce(tla.notes,'') || case when coalesce(tla.notes,'')='' then '' else E'\n' end || 'Removed automatically because territory no longer matches.'
  where tla.location_id = p_location_id
    and tla.assignment_type='territory_auto'
    and tla.status='active'
    and (root_member is null or tla.team_member_id <> root_member)
    and not exists (
      select 1
      from public.crm_territories t
      join public.crm_territory_access a on a.territory_id=t.id and a.status='active'
      join public.team_member_profiles tmp on tmp.user_id=a.user_id and tmp.id=tla.team_member_id
      where t.status='active'
        and public.crm_location_matches_territory(p_location_id,t.id)
      union all
      select 1
      from public.crm_territories t
      join public.team_member_profiles tmp on tmp.user_id=t.owner_user_id and tmp.id=tla.team_member_id
      where t.status='active'
        and public.crm_location_matches_territory(p_location_id,t.id)
    );
end;
$$;


