CREATE OR REPLACE FUNCTION "public"."crm_validate_opportunity_stage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare allowed text[];
begin
 allowed := case new.pipeline_key when 'business_claim' then array['identified','outreach_pending','contacted','engaged','claim_sent','claim_started','claim_review','claimed','closed_lost'] when 'reserve_pro' then array['identified','qualified','demo_scheduled','demo_completed','proposal','negotiation','payment_pending','closed_won','closed_lost'] when 'promoted_listing' then array['identified','qualified','proposal','payment_pending','active','closed_lost'] when 'partnership' then array['identified','discovery','qualified','proposal','legal_review','closed_won','closed_lost'] when 'renewal_expansion' then array['upcoming','review','expansion_identified','proposal','negotiation','renewed','expanded','churned'] end;
 if not (new.stage=any(allowed)) then raise exception 'invalid CRM stage % for pipeline %',new.stage,new.pipeline_key using errcode='23514'; end if;
 if new.stage='closed_lost' and nullif(btrim(new.loss_reason),'') is null then raise exception 'loss reason required' using errcode='23514'; end if;
 if new.stage in ('closed_won','closed_lost','claimed','active','renewed','expanded','churned') then new.actual_close_date=coalesce(new.actual_close_date,current_date); end if;
 return new;
end $$;


ALTER FUNCTION "public"."crm_validate_opportunity_stage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_validate_territory_access"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_parent public.crm_territory_access%rowtype;
  v_root uuid;
begin
  select root_owner_user_id into v_root
  from public.crm_territory_settings
  where singleton = true;

  if new.access_level = 'owner' then
    if new.user_id is distinct from v_root then
      raise exception 'Only the configured root owner can hold territory owner access';
    end if;
    new.can_delegate := true;
    new.parent_access_id := null;
    return new;
  end if;

  if new.granted_by_user_id is null then
    raise exception 'Territory access grants require a grantor';
  end if;

  select * into v_parent
  from public.crm_territory_access a
  where a.territory_id = new.territory_id
    and a.user_id = new.granted_by_user_id
    and a.status = 'active'
  limit 1;

  if not found then
    raise exception 'Grantor does not have active access to this territory';
  end if;

  if v_parent.access_level = 'owner' then
    if new.access_level not in ('manager','area_manager','sales_ambassador') then
      raise exception 'Owner may grant manager, area manager, or sales ambassador access';
    end if;
  elsif v_parent.access_level = 'manager' then
    if new.access_level not in ('area_manager','sales_ambassador') then
      raise exception 'Managers may grant area manager or sales ambassador access';
    end if;
  elsif v_parent.access_level = 'area_manager' then
    if new.access_level <> 'sales_ambassador' then
      raise exception 'Area managers may grant only sales ambassador access';
    end if;
  else
    raise exception 'Sales ambassadors cannot delegate territory access';
  end if;

  if not v_parent.can_delegate then
    raise exception 'Grantor is not allowed to delegate this territory';
  end if;

  new.parent_access_id := v_parent.id;
  new.can_delegate := new.access_level in ('manager','area_manager');
  return new;
end;
$$;


ALTER FUNCTION "public"."crm_validate_territory_access"() OWNER TO "postgres";


