CREATE OR REPLACE FUNCTION "public"."disable_orphaned_search_anchors"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  update public.search_anchors a
  set
    is_active = false,
    is_searchable = false,
    review_status = 'disabled',
    sync_status = 'disabled_source',
    last_synced_at = now(),
    metadata =
      coalesce(a.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'disabled_reason',
        'linked_location_missing',
        'disabled_at',
        now()
      )
  where a.source_type = 'linked_location'
    and a.linked_location_id is not null
    and not exists (
      select 1
      from public.locations l
      where l.id = a.linked_location_id
    )
    and (
      a.is_active = true
      or a.is_searchable = true
      or a.review_status is distinct from 'disabled'
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


