    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "team_work_sessions_approval_status_check" CHECK (("approval_status" = ANY (ARRAY['pending_review'::"text", 'approved'::"text", 'rejected'::"text", 'needs_correction'::"text"]))),
    CONSTRAINT "team_work_sessions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'completed'::"text", 'needs_correction'::"text", 'approved'::"text", 'rejected'::"text", 'exported'::"text", 'paid'::"text"])))
);


ALTER TABLE "public"."team_work_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_team_work_session"("p_session_id" "uuid", "p_user_notes" "text" DEFAULT NULL::"text") RETURNS "public"."team_work_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_session public.team_work_sessions%rowtype;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;
  select * into v_session from public.team_work_sessions where id = p_session_id for update;
  if not found then
    raise exception 'Work session not found.';
  end if;
  if v_session.user_id <> v_user_id and not exists (select 1 from public.admin_users where user_id = v_user_id and role in ('superadmin','admin')) then
    raise exception 'You cannot end this work session.';
  end if;
  update public.team_work_sessions
  set clock_out_at = now(),
      total_minutes = greatest(1, ceil(extract(epoch from (now() - clock_in_at)) / 60.0)::integer - coalesce(break_minutes,0)),
      status = 'completed',
      approval_status = 'pending_review',
      user_notes = coalesce(p_user_notes, user_notes),
      updated_at = now()
  where id = p_session_id
  returning * into v_session;
  return v_session;
end;
$$;


ALTER FUNCTION "public"."end_team_work_session"("p_session_id" "uuid", "p_user_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_standard_location_claim_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $_$
declare
  normalized text := upper(regexp_replace(coalesce(new.claim_code, ''), '\\s+', '', 'g'));
begin
  if normalized !~ '^[A-HJ-NP-Z2-9]{8}$' then
    normalized := public.generate_standard_location_claim_code();
  end if;

  if tg_op = 'INSERT' or new.claim_code is distinct from normalized then
    new.claim_code := normalized;
    new.claim_url := 'https://theouthaven.com/business/claim?code=' || normalized;
    new.qr_link := new.claim_url;
    new.claim_qr_url := null;
    new.claim_qr_code_url := null;
  else
    new.claim_code := normalized;
    if new.claim_url is null or new.claim_url !~ ('[?&]code=' || normalized || '($|&)') then
      new.claim_url := 'https://theouthaven.com/business/claim?code=' || normalized;
    end if;
    if new.qr_link is null or new.qr_link !~ ('[?&]code=' || normalized || '($|&)') then
      new.qr_link := new.claim_url;
    end if;
  end if;

  return new;
end;
$_$;


ALTER FUNCTION "public"."enforce_standard_location_claim_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_claimed_location_photo_nudges"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_claimed boolean;
  v_claim public.location_claim_requests%rowtype;
  v_channel text;
  v_contact text;
  v_name text;
  v_anchor timestamptz;
begin
  v_claimed := coalesce(new.is_claimed,false) or new.owner_user_id is not null or new.claim_status = 'approved';
  if not v_claimed or coalesce(new.owner_photo_count,0) >= 3 then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if (coalesce(old.is_claimed,false) or old.owner_user_id is not null or old.claim_status = 'approved')
       and old.owner_user_id is not distinct from new.owner_user_id
       and old.claim_status is not distinct from new.claim_status then
      return new;
    end if;
  end if;

  select * into v_claim
  from public.location_claim_requests
  where location_id = new.id
  order by (status = 'approved') desc, coalesce(reviewed_at, submitted_at, created_at) desc
  limit 1;

  v_channel := coalesce(v_claim.verified_contact_channel,
    case
      when nullif(btrim(coalesce(new.owner_email,'')), '') is not null then 'email'
      when nullif(btrim(coalesce(new.owner_phone,'')), '') is not null then 'sms'
      else null
    end);
  v_contact := coalesce(v_claim.verified_contact,
    case when v_channel = 'email' then new.owner_email
         when v_channel = 'sms' then new.owner_phone
         else null end);
  v_name := coalesce(nullif(new.name,''), nullif(new.restaurant_name,''), nullif(new.activity_name,''), 'Your business');
  v_anchor := coalesce(new.claimed_at, now());

  insert into public.profile_completion_nurture_queue(
    location_id, claim_request_id, message_type, contact_channel, contact, status, due_at, metadata
  ) values (
    new.id, v_claim.id, 'photo_reminder_day3', v_channel, v_contact,
    case when v_contact is null or v_channel is null then 'skipped' else 'pending' end,
    v_anchor + interval '3 days',
    jsonb_build_object('business_name',v_name,'recommended_photos',5,'minimum_photos',3,'source','claim_photo_onboarding')
  ) on conflict (location_id, message_type) do nothing;

  insert into public.profile_completion_nurture_queue(
    location_id, claim_request_id, message_type, contact_channel, contact, status, due_at, metadata
  ) values (
    new.id, v_claim.id, 'photo_reminder_day7', v_channel, v_contact,
    case when v_contact is null or v_channel is null then 'skipped' else 'pending' end,
    v_anchor + interval '7 days',
    jsonb_build_object('business_name',v_name,'recommended_photos',5,'minimum_photos',3,'source','claim_photo_onboarding')
  ) on conflict (location_id, message_type) do nothing;

  if not exists (
    select 1 from public.crm_tasks
    where location_id = new.id
      and source = 'photo_completion_nudge'
      and source_record_id = new.id::text
      and archived_at is null
  ) then
    insert into public.crm_tasks(
      location_id, title, description, task_type, status, priority,
      due_at, reminder_at, source, source_record_id,
      queue_key, category, subtype, workflow_key, workflow_stage,
      assignment_reason, metadata
    ) values (
      new.id,
      'Photo follow-up: ' || v_name,
      'Claimed location has fewer than 3 owner photos. Offer help completing the gallery; do not pressure the owner.',
      'profile_review','open','low',
      v_anchor + interval '8 days', v_anchor + interval '8 days',
      'photo_completion_nudge', new.id::text,
      'onboarding','profile','photos','claimed_business_activation','photos_needed',
      'Claimed business has fewer than 3 owner-controlled photos',
      jsonb_build_object('owner_photo_count',coalesce(new.owner_photo_count,0),'recommended_photos',5,'minimum_photos',3)
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_claimed_location_photo_nudges"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_full_search_profile_rebuild"("p_taxonomy_version" integer DEFAULT 2, "p_reason" "text" DEFAULT 'taxonomy_v2_full_rebuild'::"text") RETURNS TABLE("enqueued_count" bigint, "target_count" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_enqueued bigint;
  v_target bigint;
begin
  select count(*)
  into v_target
  from public.locations l
  where l.active = true
    and l.is_searchable = true
    and coalesce(l.is_hidden, false) = false
    and coalesce(l.is_low_level, false) = false;

  with candidates as (
    select l.id as location_id
    from public.locations l
    left join public.location_search_profiles p
      on p.location_id = l.id
    where l.active = true
      and l.is_searchable = true
      and coalesce(l.is_hidden, false) = false
      and coalesce(l.is_low_level, false) = false
      and (
        p.location_id is null
        or p.profile_version < 4
        or p.taxonomy_version < p_taxonomy_version
        or p.needs_review = true
      )
  ),
  inserted as (
    insert into public.location_search_profile_refresh_queue (
      location_id,
      reason,
      status,
      available_at,
      updated_at
    )
    select
      c.location_id,
      p_reason,
      'pending',
      now(),
      now()
    from candidates c
    where not exists (
      select 1
      from public.location_search_profile_refresh_queue q
      where q.location_id = c.location_id
        and q.status in ('pending', 'processing')
    )
    returning 1
  )
  select count(*)
  into v_enqueued
  from inserted;

  return query
  select
    v_enqueued,
    v_target;
end;
$$;


ALTER FUNCTION "public"."enqueue_full_search_profile_rebuild"("p_taxonomy_version" integer, "p_reason" "text") OWNER TO "postgres";


