CREATE OR REPLACE FUNCTION "public"."enqueue_owner_photo_activation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_name text;
  v_email text;
  v_claim_id uuid;
  v_is_new_claim boolean;
begin
  v_is_new_claim := coalesce(new.claim_status,'') in ('approved','claimed','redeemed')
    and (tg_op = 'INSERT'
      or coalesce(old.claim_status,'') is distinct from coalesce(new.claim_status,'')
      or old.owner_user_id is distinct from new.owner_user_id
      or old.claimed_at is distinct from new.claimed_at);

  if not v_is_new_claim or new.owner_user_id is null or coalesce(new.owner_photo_count,0) >= 3 then
    return new;
  end if;

  v_name := coalesce(nullif(new.name,''),nullif(new.restaurant_name,''),nullif(new.activity_name,''),'Your business');
  v_email := nullif(btrim(coalesce(new.owner_email,new.claimed_by_email,'')), '');

  select id into v_claim_id
  from public.location_claim_requests
  where location_id = new.id
  order by (status='approved') desc, coalesce(reviewed_at,submitted_at,created_at) desc
  limit 1;

  if not exists (
    select 1 from public.crm_tasks
    where location_id = new.id
      and source = 'owner_photo_completion'
      and archived_at is null
      and status <> 'completed'
  ) then
    insert into public.crm_tasks(
      location_id,title,description,task_type,status,priority,assigned_team,due_at,reminder_at,
      source,source_record_id,queue_key,category,subtype,workflow_key,workflow_stage,assignment_reason,metadata
    ) values (
      new.id,
      'Photo follow-up: ' || v_name,
      'Newly claimed location has fewer than 3 owner photos. The owner is being gently nudged to add 3-5 first-party photos so their own imagery appears before third-party images.',
      'onboarding','open','normal','support',now()+interval '7 days',now()+interval '7 days',
      'owner_photo_completion',new.id::text,'onboarding','onboarding','owner_photos','claimed_business_activation','photos_needed',
      'Newly claimed business is still using public or third-party imagery',
      jsonb_build_object('owner_photo_count',coalesce(new.owner_photo_count,0),'recommended_minimum',3,'gallery_complete',5)
    );
  end if;

  if v_email is not null then
    insert into public.profile_completion_nurture_queue(
      location_id,claim_request_id,message_type,contact_channel,contact,status,due_at,metadata
    ) values (
      new.id,v_claim_id,'photo_reminder_1','email',v_email,'pending',now()+interval '3 days',
      jsonb_build_object('business_name',v_name,'recommended_minimum',3,'gallery_complete',5)
    ) on conflict (location_id,message_type) do nothing;

    insert into public.profile_completion_nurture_queue(
      location_id,claim_request_id,message_type,contact_channel,contact,status,due_at,metadata
    ) values (
      new.id,v_claim_id,'photo_reminder_2','email',v_email,'pending',now()+interval '7 days',
      jsonb_build_object('business_name',v_name,'recommended_minimum',3,'gallery_complete',5)
    ) on conflict (location_id,message_type) do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_owner_photo_activation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_profile_completion_nurture"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_strength integer;
  v_claim public.location_claim_requests%rowtype;
  v_channel text;
  v_contact text;
  v_name text;
  v_angle text;
begin
  if new.profile_last_owner_update_at is null then return new; end if;
  if not (coalesce(new.is_claimed,false) or new.owner_user_id is not null or new.claim_status = 'approved') then return new; end if;
  v_strength := public.claim_profile_strength(new);
  if v_strength <> 100 then return new; end if;
  if exists (select 1 from public.claim_funnel_events where location_id = new.id and event_type = 'profile_completed') then return new; end if;
  select * into v_claim from public.location_claim_requests where location_id = new.id and status in ('approved','pending','needs_more_info') order by (status = 'approved') desc, coalesce(reviewed_at, submitted_at, created_at) desc limit 1;
  v_channel := coalesce(v_claim.verified_contact_channel, case when nullif(btrim(coalesce(new.owner_email,'')), '') is not null then 'email' when nullif(btrim(coalesce(new.owner_phone,'')), '') is not null then 'sms' else null end);
  v_contact := coalesce(v_claim.verified_contact, case when v_channel = 'email' then new.owner_email when v_channel = 'sms' then new.owner_phone else null end);
  v_name := coalesce(nullif(new.name,''), nullif(new.restaurant_name,''), nullif(new.activity_name,''), 'Your business');
  v_angle := case when not coalesce(new.uses_internal_reservations,false) and nullif(btrim(coalesce(new.reservation_url,new.external_reservation_url,new.booking_url,new.reservation_link,new.reservation_platform_url,'')), '') is not null then 'reservations' when coalesce(new.location_type,new.type,'') ilike '%activ%' then 'events_experiences' else 'growth_tools' end;
  insert into public.claim_funnel_events(location_id, claim_code, event_type, metadata) values (new.id, v_claim.claim_code, 'profile_completed', jsonb_build_object('profile_strength',100,'recommended_angle',v_angle,'source','owner_profile_update'));
  insert into public.profile_completion_nurture_queue(location_id, claim_request_id, message_type, contact_channel, contact, status, due_at, metadata) values (new.id, v_claim.id, 'completion_confirmation', v_channel, v_contact, case when v_contact is null or v_channel is null then 'skipped' else 'pending' end, now(), jsonb_build_object('profile_strength',100,'business_name',v_name,'recommended_angle',v_angle)) on conflict (location_id, message_type) do nothing;
  insert into public.profile_completion_nurture_queue(location_id, claim_request_id, message_type, contact_channel, contact, status, due_at, metadata) values (new.id, v_claim.id, 'upgrade_intro', v_channel, v_contact, case when v_contact is null or v_channel is null then 'skipped' else 'pending' end, now() + interval '2 days', jsonb_build_object('profile_strength',100,'business_name',v_name,'recommended_angle',v_angle)) on conflict (location_id, message_type) do nothing;
  if not exists (select 1 from public.crm_tasks where location_id = new.id and source = 'profile_completion_nurture' and source_record_id = new.id::text and archived_at is null) then
    insert into public.crm_tasks(location_id,title,description,task_type,status,priority,assigned_team,due_at,reminder_at,source,source_record_id,queue_key,category,subtype,workflow_key,workflow_stage,assignment_reason,metadata)
    values (new.id,'Follow up - profile completed: ' || v_name,'This claimed business reached 100% profile strength. Introduce the most relevant TheOutHaven paid capability after the completion confirmation has landed.','follow_up','open','normal','sales',now()+interval '2 days',now()+interval '2 days','profile_completion_nurture',new.id::text,'sales','growth','profile_completion','claimed_business_activation','profile_complete','Claimed business reached 100% profile strength',jsonb_build_object('profile_strength',100,'recommended_angle',v_angle,'claim_request_id',v_claim.id,'verified_channel',v_channel));
  end if;
  update public.locations set next_action='Introduce TheOutHaven paid tools after profile completion', next_action_type='sales_follow_up', next_action_due_at=now()+interval '2 days' where id=new.id;
  return new;
end;
$$;


ALTER FUNCTION "public"."enqueue_profile_completion_nurture"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_search_anchor_reconciliation"("p_location_id" "uuid", "p_event_type" "text" DEFAULT 'update'::"text", "p_reason_code" "text" DEFAULT 'location_changed'::"text", "p_priority" integer DEFAULT 50, "p_source_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if p_location_id is null then
    raise exception 'location_id is required';
  end if;

  insert into public.search_anchor_reconciliation_queue (
    location_id,
    event_type,
    reason_code,
    status,
    priority,
    attempts,
    available_at,
    locked_at,
    locked_by,
    processed_at,
    last_error,
    source_updated_at,
    payload
  )
  values (
    p_location_id,
    p_event_type,
    p_reason_code,
    'pending',
    greatest(0, least(coalesce(p_priority, 50), 100)),
    0,
    now(),
    null,
    null,
    null,
    null,
    p_source_updated_at,
    coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (location_id)
  where status in ('pending', 'processing')
  do update set
    event_type = excluded.event_type,
    reason_code = excluded.reason_code,
    priority = greatest(
      public.search_anchor_reconciliation_queue.priority,
      excluded.priority
    ),
    status = 'pending',
    available_at = now(),
    locked_at = null,
    locked_by = null,
    processed_at = null,
    last_error = null,
    source_updated_at = excluded.source_updated_at,
    payload =
      public.search_anchor_reconciliation_queue.payload
      || excluded.payload,
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_search_anchor_reconciliation"("p_location_id" "uuid", "p_event_type" "text", "p_reason_code" "text", "p_priority" integer, "p_source_updated_at" timestamp with time zone, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_worker_job"("p_job_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_payload_version" integer DEFAULT 1, "p_idempotency_key" "text" DEFAULT NULL::"text", "p_priority" integer DEFAULT 100, "p_max_attempts" integer DEFAULT 5, "p_run_after" timestamp with time zone DEFAULT "now"(), "p_parent_job_id" "uuid" DEFAULT NULL::"uuid", "p_created_by_label" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."worker_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_job public.worker_jobs;
begin
  insert into public.worker_jobs(job_type,payload,payload_version,idempotency_key,priority,max_attempts,run_after,parent_job_id,created_by_label,created_by)
  values(p_job_type,coalesce(p_payload,'{}'::jsonb),p_payload_version,p_idempotency_key,p_priority,p_max_attempts,coalesce(p_run_after,now()),p_parent_job_id,p_created_by_label,p_created_by)
  on conflict (idempotency_key) where idempotency_key is not null do update set updated_at=worker_jobs.updated_at
  returning * into v_job;
  insert into public.worker_job_events(job_id,event_type,message,metadata,created_by) values(v_job.id,'enqueued','Job enqueued',jsonb_build_object('job_type',v_job.job_type),'enqueue_worker_job');
  return v_job;
end $$;


ALTER FUNCTION "public"."enqueue_worker_job"("p_job_type" "text", "p_payload" "jsonb", "p_payload_version" integer, "p_idempotency_key" "text", "p_priority" integer, "p_max_attempts" integer, "p_run_after" timestamp with time zone, "p_parent_job_id" "uuid", "p_created_by_label" "text", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enterprise_search_live_music_locations"("p_search_terms" "text"[] DEFAULT ARRAY['live music'::"text", 'music venue'::"text", 'jazz'::"text", 'concert'::"text", 'live band'::"text"], "p_neighborhood" "text" DEFAULT NULL::"text", "p_borough" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_radius_miles" numeric DEFAULT NULL::numeric, "p_limit" integer DEFAULT 60) RETURNS SETOF "public"."locations"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select l.*
  from public.locations l
  where l.deleted_at is null
    and coalesce(l.is_hidden, false) = false
    and coalesce(l.active, true) = true
    and coalesce(l.is_searchable, true) = true
    and coalesce(l.is_low_level, false) = false
    and coalesce(l.has_photos, false) = true
    and coalesce(l.status, '') not in ('hidden', 'deleted', 'archived')
    and coalesce(l.data_status, 'clean') not in (
      'hidden',
      'deleted',
      'archived'
    )
    and (
      lower(
        concat_ws(
          ' ',
          l.name,
          l.activity_name,
          l.activity_type,
          l.primary_category,
          l.description,
          l.search_document,
          l.semantic_search_text,
          array_to_string(l.tags, ' '),
          array_to_string(l.search_keywords, ' '),
          array_to_string(l.semantic_tags, ' '),
          array_to_string(l.intent_tags, ' ')
        )
      ) ~ '(live music|music venue|jazz club|jazz lounge|concert venue|performing arts venue|live band)'
      or lower(coalesce(l.activity_type, '')) ~
        '(live music|music venue|jazz|concert)'
      or lower(coalesce(l.primary_category, '')) ~
        '(live music|music venue|jazz|concert|performing arts)'
    )
    and (
      p_state is null
      or l.state is null
      or lower(l.state) = lower(p_state)
    )
    and (
      p_borough is null
      or l.borough is null
      or lower(l.borough) = lower(p_borough)
    )
    and (
      p_county is null
      or l.county is null
      or lower(l.county) = lower(p_county)
    )
    and (
      (p_neighborhood is null and p_city is null)
      or lower(coalesce(l.neighborhood, '')) =
        lower(coalesce(p_neighborhood, ''))
      or lower(coalesce(l.city, '')) =
        lower(coalesce(p_city, ''))
      or (
        p_borough is not null
        and lower(coalesce(l.borough, '')) = lower(p_borough)
      )
    )
  order by
    case
      when lower(coalesce(l.activity_type, '')) ~
        '(live music|music venue|jazz|concert)'
      then 0
      else 1
    end,
    coalesce(l.theouthaven_score, l.quality_score, 0) desc,
    coalesce(l.rating, 0) desc,
    coalesce(l.review_count, 0) desc
  limit greatest(
    1,
    least(coalesce(p_limit, 60), 100)
  );
$$;


ALTER FUNCTION "public"."enterprise_search_live_music_locations"("p_search_terms" "text"[], "p_neighborhood" "text", "p_borough" "text", "p_city" "text", "p_county" "text", "p_state" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_miles" numeric, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enterprise_search_locations"("p_search_terms" "text"[], "p_domain" "text" DEFAULT 'any'::"text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_borough" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_radius_miles" numeric DEFAULT NULL::numeric, "p_limit" integer DEFAULT 40, "p_allow_places_of_worship" boolean DEFAULT false, "p_allow_low_level" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "location_type" "text", "restaurant_name" "text", "activity_name" "text", "name" "text", "address" "text", "city" "text", "state" "text", "zip_code" "text", "market" "text", "county" "text", "neighborhood" "text", "borough" "text", "latitude" numeric, "longitude" numeric, "description" "text", "cuisine" "text", "cuisine_type" "text", "activity_type" "text", "primary_category" "text", "tags" "text"[], "vibe_tags" "text"[], "best_for_tags" "text"[], "date_style_tags" "text"[], "search_keywords" "text"[], "google_types" "text"[], "semantic_tags" "text"[], "intent_tags" "text"[], "search_document" "text", "semantic_search_text" "text", "rating" numeric, "review_count" integer, "review_score" numeric, "quality_score" numeric, "popularity_score" numeric, "roseout_score" numeric, "theouthaven_score" numeric, "search_score" numeric, "recommendation_score" numeric, "analytics_score" numeric, "reservation_url" "text", "reservation_link" "text", "booking_url" "text", "external_reservation_url" "text", "website" "text", "phone" "text", "image_url" "text", "main_image" "text", "images" "jsonb", "gallery_images" "jsonb", "has_photos" boolean, "photo_status" "text", "public_visibility_tier" "text", "curation_tier" "text", "source_quality_status" "text", "duplicate_status" "text", "is_low_level" boolean, "is_searchable" boolean, "is_hidden" boolean, "active" boolean, "status" "text", "data_status" "text", "deleted_at" timestamp with time zone, "match_score" numeric, "term_score" numeric, "geo_score" numeric, "distance_score" numeric, "distance_miles" numeric, "domain_score" numeric, "quality_rank_score" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with candidates as (
  select
    l.*,
    lower(
      concat_ws(
        ' ',
        l.name,
        l.restaurant_name,
        l.activity_name,
        l.location_type,
        l.primary_category,
        l.cuisine,
        l.cuisine_type,
        l.activity_type,
        l.description,
        l.neighborhood,
        l.borough,
        l.city,
        l.county,
        l.market,
        l.state,
        l.address,
        l.search_document,
        l.semantic_search_text,
        array_to_string(l.tags, ' '),
        array_to_string(l.vibe_tags, ' '),
        array_to_string(l.best_for_tags, ' '),
        array_to_string(l.date_style_tags, ' '),
        array_to_string(l.search_keywords, ' '),
        array_to_string(l.google_types, ' '),
        array_to_string(l.semantic_tags, ' '),
        array_to_string(l.intent_tags, ' '),
        array_to_string(l.special_features, ' '),
        array_to_string(l.signature_items, ' '),
        array_to_string(l.best_for, ' ')
      )
    ) as haystack
  from public.locations l
  where l.deleted_at is null
    and coalesce(l.is_hidden, false) = false
    and coalesce(l.active, true) = true
    and coalesce(l.is_searchable, true) = true
    and coalesce(l.status, '') not in ('hidden', 'deleted', 'archived')
    and coalesce(l.data_status, 'clean') not in ('hidden', 'deleted', 'archived')
    and (p_allow_low_level = true or coalesce(l.is_low_level, false) = false)
    and (p_allow_low_level = true or coalesce(l.public_visibility_tier, 'standard') not in ('low_level', 'hidden'))
    and (p_allow_low_level = true or coalesce(l.curation_tier, 'standard') <> 'low_level')
    and (p_allow_low_level = true or coalesce(l.source_quality_status, 'enriched') not in ('imported_unverified', 'generic_restaurant', 'needs_enrichment', 'low_level_review'))
    and (p_allow_low_level = true or coalesce(l.import_confidence, 'unknown') <> 'low')
    and (p_allow_low_level = true or coalesce(l.has_photos, false) = true)
    and (p_allow_low_level = true or coalesce(l.photo_status, '') <> 'missing_photo')
    and (
      p_radius_miles is null
      or p_latitude is null
      or p_longitude is null
      or l.latitude is null
      or l.longitude is null
      or (
        3958.8 * acos(
          least(
            1,
            cos(radians(p_latitude::double precision))
            * cos(radians(l.latitude::double precision))
            * cos(radians(l.longitude::double precision) - radians(p_longitude::double precision))
            + sin(radians(p_latitude::double precision))
            * sin(radians(l.latitude::double precision))
          )
        )
      ) <= p_radius_miles
    )
    and (
      p_allow_places_of_worship = true
      or not (
        lower(coalesce(l.primary_category, '')) like '%temple%'
        or lower(coalesce(l.primary_category, '')) like '%hindu temple%'
        or lower(coalesce(l.primary_category, '')) like '%church%'
        or lower(coalesce(l.primary_category, '')) like '%chapel%'
        or lower(coalesce(l.primary_category, '')) like '%cathedral%'
        or lower(coalesce(l.primary_category, '')) like '%mosque%'
        or lower(coalesce(l.primary_category, '')) like '%masjid%'
        or lower(coalesce(l.primary_category, '')) like '%synagogue%'
        or lower(coalesce(l.primary_category, '')) like '%shul%'
        or lower(coalesce(l.primary_category, '')) like '%place of worship%'
        or lower(coalesce(l.primary_category, '')) like '%religious organization%'
        or lower(coalesce(l.primary_category, '')) like '%religious center%'
        or lower(coalesce(l.primary_category, '')) like '%worship center%'
        or lower(coalesce(l.primary_category, '')) like '%spiritual center%'
        or lower(coalesce(l.primary_category, '')) like '%shrine%'
        or lower(coalesce(l.primary_category, '')) like '%ministry%'
        or lower(coalesce(l.primary_category, '')) like '%parish%'
        or lower(coalesce(l.primary_category, '')) like '%congregation%'
        or lower(coalesce(l.location_type, '')) like '%place of worship%'
        or lower(coalesce(l.location_type, '')) like '%religious%'
      )
    )
    and (
      p_domain not in ('restaurant', 'activity')
      or (
        p_domain = 'restaurant'
        and (
          l.restaurant_name is not null
          or l.cuisine is not null
          or l.cuisine_type is not null
          or lower(coalesce(l.location_type, '')) like '%restaurant%'
          or lower(coalesce(l.primary_category, '')) like '%restaurant%'
          or lower(coalesce(l.primary_category, '')) like '%dining%'
          or lower(coalesce(l.primary_category, '')) like '%cafe%'
          or lower(coalesce(l.primary_category, '')) like '%bakery%'
          or lower(coalesce(l.primary_category, '')) like '%bistro%'
          or lower(coalesce(l.primary_category, '')) like '%steakhouse%'
          or lower(coalesce(l.primary_category, '')) like '%bar and grill%'
          or lower(coalesce(l.primary_category, '')) like '%gastropub%'
        )
        and not (
          l.restaurant_name is null
          and l.cuisine is null
          and l.cuisine_type is null
          and (
            lower(coalesce(l.primary_category, '')) like '%temple%'
            or lower(coalesce(l.primary_category, '')) like '%church%'
            or lower(coalesce(l.primary_category, '')) like '%mosque%'
            or lower(coalesce(l.primary_category, '')) like '%synagogue%'
            or lower(coalesce(l.primary_category, '')) like '%place of worship%'
            or lower(coalesce(l.primary_category, '')) like '%theater%'
            or lower(coalesce(l.primary_category, '')) like '%theatre%'
            or lower(coalesce(l.primary_category, '')) like '%movie theater%'
            or lower(coalesce(l.primary_category, '')) like '%cinema%'
            or lower(coalesce(l.primary_category, '')) like '%museum%'
            or lower(coalesce(l.primary_category, '')) like '%gallery%'
            or lower(coalesce(l.primary_category, '')) like '%park%'
            or lower(coalesce(l.primary_category, '')) like '%bowling%'
            or lower(coalesce(l.primary_category, '')) like '%arcade%'
            or lower(coalesce(l.primary_category, '')) like '%escape room%'
            or lower(coalesce(l.primary_category, '')) like '%karaoke%'
          )
        )
      )
      or (
        p_domain = 'activity'
        and (
          l.activity_name is not null
          or l.activity_type is not null
          or lower(coalesce(l.location_type, '')) like '%activity%'
          or lower(coalesce(l.primary_category, '')) like '%activity%'
          or lower(coalesce(l.primary_category, '')) like '%experience%'
          or lower(coalesce(l.primary_category, '')) like '%entertainment%'
          or lower(coalesce(l.primary_category, '')) like '%lounge%'
          or lower(coalesce(l.primary_category, '')) like '%hookah%'
          or lower(coalesce(l.primary_category, '')) like '%bowling%'
          or lower(coalesce(l.primary_category, '')) like '%museum%'
          or (
            exists (
              select 1
              from unnest(coalesce(p_search_terms, array[]::text[])) t
              where lower(t) in ('theater', 'theatre', 'movie theater', 'cinema', 'movie', 'movies', 'show', 'broadway')
            )
            and (
              lower(coalesce(l.primary_category, '')) like '%theater%'
              or lower(coalesce(l.primary_category, '')) like '%theatre%'
              or lower(coalesce(l.primary_category, '')) like '%movie theater%'
              or lower(coalesce(l.primary_category, '')) like '%cinema%'
            )
          )
          or lower(coalesce(l.primary_category, '')) like '%arcade%'
          or lower(coalesce(l.primary_category, '')) like '%karaoke%'
          or lower(coalesce(l.primary_category, '')) like '%gallery%'
          or lower(coalesce(l.primary_category, '')) like '%park%'
          or lower(coalesce(l.primary_category, '')) like '%spa%'
        )
      )
    )
), scored as (
  select
    c.*,
    (
      select coalesce(
        sum(
          case
            when lower(c.name) = lower(t)
              or lower(coalesce(c.restaurant_name, '')) = lower(t)
              or lower(coalesce(c.activity_name, '')) = lower(t)
              then 90
            when lower(coalesce(c.primary_category, '')) like '%' || lower(t) || '%'
              or lower(coalesce(c.cuisine, '')) like '%' || lower(t) || '%'
              or lower(coalesce(c.cuisine_type, '')) like '%' || lower(t) || '%'
              or lower(coalesce(c.activity_type, '')) like '%' || lower(t) || '%'
              then 70
            when c.haystack like '%' || lower(t) || '%'
              then 30
            else 0
          end
        ),
        0
      )
      from unnest(coalesce(p_search_terms, array[]::text[])) t
    ) as term_score_calc,
    case
      when p_domain = 'restaurant' and (
        c.restaurant_name is not null
        or c.cuisine is not null
        or c.cuisine_type is not null
        or lower(coalesce(c.location_type, '')) like '%restaurant%'
        or lower(coalesce(c.primary_category, '')) like '%restaurant%'
        or lower(coalesce(c.primary_category, '')) like '%dining%'
        or lower(coalesce(c.primary_category, '')) like '%cafe%'
        or lower(coalesce(c.primary_category, '')) like '%bakery%'
        or lower(coalesce(c.primary_category, '')) like '%bistro%'
        or lower(coalesce(c.primary_category, '')) like '%steakhouse%'
        or lower(coalesce(c.primary_category, '')) like '%bar and grill%'
        or lower(coalesce(c.primary_category, '')) like '%gastropub%'
      ) then 120
      when p_domain = 'activity' and (
        c.activity_name is not null
        or c.activity_type is not null
        or lower(coalesce(c.location_type, '')) like '%activity%'
        or lower(coalesce(c.primary_category, '')) like '%activity%'
        or lower(coalesce(c.primary_category, '')) like '%experience%'
        or lower(coalesce(c.primary_category, '')) like '%entertainment%'
        or lower(coalesce(c.primary_category, '')) like '%lounge%'
        or lower(coalesce(c.primary_category, '')) like '%hookah%'
        or lower(coalesce(c.primary_category, '')) like '%bowling%'
        or lower(coalesce(c.primary_category, '')) like '%museum%'
        or (
          exists (
            select 1
            from unnest(coalesce(p_search_terms, array[]::text[])) t
            where lower(t) in ('theater', 'theatre', 'movie theater', 'cinema', 'movie', 'movies', 'show', 'broadway')
          )
          and (
            lower(coalesce(c.primary_category, '')) like '%theater%'
            or lower(coalesce(c.primary_category, '')) like '%theatre%'
            or lower(coalesce(c.primary_category, '')) like '%movie theater%'
            or lower(coalesce(c.primary_category, '')) like '%cinema%'
          )
        )
        or lower(coalesce(c.primary_category, '')) like '%arcade%'
        or lower(coalesce(c.primary_category, '')) like '%karaoke%'
        or lower(coalesce(c.primary_category, '')) like '%gallery%'
        or lower(coalesce(c.primary_category, '')) like '%park%'
        or lower(coalesce(c.primary_category, '')) like '%spa%'
      ) then 120
      when p_domain = 'any' then 20
      else -200
    end as domain_score_calc,
    case
      when p_state is not null and c.state is not null and lower(c.state) <> lower(p_state) then -200
      when p_county is not null and lower(coalesce(c.county, '')) = lower(p_county) then 130
      when p_neighborhood is not null and lower(coalesce(c.neighborhood, '')) = lower(p_neighborhood) then 120
      when p_borough is not null and lower(coalesce(c.borough, '')) = lower(p_borough) then 90
      when p_city is not null and lower(coalesce(c.city, '')) = lower(p_city) then 80
      when p_region = 'Long Island'
        and c.state = 'NY'
        and (
          coalesce(c.market, '') = 'LONG_ISLAND'
          or lower(coalesce(c.county, '')) in ('nassau', 'nassau county', 'suffolk', 'suffolk county')
          or c.haystack ~ '(nassau|suffolk|hempstead|huntington|garden city|mineola|long beach)'
        )
        then 120
      when p_borough is not null
        or p_city is not null
        or p_county is not null
        or p_neighborhood is not null
        or p_state is not null
        then -35
      else 0
    end as geo_score_calc,
    case
      when p_latitude is not null
        and p_longitude is not null
        and c.latitude is not null
        and c.longitude is not null
        then 3958.8 * acos(
          least(
            1,
            cos(radians(p_latitude::double precision))
            * cos(radians(c.latitude::double precision))
            * cos(radians(c.longitude::double precision) - radians(p_longitude::double precision))
            + sin(radians(p_latitude::double precision))
            * sin(radians(c.latitude::double precision))
          )
        )
      else null
    end as distance_miles_calc
  from candidates c
), final as (
  select
    s.*,
    case
      when distance_miles_calc is null then 0
      when distance_miles_calc <= 1 then 35
      when distance_miles_calc <= 3 then 25
      when distance_miles_calc <= 5 then 15
      when distance_miles_calc <= 8 then 5
      when p_neighborhood is not null then -20
      else -5
    end as distance_score_calc,
    coalesce(s.theouthaven_score, s.quality_score, s.roseout_score, 0)
      + coalesce(s.rating, 0) * 2
      + least(coalesce(s.review_count, 0)::numeric / 100, 10)
      + case
          when coalesce(s.public_visibility_tier, 'standard') = 'premium' then 250
          when coalesce(s.public_visibility_tier, 'standard') = 'curated' then 200
          else 0
        end
      + case
          when coalesce(s.curation_tier, 'standard') = 'premium' then 250
          when coalesce(s.curation_tier, 'standard') in ('curated', 'date_worthy') then 200
          else 0
        end
      + case
          when coalesce(s.has_photos, false) = true
            and coalesce(s.photo_status, '') <> 'missing_photo'
            then 75
          else -800
        end
      + case when coalesce(s.is_low_level, false) = true then -1000 else 0 end
      + case when coalesce(s.public_visibility_tier, 'standard') in ('low_level', 'hidden') then -700 else 0 end
      + case when coalesce(s.source_quality_status, 'enriched') in ('imported_unverified', 'generic_restaurant') then -700 else 0 end
      as quality_rank_score_calc
  from scored s
)
select
  f.id,
  f.location_type,
  f.restaurant_name,
  f.activity_name,
  f.name,
  f.address,
  f.city,
  f.state,
  f.zip_code,
  f.market,
  f.county,
  f.neighborhood,
  f.borough,
  f.latitude,
  f.longitude,
  f.description,
  f.cuisine,
  f.cuisine_type,
  f.activity_type,
  f.primary_category,
  f.tags,
  f.vibe_tags,
  f.best_for_tags,
  f.date_style_tags,
  f.search_keywords,
  f.google_types,
  f.semantic_tags,
  f.intent_tags,
  f.search_document,
  f.semantic_search_text,
  f.rating,
  f.review_count,
  f.review_score,
  f.quality_score,
  f.popularity_score,
  f.roseout_score,
  f.theouthaven_score,
  null::numeric as search_score,
  f.recommendation_score,
  f.analytics_score,
  f.reservation_url,
  f.reservation_link,
  f.booking_url,
  f.external_reservation_url,
  f.website,
  f.phone,
  f.image_url,
  f.main_image,
  to_jsonb(f.images) as images,
  to_jsonb(f.gallery_images) as gallery_images,
  f.has_photos,
  f.photo_status,
  f.public_visibility_tier,
  f.curation_tier,
  f.source_quality_status,
  f.duplicate_status,
  f.is_low_level,
  f.is_searchable,
  f.is_hidden,
  f.active,
  f.status,
  f.data_status,
  f.deleted_at,
  (f.term_score_calc + f.geo_score_calc + f.domain_score_calc + f.distance_score_calc + f.quality_rank_score_calc) as match_score,
  f.term_score_calc as term_score,
  f.geo_score_calc as geo_score,
  f.distance_score_calc as distance_score,
  round(f.distance_miles_calc::numeric, 2) as distance_miles,
  f.domain_score_calc as domain_score,
  f.quality_rank_score_calc as quality_rank_score
from final f
where (
  f.term_score_calc > 0
  or coalesce(array_length(p_search_terms, 1), 0) = 0
  or p_domain in ('any')
)
order by
  match_score desc,
  term_score_calc desc,
  geo_score_calc desc,
  domain_score_calc desc,
  distance_score_calc desc,
  quality_rank_score_calc desc,
  f.theouthaven_score desc nulls last,
  f.rating desc nulls last,
  f.review_count desc nulls last
limit least(greatest(p_limit, 1), 100);
$$;


ALTER FUNCTION "public"."enterprise_search_locations"("p_search_terms" "text"[], "p_domain" "text", "p_neighborhood" "text", "p_borough" "text", "p_city" "text", "p_county" "text", "p_region" "text", "p_state" "text", "p_latitude" numeric, "p_longitude" numeric, "p_radius_miles" numeric, "p_limit" integer, "p_allow_places_of_worship" boolean, "p_allow_low_level" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enterprise_search_profile_candidate_ids"("p_query" "text" DEFAULT ''::"text", "p_domain" "text" DEFAULT NULL::"text", "p_categories" "text"[] DEFAULT NULL::"text"[], "p_market" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text", "p_borough" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_latitude" double precision DEFAULT NULL::double precision, "p_longitude" double precision DEFAULT NULL::double precision, "p_radius_miles" double precision DEFAULT NULL::double precision, "p_limit" integer DEFAULT 200) RETURNS TABLE("location_id" "uuid", "computed_distance_miles" double precision, "primary_domain" "text", "confidence" numeric, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with candidates as (
    select
      p.*,
      case
        when p_latitude is not null
          and p_longitude is not null
          and p_radius_miles is not null
          and p.latitude is not null
          and p.longitude is not null
        then 3958.7613 * 2 * asin(
          sqrt(
            least(
              1,
              greatest(
                0,
                power(sin(radians(p.latitude - p_latitude) / 2), 2)
                + cos(radians(p_latitude))
                * cos(radians(p.latitude))
                * power(sin(radians(p.longitude - p_longitude) / 2), 2)
              )
            )
          )
        )
        else null
      end as computed_distance_miles
    from public.location_search_profiles p
    join public.locations l on l.id = p.location_id
    where l.active = true
      and l.is_searchable = true
      and l.is_hidden = false
      and l.is_low_level = false
      and p.profile_version >= 3
      and (
        p_domain is null
        or p.primary_domain = p_domain
        or p.supported_domains @> array[p_domain]::text[]
      )
      and (
        p_domain is null
        or (
          p_domain = 'restaurant'
          and (
            p.primary_domain = 'restaurant'
            or coalesce(cardinality(p.restaurant_categories), 0) > 0
            or coalesce(cardinality(p.cuisines), 0) > 0
            or coalesce(cardinality(p.foods), 0) > 0
          )
        )
        or (
          p_domain = 'activity'
          and (
            p.primary_domain = 'activity'
            or coalesce(cardinality(p.activity_categories), 0) > 0
            or coalesce(cardinality(p.nightlife_categories), 0) > 0
          )
        )
      )
  )
  select
    c.location_id,
    c.computed_distance_miles,
    c.primary_domain,
    c.confidence,
    c.updated_at
  from candidates c
  where
    case
      when p_latitude is not null
        and p_longitude is not null
        and p_radius_miles is not null
      then c.computed_distance_miles is null or c.computed_distance_miles <= p_radius_miles
      when nullif(trim(p_neighborhood), '') is not null
      then regexp_replace(lower(coalesce(c.neighborhood, '')), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(p_neighborhood), '[^a-z0-9]+', '', 'g')
      when nullif(trim(p_borough), '') is not null
      then regexp_replace(lower(coalesce(c.borough, '')), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(p_borough), '[^a-z0-9]+', '', 'g')
      when nullif(trim(p_city), '') is not null
      then regexp_replace(lower(coalesce(c.city, '')), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(p_city), '[^a-z0-9]+', '', 'g')
      when nullif(trim(p_county), '') is not null
      then regexp_replace(lower(coalesce(c.county, '')), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(p_county), '[^a-z0-9]+', '', 'g')
      when nullif(trim(p_market), '') is not null
      then regexp_replace(lower(coalesce(c.market, '')), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(p_market), '[^a-z0-9]+', '', 'g')
      when nullif(trim(p_state), '') is not null
      then lower(coalesce(c.state, '')) = lower(p_state)
      else true
    end
    and (
      coalesce(trim(p_query), '') = ''
      or case
        when p_domain = 'restaurant' then
          c.restaurant_categories && coalesce(p_categories, '{}'::text[])
          or c.cuisines && coalesce(p_categories, '{}'::text[])
          or c.foods && coalesce(p_categories, '{}'::text[])
          or c.canonical_terms && coalesce(p_categories, '{}'::text[])
          or c.features && coalesce(p_categories, '{}'::text[])
          or c.search_tsv @@ websearch_to_tsquery('simple', p_query)
        when p_domain = 'activity' then
          c.activity_categories && coalesce(p_categories, '{}'::text[])
          or c.nightlife_categories && coalesce(p_categories, '{}'::text[])
          or c.canonical_terms && coalesce(p_categories, '{}'::text[])
          or c.features && coalesce(p_categories, '{}'::text[])
          or c.search_tsv @@ websearch_to_tsquery('simple', p_query)
        else
          c.search_tsv @@ websearch_to_tsquery('simple', p_query)
          or c.canonical_terms && coalesce(p_categories, '{}'::text[])
      end
    )
  order by
    case when c.primary_domain = p_domain then 0 else 1 end,
    c.computed_distance_miles nulls last,
    c.confidence desc,
    c.updated_at desc,
    c.location_id
  limit least(greatest(coalesce(p_limit, 200), 1), 250);
$$;


ALTER FUNCTION "public"."enterprise_search_profile_candidate_ids"("p_query" "text", "p_domain" "text", "p_categories" "text"[], "p_market" "text", "p_state" "text", "p_county" "text", "p_borough" "text", "p_city" "text", "p_neighborhood" "text", "p_latitude" double precision, "p_longitude" double precision, "p_radius_miles" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enterprise_search_profile_location_diagnostics"("p_query" "text" DEFAULT ''::"text", "p_domain" "text" DEFAULT NULL::"text", "p_categories" "text"[] DEFAULT NULL::"text"[], "p_market" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text", "p_borough" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_latitude" double precision DEFAULT NULL::double precision, "p_longitude" double precision DEFAULT NULL::double precision, "p_radius_miles" double precision DEFAULT NULL::double precision, "p_limit" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      p.*,
      l.is_verified as location_is_verified,
      case
        when p_latitude is not null
          and p_longitude is not null
          and p_radius_miles is not null
          and p.latitude is not null
          and p.longitude is not null
        then 3958.7613 * 2 * asin(
          sqrt(
            least(
              1,
              greatest(
                0,
                power(sin(radians(p.latitude - p_latitude) / 2), 2)
                + cos(radians(p_latitude))
                * cos(radians(p.latitude))
                * power(sin(radians(p.longitude - p_longitude) / 2), 2)
              )
            )
          )
        )
        else null
      end as distance_miles
    from public.location_search_profiles p
    join public.locations l
      on l.id = p.location_id
    where l.active = true
      and l.is_searchable = true
      and l.is_hidden = false
      and l.is_low_level = false
      and p.profile_version >= 3
  ),
  domain_ok as (
    select b.*
    from base b
    where p_domain is null
      or b.primary_domain = p_domain
      or (
        coalesce(b.location_is_verified, false)
        and b.supported_domains @> array[p_domain]::text[]
        and (
          p_domain = 'restaurant'
          or coalesce(cardinality(b.activity_categories), 0) > 0
          or coalesce(cardinality(b.nightlife_categories), 0) > 0
        )
      )
  ),
  geo_ok as (
    select d.*
    from domain_ok d
    where case
      when p_latitude is not null
        and p_longitude is not null
        and p_radius_miles is not null
        then d.distance_miles is null
          or d.distance_miles <= p_radius_miles
      when nullif(trim(p_neighborhood), '') is not null
        then lower(coalesce(d.neighborhood, '')) = lower(p_neighborhood)
      when nullif(trim(p_borough), '') is not null
        then lower(coalesce(d.borough, '')) = lower(p_borough)
      when nullif(trim(p_city), '') is not null
        then lower(coalesce(d.city, '')) = lower(p_city)
      when nullif(trim(p_county), '') is not null
        then lower(coalesce(d.county, '')) = lower(p_county)
      when nullif(trim(p_market), '') is not null
        then lower(coalesce(d.market, '')) = lower(p_market)
      when nullif(trim(p_state), '') is not null
        then lower(coalesce(d.state, '')) = lower(p_state)
      else true
    end
  ),
  terms_ok as (
    select g.*
    from geo_ok g
    where coalesce(trim(p_query), '') = ''
      or g.search_tsv @@ websearch_to_tsquery('simple', p_query)
      or g.canonical_terms && coalesce(p_categories, '{}'::text[])
      or g.restaurant_categories && coalesce(p_categories, '{}'::text[])
      or g.cuisines && coalesce(p_categories, '{}'::text[])
      or g.foods && coalesce(p_categories, '{}'::text[])
      or g.activity_categories && coalesce(p_categories, '{}'::text[])
      or g.nightlife_categories && coalesce(p_categories, '{}'::text[])
      or g.features && coalesce(p_categories, '{}'::text[])
  )
  select jsonb_build_object(
    'eligibleBeforeFilters',
    (select count(*) from base),

    'eligibleAfterDomain',
    (select count(*) from domain_ok),

    'rejectedByDomain',
    (select count(*) from base)
      - (select count(*) from domain_ok),

    'eligibleAfterGeography',
    (select count(*) from geo_ok),

    'rejectedByGeography',
    (select count(*) from domain_ok)
      - (select count(*) from geo_ok),

    'eligibleAfterTerms',
    (select count(*) from terms_ok),

    'rejectedByTerms',
    (select count(*) from geo_ok)
      - (select count(*) from terms_ok),

    'returned',
    least(
      (select count(*) from terms_ok),
      least(
        greatest(coalesce(p_limit, 60), 1),
        250
      )
    ),

    'geographyStrategy',
    case
      when p_latitude is not null
        and p_longitude is not null
        and p_radius_miles is not null
        then 'coordinates'
      when nullif(trim(p_neighborhood), '') is not null
        then 'neighborhood'
      when nullif(trim(p_borough), '') is not null
        then 'borough'
      when nullif(trim(p_city), '') is not null
        then 'city'
      when nullif(trim(p_county), '') is not null
        then 'county'
      when nullif(trim(p_market), '') is not null
        then 'market'
      when nullif(trim(p_state), '') is not null
        then 'state'
      else 'none'
    end
  );
$$;


ALTER FUNCTION "public"."enterprise_search_profile_location_diagnostics"("p_query" "text", "p_domain" "text", "p_categories" "text"[], "p_market" "text", "p_state" "text", "p_county" "text", "p_borough" "text", "p_city" "text", "p_neighborhood" "text", "p_latitude" double precision, "p_longitude" double precision, "p_radius_miles" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enterprise_search_profile_locations"("p_query" "text" DEFAULT ''::"text", "p_domain" "text" DEFAULT NULL::"text", "p_categories" "text"[] DEFAULT NULL::"text"[], "p_market" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text", "p_borough" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_neighborhood" "text" DEFAULT NULL::"text", "p_latitude" double precision DEFAULT NULL::double precision, "p_longitude" double precision DEFAULT NULL::double precision, "p_radius_miles" double precision DEFAULT NULL::double precision, "p_limit" integer DEFAULT 60) RETURNS SETOF "public"."locations"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with candidates as (
    select
      p.*,
      case
        when p_latitude is not null
          and p_longitude is not null
          and p_radius_miles is not null
          and p.latitude is not null
          and p.longitude is not null
        then 3958.7613 * 2 * asin(
          sqrt(
            least(
              1,
              greatest(
                0,
                power(
                  sin(radians(p.latitude - p_latitude) / 2),
                  2
                )
                + cos(radians(p_latitude))
                * cos(radians(p.latitude))
                * power(
                  sin(radians(p.longitude - p_longitude) / 2),
                  2
                )
              )
            )
          )
        )
        else null
      end as computed_distance_miles
    from public.location_search_profiles p
    join public.locations l
      on l.id = p.location_id
    where l.active = true
      and l.is_searchable = true
      and l.is_hidden = false
      and l.is_low_level = false
      and p.profile_version >= 3

      -- A profile can qualify through either its primary domain
      -- or an explicitly supported cross-domain classification.
      and (
        p_domain is null
        or p.primary_domain = p_domain
        or p.supported_domains @> array[p_domain]::text[]
      )

      -- Require real profile evidence for the requested lane.
      -- Verification is intentionally not used as an eligibility gate.
      and (
        p_domain is null

        or (
          p_domain = 'restaurant'
          and (
            p.primary_domain = 'restaurant'
            or coalesce(cardinality(p.restaurant_categories), 0) > 0
            or coalesce(cardinality(p.cuisines), 0) > 0
            or coalesce(cardinality(p.foods), 0) > 0
          )
        )

        or (
          p_domain = 'activity'
          and (
            p.primary_domain = 'activity'
            or coalesce(cardinality(p.activity_categories), 0) > 0
            or coalesce(cardinality(p.nightlife_categories), 0) > 0
          )
        )
      )
  ),

  matched as (
    select
      c.location_id,
      c.computed_distance_miles,
      c.primary_domain,
      c.confidence,
      c.updated_at
    from candidates c
    where
      case
        -- Coordinate scope has highest priority.
        when p_latitude is not null
          and p_longitude is not null
          and p_radius_miles is not null
        then
          c.computed_distance_miles is null
          or c.computed_distance_miles <= p_radius_miles

        -- Normalize punctuation, spacing and capitalization
        -- for text-based geography comparisons.
        when nullif(trim(p_neighborhood), '') is not null
        then
          regexp_replace(
            lower(coalesce(c.neighborhood, '')),
            '[^a-z0-9]+',
            '',
            'g'
          ) =
          regexp_replace(
            lower(p_neighborhood),
            '[^a-z0-9]+',
            '',
            'g'
          )

        when nullif(trim(p_borough), '') is not null
        then
          regexp_replace(
            lower(coalesce(c.borough, '')),
            '[^a-z0-9]+',
            '',
            'g'
          ) =
          regexp_replace(
            lower(p_borough),
            '[^a-z0-9]+',
            '',
            'g'
          )

        when nullif(trim(p_city), '') is not null
        then
          regexp_replace(
            lower(coalesce(c.city, '')),
            '[^a-z0-9]+',
            '',
            'g'
          ) =
          regexp_replace(
            lower(p_city),
            '[^a-z0-9]+',
            '',
            'g'
          )

        when nullif(trim(p_county), '') is not null
        then
          regexp_replace(
            lower(coalesce(c.county, '')),
            '[^a-z0-9]+',
            '',
            'g'
          ) =
          regexp_replace(
            lower(p_county),
            '[^a-z0-9]+',
            '',
            'g'
          )

        when nullif(trim(p_market), '') is not null
        then
          regexp_replace(
            lower(coalesce(c.market, '')),
            '[^a-z0-9]+',
            '',
            'g'
          ) =
          regexp_replace(
            lower(p_market),
            '[^a-z0-9]+',
            '',
            'g'
          )

        when nullif(trim(p_state), '') is not null
        then lower(coalesce(c.state, '')) = lower(p_state)

        else true
      end

      -- Match only fields that are appropriate for the requested lane.
      and (
        coalesce(trim(p_query), '') = ''

        or case
          when p_domain = 'restaurant'
          then
            c.restaurant_categories
              && coalesce(p_categories, '{}'::text[])
            or c.cuisines
              && coalesce(p_categories, '{}'::text[])
            or c.foods
              && coalesce(p_categories, '{}'::text[])
            or c.canonical_terms
              && coalesce(p_categories, '{}'::text[])
            or c.features
              && coalesce(p_categories, '{}'::text[])
            or c.search_tsv
              @@ websearch_to_tsquery('simple', p_query)

          when p_domain = 'activity'
          then
            c.activity_categories
              && coalesce(p_categories, '{}'::text[])
            or c.nightlife_categories
              && coalesce(p_categories, '{}'::text[])
            or c.canonical_terms
              && coalesce(p_categories, '{}'::text[])
            or c.features
              && coalesce(p_categories, '{}'::text[])
            or c.search_tsv
              @@ websearch_to_tsquery('simple', p_query)

          else
            c.search_tsv
              @@ websearch_to_tsquery('simple', p_query)
            or c.canonical_terms
              && coalesce(p_categories, '{}'::text[])
        end
      )

    order by
      case
        when c.primary_domain = p_domain then 0
        else 1
      end,
      c.computed_distance_miles nulls last,
      c.confidence desc,
      c.updated_at desc,
      c.location_id

    limit least(
      greatest(coalesce(p_limit, 60), 1),
      250
    )
  )

  select l.*
  from matched m
  join public.locations l
    on l.id = m.location_id
  order by
    case
      when m.primary_domain = p_domain then 0
      else 1
    end,
    m.computed_distance_miles nulls last,
    m.confidence desc,
    m.updated_at desc,
    m.location_id;
$$;


