CREATE OR REPLACE FUNCTION "public"."fail_partner_pro_included_domain"("p_operation_id" "uuid", "p_error_code" "text") RETURNS "public"."domain_registration_operations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_operation public.domain_registration_operations%rowtype;
begin
  update public.domain_registration_operations set status='failed',error_code=p_error_code,updated_at=now() where id=p_operation_id and status<>'active' returning * into v_operation;
  if not found then select * into v_operation from public.domain_registration_operations where id=p_operation_id; end if;
  if v_operation.id is null then raise exception 'operation_not_found'; end if;
  if v_operation.status='failed' then
    update public.locations set included_domain_name=case when included_domain_claimed_at is null then null else included_domain_name end,included_domain_status=case when included_domain_claimed_at is null then null else included_domain_status end where id=v_operation.location_id;
  end if;
  return v_operation;
end;$$;


ALTER FUNCTION "public"."fail_partner_pro_included_domain"("p_operation_id" "uuid", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_search_anchor_reconciliation"("p_queue_id" "uuid", "p_error" "text", "p_retry_minutes" integer DEFAULT 15) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.search_anchor_reconciliation_queue
  set
    status =
      case
        when attempts >= max_attempts
          then 'dead_letter'
        else 'failed'
      end,
    available_at =
      case
        when attempts >= max_attempts
          then available_at
        else now()
          + make_interval(
              mins => greatest(
                1,
                least(coalesce(p_retry_minutes, 15), 1440)
              )
            )
      end,
    locked_at = null,
    locked_by = null,
    last_error = left(
      coalesce(p_error, 'Unknown reconciliation error'),
      4000
    ),
    updated_at = now()
  where id = p_queue_id;

  return found;
end;
$$;


ALTER FUNCTION "public"."fail_search_anchor_reconciliation"("p_queue_id" "uuid", "p_error" "text", "p_retry_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_worker_job"("p_job_id" "uuid", "p_error" "text", "p_retryable" boolean DEFAULT true, "p_backoff_seconds" integer DEFAULT 60, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_attempts int; v_max int; v_status text;
begin select attempt_count,max_attempts into v_attempts,v_max from public.worker_jobs where id=p_job_id; v_status := case when p_retryable and v_attempts < v_max then 'queued' when p_retryable then 'dead_letter' else 'failed' end; update public.worker_jobs set status=v_status,last_error=p_error,run_after=case when v_status='queued' then now()+make_interval(secs=>greatest(1,p_backoff_seconds)) else run_after end,updated_at=now(),completed_at=case when v_status in ('failed','dead_letter') then now() else completed_at end,lease_owner=null,lease_expires_at=null where id=p_job_id; insert into public.worker_job_events(job_id,event_type,message,metadata,created_by) values(p_job_id,v_status,p_error,coalesce(p_metadata,'{}'::jsonb),'fail_worker_job'); end $$;


ALTER FUNCTION "public"."fail_worker_job"("p_job_id" "uuid", "p_error" "text", "p_retryable" boolean, "p_backoff_seconds" integer, "p_metadata" "jsonb") OWNER TO "postgres";


