CREATE OR REPLACE FUNCTION "public"."finish_location_website_ai_generation"("p_usage_id" "uuid", "p_status" "text", "p_input_tokens" integer, "p_output_tokens" integer, "p_actual_cost_micros" bigint, "p_error_code" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_status not in ('succeeded', 'failed') then
    raise exception 'website_ai_invalid_finish_status';
  end if;

  update public.business_website_ai_usage
  set status = p_status,
      input_tokens = greatest(coalesce(p_input_tokens, 0), 0),
      output_tokens = greatest(coalesce(p_output_tokens, 0), 0),
      estimated_cost_micros = greatest(coalesce(p_actual_cost_micros, 0), 0),
      error_code = nullif(p_error_code, ''),
      completed_at = now()
  where id = p_usage_id and status = 'running';
end;
$$;


