CREATE OR REPLACE FUNCTION "public"."finish_photo_nudges_after_upload"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_old_count integer := cardinality(coalesce(old.owner_photo_urls,'{}'::text[]));
  v_new_count integer := cardinality(coalesce(new.owner_photo_urls,'{}'::text[]));
begin
  if v_new_count >= 3 and v_old_count < 3 then
    update public.profile_completion_nurture_queue
    set status = 'skipped',
        last_error = 'Owner reached recommended photo minimum',
        updated_at = now()
    where location_id = new.id
      and message_type in ('photo_reminder_day3','photo_reminder_day7')
      and status in ('pending','failed','needs_consent');

    update public.crm_tasks
    set status = 'cancelled',
        updated_at = now()
    where location_id = new.id
      and source = 'photo_completion_nudge'
      and source_record_id = new.id::text
      and status in ('open','in_progress','blocked');
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."finish_photo_nudges_after_upload"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fraud_after_signal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_subject public.fraud_subjects; v_auto_case boolean;
begin
  v_subject := public.fraud_recalculate_subject(new.subject_type,new.subject_id);
  select coalesce(auto_case,true) into v_auto_case from public.fraud_rules where rule_key=new.rule_key;
  if v_auto_case is null then v_auto_case:=true; end if;
  if v_auto_case and (v_subject.risk_score>=40 or new.severity>=4) then perform public.fraud_ensure_case(new.subject_type,new.subject_id,'Opened automatically after '||new.signal_type||' signal.'); end if;
  insert into public.fraud_audit_log(subject_type,subject_id,event_type,payload) values(new.subject_type,new.subject_id,'signal_recorded',jsonb_build_object('signal_id',new.id,'signal_type',new.signal_type,'score_delta',new.score_delta));
  return new;
end; $$;


ALTER FUNCTION "public"."fraud_after_signal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fraud_apply_action_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_state text;
begin
  v_state:=case
    when new.action_type='ban' then 'banned'
    when new.action_type in ('suspend','hold_payout','remove_content') then 'suspended'
    when new.action_type in ('limit_account','hold_publication','require_verification') then 'limited'
    when new.action_type in ('clear','restore') then 'none'
    else null
  end;

  if v_state is not null then
    insert into public.fraud_subjects(subject_type,subject_id,enforcement_state)
    values(new.subject_type,new.subject_id,v_state)
    on conflict(subject_type,subject_id)
    do update set enforcement_state=excluded.enforcement_state,updated_at=now();
  end if;

  if new.action_type in ('hold_publication','remove_content','suspend','ban') then
    if new.subject_type='event' then
      update public.events set searchable=false,updated_at=now() where id::text=new.subject_id;
    elsif new.subject_type='experience' then
      update public.experiences set searchable=false,updated_at=now() where id::text=new.subject_id;
    elsif new.subject_type='location' then
      update public.events set searchable=false,updated_at=now() where location_id::text=new.subject_id and searchable=true;
      update public.experiences set searchable=false,updated_at=now() where location_id::text=new.subject_id and searchable=true;
    elsif new.subject_type='organizer' then
      update public.events set searchable=false,updated_at=now() where organization_id::text=new.subject_id and searchable=true;
      update public.experiences set searchable=false,updated_at=now() where organization_id::text=new.subject_id and searchable=true;
    end if;
  end if;

  update public.fraud_cases
  set status=case when new.action_type in ('clear','restore') then 'closed' else 'actioned' end,
      last_activity_at=now(),
      updated_at=now()
  where id=new.case_id;

  insert into public.fraud_audit_log(case_id,subject_type,subject_id,event_type,actor_user_id,payload)
  values(new.case_id,new.subject_type,new.subject_id,'enforcement_action',new.actor_user_id,
    jsonb_build_object('action_type',new.action_type,'reason',new.reason,'ends_at',new.ends_at));
  return new;
end;
$$;


ALTER FUNCTION "public"."fraud_apply_action_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fraud_decide_subject"("p_subject_type" "text", "p_subject_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_subject public.fraud_subjects;
  v_case public.fraud_cases;
  v_action public.fraud_actions;
  v_has_action_history boolean := false;
  v_decision text := 'allow';
  v_reason text := 'no_active_risk';
  v_score integer := 0;
  v_band text := 'low';
  v_enforcement text := 'none';
begin
  select * into v_subject
  from public.fraud_subjects
  where subject_type=p_subject_type and subject_id=p_subject_id;

  if v_subject.id is not null then
    v_score := greatest(0, least(100, coalesce(v_subject.risk_score,0)));
    v_band := coalesce(v_subject.risk_band,'low');
    v_enforcement := coalesce(v_subject.enforcement_state,'none');
  end if;

  select * into v_case
  from public.fraud_cases
  where primary_subject_type=p_subject_type
    and primary_subject_id=p_subject_id
    and status in ('open','investigating','awaiting_evidence','actioned','appealed')
  order by opened_at desc
  limit 1;

  select exists(
    select 1 from public.fraud_actions
    where subject_type=p_subject_type and subject_id=p_subject_id
  ) into v_has_action_history;

  select * into v_action
  from public.fraud_actions
  where subject_type=p_subject_type
    and subject_id=p_subject_id
    and (action_type in ('clear','restore') or ends_at is null or ends_at > now())
  order by created_at desc
  limit 1;

  if v_action.id is not null then
    v_decision := case
      when v_action.action_type in ('ban','suspend','remove_content') then 'block'
      when v_action.action_type in ('hold_publication','hold_payout') then 'hold'
      when v_action.action_type in ('require_verification','limit_account') then 'step_up_verification'
      when v_action.action_type='monitor' then 'monitor'
      when v_action.action_type in ('clear','restore') then 'allow'
      else 'allow'
    end;
    v_reason := 'enforcement_' || v_action.action_type;
  elsif not v_has_action_history and v_enforcement='banned' then
    v_decision := 'block'; v_reason := 'subject_banned';
  elsif not v_has_action_history and v_enforcement='suspended' then
    v_decision := 'hold'; v_reason := 'subject_suspended';
  elsif not v_has_action_history and v_enforcement='limited' then
    v_decision := 'step_up_verification'; v_reason := 'subject_limited';
  elsif v_score >= 85 then
    v_decision := 'hold'; v_reason := 'critical_risk';
  elsif v_score >= 65 then
    v_decision := 'manual_review'; v_reason := 'high_risk';
  elsif v_case.id is not null and v_score >= 40 then
    v_decision := 'manual_review'; v_reason := 'active_fraud_case';
  elsif v_score >= 40 then
    v_decision := 'monitor'; v_reason := 'elevated_risk';
  elsif v_score >= 20 then
    v_decision := 'monitor'; v_reason := 'guarded_risk';
  end if;

  return jsonb_build_object(
    'subjectType',p_subject_type,
    'subjectId',p_subject_id,
    'decision',v_decision,
    'riskScore',v_score,
    'riskBand',v_band,
    'enforcementState',v_enforcement,
    'activeCaseId',case when v_case.id is null then null else v_case.id::text end,
    'activeCaseStatus',v_case.status,
    'actionType',v_action.action_type,
    'reasonCode',v_reason
  );
end;
$$;


ALTER FUNCTION "public"."fraud_decide_subject"("p_subject_type" "text", "p_subject_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fraud_ensure_case"("p_subject_type" "text", "p_subject_id" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_subject public.fraud_subjects; v_case_id uuid; v_priority text;
begin
  select * into v_subject from public.fraud_subjects where subject_type=p_subject_type and subject_id=p_subject_id;
  if v_subject.id is null then v_subject := public.fraud_recalculate_subject(p_subject_type,p_subject_id); end if;
  if v_subject.active_case_id is not null then
    update public.fraud_cases set risk_score=v_subject.risk_score,last_activity_at=now(),updated_at=now() where id=v_subject.active_case_id and status <> 'closed';
    if found then return v_subject.active_case_id; end if;
  end if;
  v_priority := case when v_subject.risk_score>=85 then 'urgent' when v_subject.risk_score>=65 then 'high' when v_subject.risk_score>=40 then 'medium' else 'low' end;
  insert into public.fraud_cases(primary_subject_type,primary_subject_id,title,summary,priority,risk_score)
  values(p_subject_type,p_subject_id,initcap(p_subject_type)||' fraud review · '||p_subject_id,coalesce(p_reason,'Automatically opened from fraud risk signals.'),v_priority,v_subject.risk_score)
  returning id into v_case_id;
  insert into public.fraud_case_subjects(case_id,subject_type,subject_id,relationship) values(v_case_id,p_subject_type,p_subject_id,'primary') on conflict do nothing;
  update public.fraud_subjects set active_case_id=v_case_id,updated_at=now() where subject_type=p_subject_type and subject_id=p_subject_id;
  insert into public.fraud_audit_log(case_id,subject_type,subject_id,event_type,payload) values(v_case_id,p_subject_type,p_subject_id,'case_opened',jsonb_build_object('reason',p_reason,'risk_score',v_subject.risk_score));
  return v_case_id;
end; $$;


ALTER FUNCTION "public"."fraud_ensure_case"("p_subject_type" "text", "p_subject_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."fraud_subjects" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_id" "text" NOT NULL,
    "display_label" "text",
    "risk_score" integer DEFAULT 0 NOT NULL,
    "risk_band" "text" DEFAULT 'low'::"text" NOT NULL,
    "enforcement_state" "text" DEFAULT 'none'::"text" NOT NULL,
    "active_case_id" "uuid",
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_signal_at" timestamp with time zone,
    "last_reviewed_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "fraud_subjects_enforcement_state_check" CHECK (("enforcement_state" = ANY (ARRAY['none'::"text", 'limited'::"text", 'suspended'::"text", 'banned'::"text"]))),
    CONSTRAINT "fraud_subjects_risk_band_check" CHECK (("risk_band" = ANY (ARRAY['low'::"text", 'guarded'::"text", 'elevated'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "fraud_subjects_risk_score_check" CHECK ((("risk_score" >= 0) AND ("risk_score" <= 100))),
    CONSTRAINT "fraud_subjects_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['user'::"text", 'location'::"text", 'claim'::"text", 'organizer'::"text", 'event'::"text", 'experience'::"text", 'reservation'::"text", 'order'::"text", 'payment'::"text", 'payout'::"text", 'review'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."fraud_subjects" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fraud_recalculate_subject"("p_subject_type" "text", "p_subject_id" "text") RETURNS "public"."fraud_subjects"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_score integer; v_subject public.fraud_subjects;
begin
  select greatest(0, least(100, coalesce(round(sum(score_delta * confidence))::integer, 0))) into v_score
  from public.fraud_signals where subject_type = p_subject_type and subject_id = p_subject_id and (expires_at is null or expires_at > now());
  insert into public.fraud_subjects(subject_type, subject_id, risk_score, risk_band, last_signal_at)
  values (p_subject_type, p_subject_id, v_score, public.fraud_risk_band(v_score), now())
  on conflict (subject_type, subject_id) do update set risk_score=excluded.risk_score, risk_band=excluded.risk_band, last_signal_at=excluded.last_signal_at, updated_at=now()
  returning * into v_subject;
  return v_subject;
end; $$;


ALTER FUNCTION "public"."fraud_recalculate_subject"("p_subject_type" "text", "p_subject_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fraud_risk_band"("score" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when score >= 85 then 'critical' when score >= 65 then 'high' when score >= 40 then 'elevated' when score >= 20 then 'guarded' else 'low' end;
$$;


ALTER FUNCTION "public"."fraud_risk_band"("score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_standard_location_claim_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  candidate text;
  bytes bytea;
  i integer;
begin
  loop
    bytes := extensions.gen_random_bytes(8);
    candidate := '';
    for i in 0..7 loop
      candidate := candidate || substr(alphabet, (get_byte(bytes, i) % length(alphabet)) + 1, 1);
    end loop;

    exit when not exists (
      select 1 from public.locations where claim_code = candidate
    );
  end loop;

  return candidate;
end;
$$;


ALTER FUNCTION "public"."generate_standard_location_claim_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_allowed_work_types_for_team_type"("p_team_type" "text") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select case p_team_type
    when 'ambassador' then array['field_visit','site_visit','social_outreach','phone_outreach','email_outreach','follow_up','claim_code_delivery','qr_dropoff','owner_meeting','reservation_setup','training','demo','other']::text[]
    when 'experience_team' then array['customer_support','owner_support','reservation_support','claim_support','support_ticket','listing_review','photo_review','quality_review','crm_cleanup','email_follow_up','phone_follow_up','training','admin_work','other']::text[]
    when 'sales_team' then array['social_outreach','phone_outreach','email_outreach','follow_up','owner_meeting','claim_code_delivery','reservation_demo','onboarding_support','training','admin_work','other']::text[]
    when 'support_team' then array['customer_support','owner_support','reservation_support','claim_support','support_ticket','email_follow_up','phone_follow_up','admin_work','training','other']::text[]
    when 'manager' then array['team_review','payroll_review','proof_review','quality_review','crm_cleanup','support_ticket','training','admin_work','other']::text[]
    when 'superadmin' then public.team_tools_global_work_types()
    else array[]::text[]
  end;
$$;


