CREATE OR REPLACE FUNCTION "public"."get_hf_menu_embedding_backfill_candidates"("p_limit" integer DEFAULT 100, "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text") RETURNS TABLE("location_id" "uuid", "item_name" "text", "source" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with raw_items(location_id,item_name,source,priority) as (
    select l.id,trim(i.item_name),'signature_item'::text,1
    from public.locations l cross join lateral unnest(coalesce(l.signature_items,'{}'::text[])) as i(item_name)
    where coalesce(l.is_searchable,true)=true and coalesce(l.is_hidden,false)=false and coalesce(l.active,true)=true and l.deleted_at is null
    union all
    select p.location_id,trim(i.item_name),'search_profile_food'::text,2
    from public.location_search_profiles p cross join lateral unnest(coalesce(p.foods,'{}'::text[])) as i(item_name)
  ), deduped as (
    select distinct on (location_id,lower(item_name)) location_id,item_name,source
    from raw_items where length(item_name) between 2 and 160
    order by location_id,lower(item_name),priority
  )
  select d.location_id,d.item_name,d.source
  from deduped d left join public.location_menu_item_embeddings_hf e
    on e.location_id=d.location_id and e.normalized_item_name=lower(regexp_replace(d.item_name,'\s+',' ','g'))
  where e.id is null or e.status<>'ready' or e.embedding_version<>p_embedding_version or e.item_name<>d.item_name
  order by d.location_id,d.item_name limit greatest(1,least(coalesce(p_limit,100),500));
$$;


ALTER FUNCTION "public"."get_hf_menu_embedding_backfill_candidates"("p_limit" integer, "p_embedding_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_hf_search_embedding_backfill_candidates"("p_limit" integer DEFAULT 50, "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text") RETURNS TABLE("location_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select l.id
  from public.locations l
  left join public.location_search_embeddings_hf e on e.location_id = l.id
  where coalesce(l.is_searchable, true) = true
    and coalesce(l.is_hidden, false) = false
    and coalesce(l.active, true) = true
    and l.deleted_at is null
    and lower(coalesce(l.status, '')) not in ('closed', 'permanently_closed', 'archived', 'deleted', 'hidden')
    and lower(coalesce(l.duplicate_status, '')) not in ('duplicate', 'secondary', 'merged')
    and (
      e.location_id is null
      or (e.status <> 'disabled' and e.status <> 'ready')
      or (e.status = 'ready' and e.embedding_version <> p_embedding_version)
    )
  order by
    case
      when e.location_id is null then 0
      when e.status <> 'ready' then 1
      else 2
    end,
    e.calculated_at asc nulls first,
    coalesce(l.updated_at, l.created_at) asc nulls first,
    l.id
  limit greatest(1, least(coalesce(p_limit, 50), 250));
$$;


ALTER FUNCTION "public"."get_hf_search_embedding_backfill_candidates"("p_limit" integer, "p_embedding_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_hours_repair_candidates"("max_rows" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "operating_hours" "jsonb", "google_regular_opening_hours" "jsonb", "hours_raw" "jsonb", "profile_managed_by" "text", "profile_manual_lock" boolean, "is_claimed" boolean, "claimed" boolean, "claim_status" "text", "created_at" timestamp with time zone, "hours_last_backfilled_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    l.id,
    l.operating_hours,
    l.google_regular_opening_hours,
    l.hours_raw,
    l.profile_managed_by,
    l.profile_manual_lock,
    l.is_claimed,
    l.claimed,
    l.claim_status,
    l.created_at,
    l.hours_last_backfilled_at
  from public.locations l
  where l.google_regular_opening_hours is not null
    and (
      l.operating_hours is null
      or l.operating_hours::text in ('{}', '[]', 'null', '"null"', '"{}"', '"[]"', '{"monday": "9am-5pm"}', '{"Monday": "9am-5pm"}', '{"monday":"9am-5pm"}', '{"Monday":"9am-5pm"}')
    )
  order by l.hours_last_backfilled_at asc nulls first, l.created_at asc nulls first, l.id asc
  limit greatest(1, least(coalesce(max_rows, 100), 1000));
$$;


ALTER FUNCTION "public"."get_location_hours_repair_candidates"("max_rows" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_location_website_ai_quota"("p_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_policy public.business_website_ai_policy%rowtype;
  v_month_start timestamptz := date_trunc('month', now());
  v_running integer := 0;
  v_initial integer := 0;
  v_redesign integer := 0;
  v_cost bigint := 0;
begin
  insert into public.business_website_ai_policy(location_id)
  values (p_location_id)
  on conflict (location_id) do nothing;

  select * into v_policy
  from public.business_website_ai_policy
  where location_id = p_location_id;

  select count(*) into v_running
  from public.business_website_ai_usage
  where location_id = p_location_id and status = 'running';

  select count(*) into v_initial
  from public.business_website_ai_usage
  where location_id = p_location_id
    and generation_type = 'initial_build'
    and status = 'succeeded';

  select count(*) into v_redesign
  from public.business_website_ai_usage
  where location_id = p_location_id
    and generation_type = 'full_redesign'
    and status = 'succeeded'
    and created_at >= v_month_start;

  select coalesce(sum(estimated_cost_micros), 0)::bigint into v_cost
  from public.business_website_ai_usage
  where location_id = p_location_id
    and status in ('running', 'succeeded')
    and created_at >= v_month_start;

  return jsonb_build_object(
    'initial_builds_included', v_policy.initial_builds_included,
    'initial_builds_used', v_initial,
    'initial_build_available', v_initial < v_policy.initial_builds_included,
    'full_redesigns_per_month', v_policy.full_redesigns_per_month,
    'full_redesigns_used_this_month', v_redesign,
    'full_redesign_available', v_redesign < v_policy.full_redesigns_per_month,
    'max_concurrent_generations', v_policy.max_concurrent_generations,
    'running_generations', v_running,
    'monthly_cost_ceiling_micros', v_policy.max_estimated_cost_micros_per_location_month,
    'monthly_cost_used_micros', v_cost,
    'monthly_cost_remaining_micros', greatest(v_policy.max_estimated_cost_micros_per_location_month - v_cost, 0),
    'ai_image_generation_enabled', false
  );
end;
$$;


ALTER FUNCTION "public"."get_location_website_ai_quota"("p_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_marketing_site_metrics"("p_since" timestamp with time zone DEFAULT ("now"() - '24:00:00'::interval)) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
with base as (
  select
    coalesce(nullif(session_id,''), nullif(anonymous_id,''), id::text) as visitor_key,
    coalesce(canonical_event_name, event_name, event_type) as event_key,
    page_path,
    metadata,
    created_at
  from public.analytics_events
  where created_at >= p_since
    and coalesce(is_bot, false) = false
),
create_sessions as (
  select distinct visitor_key from base where event_key = 'page_view' and page_path = '/create'
),
started as (
  select distinct b.visitor_key from base b join create_sessions c using (visitor_key)
  where b.event_key = 'search_started'
),
completed as (
  select distinct b.visitor_key from base b join started s using (visitor_key)
  where b.event_key in ('search_completed','search_results_impression')
),
engaged as (
  select distinct b.visitor_key from base b join completed c using (visitor_key)
  where b.event_key in ('location_clicked','result_clicked','pair_clicked','result_opened')
),
plan_reached as (
  select distinct b.visitor_key from base b join engaged e using (visitor_key)
  where b.page_path = '/plan'
),
plan_acted as (
  select distinct b.visitor_key from base b join plan_reached p using (visitor_key)
  where b.page_path = '/plan'
    and b.event_key in ('outing_created','reservation_started','website_clicked','directions_clicked','call_clicked','book_my_outing_clicked','outing_details_clicked')
),
session_duration as (
  select visitor_key,
         max(case when event_key = 'session_heartbeat' and (metadata->>'session_duration_seconds') ~ '^[0-9]+(\\.[0-9]+)?$'
                  then (metadata->>'session_duration_seconds')::numeric end) as seconds
  from base
  group by visitor_key
),
summary as (
  select
    count(*) filter (where event_key = 'page_view' and page_path = '/') as home_views,
    count(*) filter (where event_key = 'page_view' and page_path = '/create') as create_views,
    count(*) filter (where event_key = 'page_view' and page_path = '/plan') as plan_views,
    count(distinct visitor_key) as unique_sessions
  from base
)
select jsonb_build_object(
  'home_views', s.home_views,
  'create_views', s.create_views,
  'plan_views', s.plan_views,
  'unique_sessions', s.unique_sessions,
  'avg_session_seconds', coalesce((select round(avg(seconds)::numeric, 1) from session_duration where seconds is not null), 0),
  'funnel', jsonb_build_object(
    'create_viewed', (select count(*) from create_sessions),
    'search_started', (select count(*) from started),
    'search_completed', (select count(*) from completed),
    'result_engaged', (select count(*) from engaged),
    'plan_reached', (select count(*) from plan_reached),
    'plan_acted', (select count(*) from plan_acted)
  )
)
from summary s;
$_$;


ALTER FUNCTION "public"."get_marketing_site_metrics"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_search_embedding_backfill_candidates"("p_limit" integer DEFAULT 50) RETURNS TABLE("location_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select l.id
  from public.locations l
  left join public.location_search_embeddings e on e.location_id = l.id
  where coalesce(l.is_searchable, true) = true
    and coalesce(l.is_hidden, false) = false
    and coalesce(l.active, true) = true
    and l.deleted_at is null
    and lower(coalesce(l.status, '')) not in ('closed', 'permanently_closed', 'archived', 'deleted', 'hidden')
    and lower(coalesce(l.duplicate_status, '')) not in ('duplicate', 'secondary', 'merged')
  order by
    case
      when e.location_id is null then 0
      when e.status <> 'ready' then 1
      else 2
    end,
    e.calculated_at asc nulls first,
    coalesce(l.updated_at, l.created_at) asc nulls first,
    l.id
  limit greatest(1, least(coalesce(p_limit, 50), 250));
