CREATE OR REPLACE FUNCTION "public"."get_search_v2_advanced_location_features"("p_location_ids" "uuid"[]) RETURNS TABLE("location_id" "uuid", "result_quality_score" numeric, "result_confidence_score" numeric, "negative_feedback_rate" numeric, "result_sample_size" integer, "overall_review_quality_score" numeric, "review_confidence_score" numeric, "quiet_score" numeric, "loud_score" numeric, "romantic_score" numeric, "group_score" numeric, "family_score" numeric, "upscale_score" numeric, "casual_score" numeric, "lively_score" numeric, "relaxed_score" numeric, "booking_likelihood_score" numeric, "booking_confidence_score" numeric, "business_trust_score" numeric, "duplicate_risk_score" numeric, "ml_vibes" "text"[], "ml_features" "text"[], "ml_occasions" "text"[], "ml_audiences" "text"[], "ml_tag_confidence" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with requested as (
    select unnest(coalesce(p_location_ids, '{}'::uuid[])) as location_id
  ),
  result_best as (
    select distinct on (f.location_id)
      f.location_id,
      f.result_quality_score,
      f.confidence_score,
      f.negative_feedback_rate,
      f.sample_size
    from public.search_result_ml_features f
    where f.location_id = any(coalesce(p_location_ids, '{}'::uuid[]))
    order by f.location_id, f.confidence_score desc nulls last, f.sample_size desc nulls last, f.updated_at desc nulls last
  )
  select
    r.location_id,
    rb.result_quality_score,
    rb.confidence_score as result_confidence_score,
    rb.negative_feedback_rate,
    rb.sample_size as result_sample_size,
    rv.overall_review_quality_score,
    rv.review_confidence_score,
    rv.quiet_score,
    rv.loud_score,
    rv.romantic_score,
    rv.group_score,
    rv.family_score,
    rv.upscale_score,
    rv.casual_score,
    rv.lively_score,
    rv.relaxed_score,
    bl.booking_likelihood_score,
    bl.booking_confidence_score,
    bq.business_trust_score,
    bq.duplicate_risk_score,
    la.vibes as ml_vibes,
    la.features as ml_features,
    la.occasions as ml_occasions,
    la.audiences as ml_audiences,
    la.confidence as ml_tag_confidence
  from requested r
  left join result_best rb on rb.location_id = r.location_id
  left join public.location_review_ml_features rv on rv.location_id = r.location_id
  left join public.booking_likelihood_ml_features bl on bl.location_id = r.location_id
  left join public.business_quality_ml_features bq on bq.location_id = r.location_id
  left join public.location_ml_attributes la on la.location_id = r.location_id and la.status = 'ready';
$$;


ALTER FUNCTION "public"."get_search_v2_advanced_location_features"("p_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_theouthaven_cron_job_health"() RETURNS TABLE("jobid" bigint, "jobname" "text", "schedule" "text", "active" boolean, "function_name" "text", "has_authorization_header" boolean, "has_cron_secret_header" boolean, "has_placeholder_values" boolean, "has_supabase_function_url" boolean, "warning_notes" "text"[])
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'cron'
    AS $$
  select
    j.jobid::bigint,
    j.jobname::text,
    j.schedule::text,
    j.active::boolean,
    (regexp_match(j.command, '/functions/v1/([a-zA-Z0-9_-]+)'))[1]::text as function_name,
    (j.command ilike '%Authorization%') as has_authorization_header,
    (j.command ilike '%x-cron-secret%') as has_cron_secret_header,
    (
      j.command ilike '%YOUR_PROJECT_REF%'
      or j.command ilike '%YOUR_CRON_SECRET%'
      or j.command ilike '%PASTE_%'
    ) as has_placeholder_values,
    (j.command ilike '%functions/v1/%') as has_supabase_function_url,
    array_remove(array[
      case when not j.active then 'inactive' end,
      case when j.command not ilike '%Authorization%' then 'missing_authorization_header' end,
      case when j.command not ilike '%x-cron-secret%' then 'missing_x_cron_secret_header' end,
      case when j.command ilike '%YOUR_PROJECT_REF%' or j.command ilike '%YOUR_CRON_SECRET%' or j.command ilike '%PASTE_%' then 'placeholder_values_detected' end,
      case when j.command not ilike '%functions/v1/%' then 'not_an_edge_function_call' end
    ], null)::text[] as warning_notes
  from cron.job j
  where j.jobname ilike '%theouthaven%'
     or j.jobname in (
       'nightly-photo-backfill',
       'beta-tester-reminders',
       'admin-search-health-digest',
       'admin-cron-digest-email',
       'nightly-demo-reset',
       'team-session-watchdog'
     )
     or j.command ilike '%functions/v1/%'
     or j.command ilike '%theouthaven%'
  order by j.jobname;
$$;


ALTER FUNCTION "public"."get_theouthaven_cron_job_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_location_preference_similarity"("p_user_id" "uuid", "p_location_ids" "uuid"[], "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text") RETURNS TABLE("location_id" "uuid", "similarity" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select l.location_id,(1-(l.embedding<=>u.embedding))::numeric
  from public.user_search_preference_vectors u join public.location_search_embeddings_hf l on l.location_id=any(p_location_ids)
  where u.user_id=p_user_id and u.status='ready' and u.embedding_version=p_embedding_version and l.status='ready' and l.embedding_version=p_embedding_version
  order by l.embedding<=>u.embedding;
$$;


