CREATE OR REPLACE FUNCTION "public"."log_first_claim_profile_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.profile_last_owner_update_at is distinct from old.profile_last_owner_update_at
     and new.profile_last_owner_update_at is not null
     and not exists (
       select 1
       from public.claim_funnel_events e
       where e.location_id = new.id
         and e.event_type = 'profile_updated'
     ) then
    insert into public.claim_funnel_events (
      location_id,
      event_type,
      metadata,
      created_at
    ) values (
      new.id,
      'profile_updated',
      jsonb_build_object(
        'source', 'owner_profile_save',
        'profile_last_owner_update_at', new.profile_last_owner_update_at
      ),
      coalesce(new.profile_last_owner_update_at, now())
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."log_first_claim_profile_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lookup_local_area"("p_latitude" double precision, "p_longitude" double precision, "p_state" "text" DEFAULT NULL::"text") RETURNS TABLE("area_code" "text", "area_name" "text", "area_type" "text", "area_source" "text", "borough" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_nyc record;
begin
  if p_latitude is null or p_longitude is null then
    return;
  end if;

  if upper(coalesce(p_state,'NY')) = 'NY'
     and p_latitude between 40.45 and 40.95
     and p_longitude between -74.30 and -73.65 then
    select * into v_nyc
    from public.lookup_nyc_neighborhood(p_latitude, p_longitude)
    limit 1;

    if found then
      area_code := v_nyc.nta_code;
      area_name := v_nyc.neighborhood;
      area_type := 'nyc_nta';
      area_source := 'nyc_dcp_2020_nta_coordinates';
      borough := v_nyc.borough;
      return next;
      return;
    end if;
  end if;

  return query
  select
    b.geo_id,
    b.name,
    b.area_type,
    'census_tigerweb_2025_coordinates'::text,
    null::text
  from public.local_area_boundaries b
  where (p_state is null or b.state = upper(p_state))
    and extensions.st_covers(
      b.geom,
      extensions.st_setsrid(extensions.st_makepoint(p_longitude, p_latitude),4326)
    )
  order by b.priority asc, extensions.st_area(b.geom::extensions.geography) asc, b.geo_id
  limit 1;
end;
$$;


ALTER FUNCTION "public"."lookup_local_area"("p_latitude" double precision, "p_longitude" double precision, "p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lookup_nyc_neighborhood"("p_latitude" double precision, "p_longitude" double precision) RETURNS TABLE("nta_code" "text", "neighborhood" "text", "borough" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select n.nta_code, n.name, n.borough
  from public.nyc_neighborhoods n
  where p_latitude between 40.45 and 40.95
    and p_longitude between -74.30 and -73.65
    and extensions.st_covers(
      n.geom,
      extensions.st_setsrid(extensions.st_makepoint(p_longitude, p_latitude), 4326)
    )
  order by case when n.nta_type = '0' then 0 else 1 end, n.nta_code
  limit 1;
$$;


ALTER FUNCTION "public"."lookup_nyc_neighborhood"("p_latitude" double precision, "p_longitude" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_hf_location_menu_items"("p_query_embedding" "public"."vector", "p_market_key" "text" DEFAULT NULL::"text", "p_match_count" integer DEFAULT 50, "p_min_similarity" numeric DEFAULT 0.55, "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text") RETURNS TABLE("location_id" "uuid", "item_name" "text", "source" "text", "similarity" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select e.location_id,e.item_name,e.source,(1-(e.embedding<=>p_query_embedding))::numeric
  from public.location_menu_item_embeddings_hf e join public.locations l on l.id=e.location_id
  where e.status='ready' and e.embedding_version=p_embedding_version
    and coalesce(l.is_searchable,true)=true and coalesce(l.is_hidden,false)=false and coalesce(l.active,true)=true and l.deleted_at is null
    and (p_market_key is null or p_market_key='' or lower(coalesce(l.market,l.source_market,''))=lower(p_market_key))
    and (1-(e.embedding<=>p_query_embedding))>=p_min_similarity
  order by e.embedding<=>p_query_embedding limit greatest(1,least(coalesce(p_match_count,50),150));
$$;


ALTER FUNCTION "public"."match_hf_location_menu_items"("p_query_embedding" "public"."vector", "p_market_key" "text", "p_match_count" integer, "p_min_similarity" numeric, "p_embedding_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_hf_location_search_embeddings"("p_query_embedding" "public"."vector", "p_expected_domain" "text", "p_market_key" "text" DEFAULT NULL::"text", "p_match_count" integer DEFAULT 100, "p_min_similarity" numeric DEFAULT 0.50, "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text", "p_food_intent" boolean DEFAULT false) RETURNS TABLE("location_id" "uuid", "similarity" numeric, "semantic_similarity" numeric, "food_similarity" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with general_candidates as materialized (
    select
      e.location_id,
      (1 - (e.embedding <=> p_query_embedding))::numeric as semantic_similarity,
      case when e.food_embedding is null then null::numeric else (1 - (e.food_embedding <=> p_query_embedding))::numeric end as food_similarity
    from public.location_search_embeddings_hf e
    join public.locations l on l.id = e.location_id
    where e.status = 'ready'
      and e.embedding is not null
      and e.embedding_provider = 'huggingface'
      and e.embedding_version = p_embedding_version
      and e.canonical_search_type in (p_expected_domain, 'hybrid')
      and (p_market_key is null or p_market_key = '' or lower(coalesce(e.market_key, '')) = lower(p_market_key))
      and coalesce(l.is_searchable, true) = true
      and coalesce(l.is_hidden, false) = false
      and coalesce(l.active, true) = true
      and l.deleted_at is null
      and lower(coalesce(l.status, '')) not in ('closed','permanently_closed','archived','deleted','hidden')
      and lower(coalesce(l.duplicate_status, '')) not in ('duplicate','secondary','merged')
    order by e.embedding <=> p_query_embedding
    limit greatest(20, least(coalesce(p_match_count, 100) * 2, 250))
  ),
  food_candidates as materialized (
    select
      e.location_id,
      (1 - (e.embedding <=> p_query_embedding))::numeric as semantic_similarity,
      (1 - (e.food_embedding <=> p_query_embedding))::numeric as food_similarity
    from public.location_search_embeddings_hf e
    join public.locations l on l.id = e.location_id
    where p_food_intent
      and p_expected_domain = 'restaurant'
      and e.status = 'ready'
      and e.embedding is not null
      and e.food_embedding is not null
      and e.embedding_provider = 'huggingface'
      and e.embedding_version = p_embedding_version
      and e.canonical_search_type in (p_expected_domain, 'hybrid')
      and (p_market_key is null or p_market_key = '' or lower(coalesce(e.market_key, '')) = lower(p_market_key))
      and coalesce(l.is_searchable, true) = true
      and coalesce(l.is_hidden, false) = false
      and coalesce(l.active, true) = true
      and l.deleted_at is null
      and lower(coalesce(l.status, '')) not in ('closed','permanently_closed','archived','deleted','hidden')
      and lower(coalesce(l.duplicate_status, '')) not in ('duplicate','secondary','merged')
    order by e.food_embedding <=> p_query_embedding
    limit greatest(20, least(coalesce(p_match_count, 100) * 2, 250))
  ),
  combined as (
    select * from general_candidates
    union all
    select * from food_candidates
  ),
  ranked as (
    select
      c.location_id,
      max(c.semantic_similarity)::numeric as semantic_similarity,
      max(c.food_similarity)::numeric as food_similarity,
      case
        when p_food_intent and p_expected_domain = 'restaurant'
          then greatest(max(c.semantic_similarity), coalesce(max(c.food_similarity), -1))
        else max(c.semantic_similarity)
      end::numeric as similarity
    from combined c
    group by c.location_id
  )
  select r.location_id, r.similarity, r.semantic_similarity, r.food_similarity
  from ranked r
  where r.similarity >= p_min_similarity
  order by r.similarity desc
  limit greatest(1, least(coalesce(p_match_count, 100), 250));
$$;


ALTER FUNCTION "public"."match_hf_location_search_embeddings"("p_query_embedding" "public"."vector", "p_expected_domain" "text", "p_market_key" "text", "p_match_count" integer, "p_min_similarity" numeric, "p_embedding_version" "text", "p_food_intent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_hf_search_inventory_embeddings"("p_query_embedding" "public"."vector", "p_source_kinds" "text"[] DEFAULT ARRAY['event'::"text", 'experience'::"text"], "p_market_key" "text" DEFAULT NULL::"text", "p_match_count" integer DEFAULT 40, "p_min_similarity" numeric DEFAULT 0.48, "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text") RETURNS TABLE("source_kind" "text", "source_id" "uuid", "location_id" "uuid", "similarity" numeric, "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    e.source_kind,
    e.source_id,
    e.location_id,
    (1-(e.embedding<=>p_query_embedding))::numeric as similarity,
    e.starts_at,
    e.ends_at
  from public.search_inventory_embeddings_hf e
  where e.searchable = true
    and e.embedding_version = p_embedding_version
    and e.source_kind = any(coalesce(p_source_kinds, array['event','experience']::text[]))
    and (p_market_key is null or p_market_key='' or lower(coalesce(e.market_key,''))=lower(p_market_key))
    and (e.source_kind <> 'event' or coalesce(e.ends_at,e.starts_at,now()) >= now() - interval '6 hours')
    and (1-(e.embedding<=>p_query_embedding)) >= p_min_similarity
  order by e.embedding<=>p_query_embedding
  limit greatest(1,least(coalesce(p_match_count,40),100));
$$;


ALTER FUNCTION "public"."match_hf_search_inventory_embeddings"("p_query_embedding" "public"."vector", "p_source_kinds" "text"[], "p_market_key" "text", "p_match_count" integer, "p_min_similarity" numeric, "p_embedding_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_location_photo_embeddings_siglip"("p_query_embedding" "public"."vector", "p_match_count" integer DEFAULT 40, "p_min_similarity" numeric DEFAULT 0.45, "p_model_version" "text" DEFAULT 'hf-siglip-base-patch16-224:v1'::"text") RETURNS TABLE("location_id" "uuid", "photo_url" "text", "similarity" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select p.location_id,p.photo_url,(1-(p.embedding<=>p_query_embedding))::numeric as similarity
  from public.location_photo_embeddings_siglip p
  join public.locations l on l.id=p.location_id
  where p.status='ready'
    and p.model_version=p_model_version
    and coalesce(l.is_searchable,true)=true
    and coalesce(l.is_hidden,false)=false
    and coalesce(l.active,true)=true
    and l.deleted_at is null
    and lower(coalesce(l.status,'')) not in ('closed','permanently_closed','archived','deleted','hidden')
    and lower(coalesce(l.duplicate_status,'')) not in ('duplicate','secondary','merged')
    and (1-(p.embedding<=>p_query_embedding)) >= p_min_similarity
  order by p.embedding<=>p_query_embedding
  limit greatest(1,least(coalesce(p_match_count,40),100));
$$;


ALTER FUNCTION "public"."match_location_photo_embeddings_siglip"("p_query_embedding" "public"."vector", "p_match_count" integer, "p_min_similarity" numeric, "p_model_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_location_search_embeddings"("p_query_embedding" "public"."vector", "p_expected_domain" "text", "p_market_key" "text" DEFAULT NULL::"text", "p_match_count" integer DEFAULT 100, "p_min_similarity" numeric DEFAULT 0.55, "p_embedding_version" "text" DEFAULT 'search-embedding:v1'::"text") RETURNS TABLE("location_id" "uuid", "similarity" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    e.location_id,
    (1 - (e.embedding <=> p_query_embedding))::numeric as similarity
  from public.location_search_embeddings e
  join public.locations l
    on l.id = e.location_id
  where e.status = 'ready'
    and e.embedding_version = p_embedding_version
    and e.canonical_search_type in (p_expected_domain, 'hybrid')
    and (
      p_market_key is null
      or p_market_key = ''
      or lower(coalesce(e.market_key, '')) = lower(p_market_key)
    )
    and coalesce(l.is_searchable, true) = true
    and coalesce(l.is_hidden, false) = false
    and coalesce(l.active, true) = true
    and l.deleted_at is null
    and lower(coalesce(l.status, '')) not in (
      'closed',
      'permanently_closed',
      'archived',
      'deleted',
      'hidden'
    )
    and lower(coalesce(l.duplicate_status, '')) not in (
      'duplicate',
      'secondary',
      'merged'
    )
    and (
      1 - (e.embedding <=> p_query_embedding)
    ) >= p_min_similarity
  order by e.embedding <=> p_query_embedding
  limit greatest(1, least(p_match_count, 250));
$$;


ALTER FUNCTION "public"."match_location_search_embeddings"("p_query_embedding" "public"."vector", "p_expected_domain" "text", "p_market_key" "text", "p_match_count" integer, "p_min_similarity" numeric, "p_embedding_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_locations"("query_embedding" "public"."vector", "match_threshold" double precision, "match_count" integer) RETURNS TABLE("id" "uuid", "name" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    locations.id,
    locations.name,
    1 - (locations.embedding <=> query_embedding) as similarity
  from locations
  where locations.embedding is not null
    and 1 - (locations.embedding <=> query_embedding) > match_threshold
  order by similarity desc
  limit match_count;
$$;


ALTER FUNCTION "public"."match_locations"("query_embedding" "public"."vector", "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_search_semantic_query_memory"("p_query_embedding" "public"."vector", "p_market_key" "text" DEFAULT NULL::"text", "p_match_count" integer DEFAULT 5, "p_min_similarity" numeric DEFAULT 0.90, "p_embedding_version" "text" DEFAULT 'hf-bge-small-en-v1.5:v2'::"text") RETURNS TABLE("id" "uuid", "representative_query" "text", "normalized_query" "text", "search_plan" "jsonb", "confidence" numeric, "success_score" numeric, "review_status" "text", "similarity" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select m.id,m.representative_query,m.normalized_query,m.search_plan,m.confidence,m.success_score,m.review_status,(1-(m.query_embedding<=>p_query_embedding))::numeric
  from public.search_semantic_query_memory m
  where m.review_status='approved' and m.embedding_version=p_embedding_version
    and (p_market_key is null or p_market_key='' or m.market_key is null or lower(m.market_key)=lower(p_market_key))
    and (1-(m.query_embedding<=>p_query_embedding))>=p_min_similarity
  order by m.query_embedding<=>p_query_embedding limit greatest(1,least(coalesce(p_match_count,5),20));
$$;


ALTER FUNCTION "public"."match_search_semantic_query_memory"("p_query_embedding" "public"."vector", "p_market_key" "text", "p_match_count" integer, "p_min_similarity" numeric, "p_embedding_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_support_learned_response"("p_question" "text", "p_threshold" real DEFAULT 0.84) RETURNS TABLE("id" "uuid", "response_text" "text", "category" "text", "priority" "text", "source_article_ids" "uuid"[], "similarity_score" real, "confidence" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select r.id,r.response_text,r.category,r.priority,r.source_article_ids,similarity(r.normalized_question,p_question)::real,r.confidence
  from public.support_learned_responses r
  where r.status='active' and r.confidence>=0.95 and r.success_count>=5
    and similarity(r.normalized_question,p_question)>=greatest(0.70,least(0.98,p_threshold))
  order by similarity(r.normalized_question,p_question) desc,r.confidence desc,r.success_count desc limit 1;
$$;


ALTER FUNCTION "public"."match_support_learned_response"("p_question" "text", "p_threshold" real) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_theouthaven_full_sentence"("query_embedding" "public"."vector", "match_count" integer DEFAULT 30, "min_similarity" double precision DEFAULT 0.20) RETURNS TABLE("id" "uuid", "source_table" "text", "similarity" double precision, "search_document" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  (
    select
      r.id,
      'restaurants'::text as source_table,
      1 - (r.embedding <=> query_embedding) as similarity,
      r.search_document
    from public.restaurants r
    where r.embedding is not null
    order by r.embedding <=> query_embedding
    limit 15
  )

  union all

  (
    select
      a.id,
      'activities'::text as source_table,
      1 - (a.embedding <=> query_embedding) as similarity,
      a.search_document
    from public.activities a
    where a.embedding is not null
    order by a.embedding <=> query_embedding
    limit 15
  )

  union all

  (
    select
      l.id,
      'locations'::text as source_table,
      1 - (l.embedding <=> query_embedding) as similarity,
      l.search_document
    from public.locations l
    where l.embedding is not null
    order by l.embedding <=> query_embedding
    limit 5
  )

  order by similarity desc
  limit match_count;
$$;


ALTER FUNCTION "public"."match_theouthaven_full_sentence"("query_embedding" "public"."vector", "match_count" integer, "min_similarity" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_text_arrays"("existing" "text"[], "additions" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select array(
    select distinct lower(trim(x))
    from unnest(coalesce(existing, '{}') || coalesce(additions, '{}')) as x
    where nullif(trim(x), '') is not null
  );
$$;


ALTER FUNCTION "public"."merge_text_arrays"("existing" "text"[], "additions" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_location_analytics_event_name"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.event_name := case
    when new.metadata->>'location_event_type' = 'click' then 'location_clicked'
    when new.metadata->>'location_event_type' = 'save' then 'location_saved'
    when new.metadata->>'location_event_type' = 'view' then 'location_viewed'
    when new.metadata->>'location_event_type' = 'booking' then 'reservation_completed'
    when new.metadata->>'location_event_type' = 'skip' then 'location_skipped'
    when new.event_type = 'search_click' then 'location_clicked'
    when new.event_type = 'share_click' then 'location_saved'
    when new.event_type = 'reservation_completed' then 'reservation_completed'
    when new.event_type = 'reservation_started' then 'reservation_started'
    when new.event_type = 'phone_click' then 'phone_clicked'
    when new.event_type = 'website_click' then 'website_clicked'
    else coalesce(nullif(new.event_name, ''), 'unknown')
  end;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_location_analytics_event_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_reservation_customer_phone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  digits text;
begin
  if new.customer_phone is null or btrim(new.customer_phone) = '' then
    return new;
  end if;

  digits := regexp_replace(new.customer_phone, '\D', '', 'g');

  if length(digits) = 10 then
    new.customer_phone := '+1' || digits;
  elsif length(digits) = 11 and left(digits, 1) = '1' then
    new.customer_phone := '+' || digits;
  else
    new.customer_phone := btrim(new.customer_phone);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_reservation_customer_phone"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_search_anchor_name"("input_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  select trim(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(
            lower(coalesce(input_text, '')),
            '&',
            ' and ',
            'g'
          ),
          '\m(llc|inc|corp|corporation|company|co)\M\.?',
          ' ',
          'gi'
        ),
        '[^a-z0-9]+',
        ' ',
        'g'
      ),
      '\s+',
      ' ',
      'g'
    )
  );
$$;


ALTER FUNCTION "public"."normalize_search_anchor_name"("input_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_apply_google_business_status_visibility"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.google_business_status is distinct from old.google_business_status then
    new.google_business_status_checked_at := coalesce(new.google_business_status_checked_at, now());
  end if;

  if new.google_business_status = 'CLOSED_PERMANENTLY' then
    new.is_searchable := false;
    new.is_hidden := true;
    new.publish_ready := false;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."oh_apply_google_business_status_visibility"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_auto_merge_exact_live_duplicates"("p_limit" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r record; merge_count integer := 0;
begin
  perform public.oh_find_live_location_duplicates(p_limit);
  for r in select * from public.location_duplicate_review where status='pending' and duplicate_score >= 100 and suggested_master_id is not null and match_reasons && array['same_location_key','same_google_place_id','same_normalized_name_address'] order by duplicate_score desc, created_at asc limit greatest(1, least(coalesce(p_limit,100),500)) loop
    perform public.oh_merge_live_location_duplicate(r.suggested_master_id, case when r.location_a_id = r.suggested_master_id then r.location_b_id else r.location_a_id end, 'auto_merge_exact_live_duplicates');
    merge_count := merge_count + 1;
  end loop;
  return merge_count;
end; $$;


ALTER FUNCTION "public"."oh_auto_merge_exact_live_duplicates"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_calculate_location_quality"("p_name" "text", "p_address" "text", "p_city" "text", "p_state" "text", "p_zip" "text", "p_lat" numeric, "p_lng" numeric, "p_category" "text", "p_phone" "text", "p_website" "text", "p_image" "text", "p_rating" numeric, "p_review_count" integer) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare score numeric := 0; begin
  if coalesce(trim(p_name), '') <> '' then score := score + 15; end if; if coalesce(trim(p_address), '') <> '' then score := score + 15; end if;
  if coalesce(trim(p_city), '') <> '' then score := score + 8; end if; if coalesce(trim(p_state), '') <> '' then score := score + 6; end if; if coalesce(trim(p_zip), '') <> '' then score := score + 6; end if;
  if p_lat is not null and p_lng is not null then score := score + 15; end if; if coalesce(trim(p_category), '') <> '' then score := score + 15; end if;
  if coalesce(trim(p_phone), '') <> '' then score := score + 6; end if; if coalesce(trim(p_website), '') <> '' then score := score + 6; end if; if coalesce(trim(p_image), '') <> '' then score := score + 6; end if;
  if coalesce(p_rating, 0) >= 4 then score := score + 4; end if; if coalesce(p_review_count, 0) >= 25 then score := score + 4; end if; return least(100, score);
end; $$;


ALTER FUNCTION "public"."oh_calculate_location_quality"("p_name" "text", "p_address" "text", "p_city" "text", "p_state" "text", "p_zip" "text", "p_lat" numeric, "p_lng" numeric, "p_category" "text", "p_phone" "text", "p_website" "text", "p_image" "text", "p_rating" numeric, "p_review_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_cleanup_low_level_locations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total_scanned integer := 0;
  v_marked_low_level integer := 0;
  v_hidden_low_level integer := 0;
  v_nyc_import_unverified integer := 0;
  v_generic_restaurant_unverified integer := 0;
  v_missing_photo_marked integer := 0;
  v_restaurants_marked integer := 0;
  v_activities_marked integer := 0;
  v_still_searchable_low_level integer := 0;
begin
  select count(*) into v_total_scanned
  from public.locations;

  with evaluated as (
    select
      l.id,
      l.location_type,
      l.rating,
      l.review_count,
      l.has_photos,
      l.photo_status,
      l.curation_tier,
      l.public_visibility_tier,
      public.oh_location_low_level_text(
        l.name,
        l.restaurant_name,
        l.activity_name,
        l.location_type,
        l.primary_category,
        coalesce(to_jsonb(l)->>'category', ''),
        l.cuisine,
        l.cuisine_type,
        coalesce(to_jsonb(l)->>'food_type', ''),
        coalesce(to_jsonb(l)->>'activity_type', ''),
        l.description,
        coalesce(to_jsonb(l)->>'search_document', ''),
        case
          when jsonb_typeof(to_jsonb(l)->'tags') = 'array'
          then array(select jsonb_array_elements_text(to_jsonb(l)->'tags'))
          else array[]::text[]
        end,
        case
          when jsonb_typeof(to_jsonb(l)->'google_types') = 'array'
          then array(select jsonb_array_elements_text(to_jsonb(l)->'google_types'))
          else array[]::text[]
        end,
        coalesce(to_jsonb(l)->>'source_table', ''),
        coalesce(to_jsonb(l)->>'import_source', ''),
        coalesce(to_jsonb(l)->>'source', '')
      ) as low_text,
      public.oh_safe_lower_text(
        concat_ws(
          ' ',
          coalesce(to_jsonb(l)->>'source_table', ''),
          coalesce(to_jsonb(l)->>'import_source', ''),
          coalesce(to_jsonb(l)->>'source', '')
        )
      ) as source_text
    from public.locations l
  ),
  reasons as (
    select
      e.id,
      public.oh_low_level_reason(
        e.location_type,
        e.low_text,
        e.rating,
        e.review_count,
        e.has_photos,
        e.photo_status,
        e.curation_tier,
        e.public_visibility_tier,
        e.source_text
      ) as reason,
      e.location_type,
      e.low_text,
      e.source_text,
      e.has_photos,
      e.photo_status,
      e.rating,
      e.review_count,
      e.curation_tier,
      e.public_visibility_tier
    from evaluated e
  ),
  low_rows as (
    select *
    from reasons
    where public.oh_is_low_level_location(
      location_type,
      low_text,
      rating,
      review_count,
      has_photos,
      photo_status,
      curation_tier,
      public_visibility_tier,
      source_text
    )
  ),
  updated as (
    update public.locations l
    set
      is_low_level = true,
      low_level_detected_at = coalesce(l.low_level_detected_at, now()),
      low_level_source = case
        when r.reason = 'nyc_import_unverified' then 'nyc_import_cleanup'
        when r.reason = 'generic_restaurant_unverified' then 'generic_restaurant_cleanup'
        else 'auto_cleanup'
      end,
      low_level_reason = coalesce(r.reason, 'unknown_low_level'),
      public_visibility_tier = case
        when coalesce(l.public_visibility_tier, 'standard') in ('premium', 'curated')
          then l.public_visibility_tier
        when coalesce(r.reason, '') in (
          'smoke_liquor_pharmacy_gas',
          'grocery_convenience',
          'deli_bodega_market',
          'nyc_import_unverified',
          'generic_restaurant_unverified'
        )
          then 'hidden'
        else 'low_level'
      end,
      curation_tier = case
        when coalesce(l.curation_tier, 'standard') in ('premium', 'curated', 'date_worthy', 'featured', 'high_value')
          then l.curation_tier
        else 'low_level'
      end,
      search_boost = least(coalesce(l.search_boost, 0), -500),
      date_score = least(coalesce(l.date_score, 50), 15),
      is_searchable = false,
      is_hidden = case
        when coalesce(r.reason, '') in (
          'smoke_liquor_pharmacy_gas',
          'grocery_convenience',
          'deli_bodega_market',
          'nyc_import_unverified',
          'generic_restaurant_unverified'
        )
          then true
        else coalesce(l.is_hidden, false)
      end,
      data_status = case
        when coalesce(l.data_status, 'clean') = 'clean' then 'needs_review'
        else l.data_status
      end,
      quality_status = 'low_level_review',
      source_quality_status = case
        when r.reason in ('nyc_import_unverified', 'generic_restaurant_unverified')
          then 'imported_unverified'
        else 'low_level_review'
      end,
      import_confidence = case
        when r.reason in ('nyc_import_unverified', 'generic_restaurant_unverified')
          then 'low'
        else coalesce(l.import_confidence, 'unknown')
      end
    from low_rows r
    where l.id = r.id
    returning
      l.id,
      l.location_type,
      l.public_visibility_tier,
      l.is_hidden,
      l.low_level_reason,
      l.is_searchable
  )
  select
    count(*),
    count(*) filter (where public_visibility_tier = 'hidden' or is_hidden is true),
    count(*) filter (where low_level_reason = 'nyc_import_unverified'),
    count(*) filter (where low_level_reason = 'generic_restaurant_unverified'),
    count(*) filter (where low_level_reason = 'missing_photo'),
    count(*) filter (where location_type = 'restaurant'),
    count(*) filter (where location_type <> 'restaurant')
  into
    v_marked_low_level,
    v_hidden_low_level,
    v_nyc_import_unverified,
    v_generic_restaurant_unverified,
    v_missing_photo_marked,
    v_restaurants_marked,
    v_activities_marked
  from updated;

  select count(*) into v_still_searchable_low_level
  from public.locations
  where coalesce(is_low_level, false) = true
  and coalesce(is_searchable, false) = true;

  return jsonb_build_object(
    'success', true,
    'total_scanned', v_total_scanned,
    'marked_low_level', v_marked_low_level,
    'hidden_low_level', v_hidden_low_level,
    'nyc_import_unverified', v_nyc_import_unverified,
    'generic_restaurant_unverified', v_generic_restaurant_unverified,
    'missing_photo_marked', v_missing_photo_marked,
    'restaurants_marked', v_restaurants_marked,
    'activities_marked', v_activities_marked,
    'still_searchable_low_level', v_still_searchable_low_level
  );
end;
$$;


ALTER FUNCTION "public"."oh_cleanup_low_level_locations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_enforce_location_duplicate_invariants"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_target_status text;
  v_target_duplicate_of uuid;
  v_target_google_place_id text;
begin
  if new.duplicate_of is not null then
    if new.id is not null and new.duplicate_of = new.id then
      raise exception 'a location cannot be a duplicate of itself';
    end if;

    select l.duplicate_status, l.duplicate_of, nullif(l.google_place_id, '')
      into v_target_status, v_target_duplicate_of, v_target_google_place_id
    from public.locations l
    where l.id = new.duplicate_of
      and coalesce(l.active, true) = true
      and l.deleted_at is null;

    if not found then
      raise exception 'duplicate target must be an active canonical location';
    end if;

    if v_target_duplicate_of is not null or coalesce(v_target_status, '') = 'duplicate' then
      raise exception 'duplicate target must be canonical';
    end if;

    if exists (
      select 1 from public.locations child
      where child.duplicate_of = new.id
        and child.id <> coalesce(new.id, gen_random_uuid())
    ) then
      raise exception 'cannot mark a canonical location as duplicate while duplicates point to it';
    end if;

    if nullif(new.google_place_id, '') is not null
       and v_target_google_place_id is not null
       and new.google_place_id <> v_target_google_place_id then
      raise exception 'cannot confirm duplicate across different Google Place IDs';
    end if;

    new.duplicate_status := 'duplicate';
    new.is_searchable := false;
    new.is_hidden := true;
    new.publish_ready := false;
  elsif coalesce(new.duplicate_status, '') = 'duplicate' then
    raise exception 'confirmed duplicate requires duplicate_of';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."oh_enforce_location_duplicate_invariants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_find_live_location_duplicates"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 500), 2000));
  v_changed integer := 0;
  v_pending integer := 0;
begin
  with base as materialized (
    select *
    from public.locations l
    where coalesce(l.duplicate_status, '') <> 'duplicate'
      and coalesce((to_jsonb(l)->>'is_hidden')::boolean, false) = false
      and (to_jsonb(l)->>'deleted_at') is null
  ),
  same_location_key as (
    select least(a.id,b.id) location_a_id, greatest(a.id,b.id) location_b_id, 100::numeric duplicate_score, array['same_location_key']::text[] reasons
    from base a join base b on a.id < b.id and nullif(a.location_key,'') is not null and a.location_key = b.location_key
    limit v_limit
  ),
  same_google_place_id as (
    select least(a.id,b.id), greatest(a.id,b.id), 100::numeric, array['same_google_place_id']::text[]
    from base a join base b on a.id < b.id and nullif(a.google_place_id,'') is not null and a.google_place_id = b.google_place_id
    limit v_limit
  ),
  same_normalized_name_address as (
    select least(a.id,b.id), greatest(a.id,b.id), 100::numeric, array['same_normalized_name_address']::text[]
    from base a join base b on a.id < b.id
      and nullif(a.normalized_name,'') is not null and a.normalized_name = b.normalized_name
      and nullif(a.normalized_address,'') is not null and a.normalized_address = b.normalized_address
      and coalesce(public.oh_normalize_text(a.city),'') = coalesce(public.oh_normalize_text(b.city),'')
      and coalesce(upper(a.state),'') = coalesce(upper(b.state),'')
    limit v_limit
  ),
  same_phone_similar_name as (
    select least(a.id,b.id), greatest(a.id,b.id), 95::numeric, array['same_phone']::text[]
    from base a join base b on a.id < b.id
      and nullif(a.normalized_phone,'') is not null and a.normalized_phone = b.normalized_phone
      and similarity(coalesce(a.normalized_name,''), coalesce(b.normalized_name,'')) >= 0.72
    limit v_limit
  ),
  similar_name_same_address as (
    select least(a.id,b.id), greatest(a.id,b.id), round(similarity(coalesce(a.normalized_name,''), coalesce(b.normalized_name,'')) * 100)::numeric, array['similar_name_same_address']::text[]
    from base a join base b on a.id < b.id
      and nullif(a.normalized_address,'') is not null and a.normalized_address = b.normalized_address
      and coalesce(public.oh_normalize_text(a.city),'') = coalesce(public.oh_normalize_text(b.city),'')
      and coalesce(upper(a.state),'') = coalesce(upper(b.state),'')
      and similarity(coalesce(a.normalized_name,''), coalesce(b.normalized_name,'')) >= 0.72
    limit v_limit
  ),
  unioned as (
    select * from same_location_key
    union all select * from same_google_place_id
    union all select * from same_normalized_name_address
    union all select * from same_phone_similar_name
    union all select * from similar_name_same_address
  ),
  grouped as (
    select location_a_id, location_b_id, max(duplicate_score) duplicate_score, array_agg(distinct reason) match_reasons
    from unioned u cross join lateral unnest(u.reasons) reason
    group by location_a_id, location_b_id
    order by max(duplicate_score) desc
    limit v_limit
  ),
  enriched as (
    select g.location_a_id, g.location_b_id, g.duplicate_score,
      (g.match_reasons
        || case when coalesce(a.is_searchable,false) and coalesce(b.is_searchable,false) then array['both_searchable']::text[] else '{}'::text[] end
        || case when coalesce(a.location_type,'') <> coalesce(b.location_type,'') and (coalesce(a.location_type,'') in ('restaurant','activity','nightlife') or coalesce(b.location_type,'') in ('restaurant','activity','nightlife')) then array['cross_type_restaurant_activity']::text[] else '{}'::text[] end
      ) match_reasons,
      case when (case when nullif(a.google_place_id,'') is not null then 1 else 0 end, case when coalesce(cardinality(a.images),0) > 0 or nullif(coalesce(a.main_image,a.image_url),'') is not null then 1 else 0 end, coalesce(a.quality_score,0), coalesce(a.review_count,0), case when coalesce(a.is_searchable,false) then 1 else 0 end, -extract(epoch from coalesce(a.created_at, now()))) >=
                (case when nullif(b.google_place_id,'') is not null then 1 else 0 end, case when coalesce(cardinality(b.images),0) > 0 or nullif(coalesce(b.main_image,b.image_url),'') is not null then 1 else 0 end, coalesce(b.quality_score,0), coalesce(b.review_count,0), case when coalesce(b.is_searchable,false) then 1 else 0 end, -extract(epoch from coalesce(b.created_at, now()))) then a.id else b.id end suggested_master_id
    from grouped g join base a on a.id = g.location_a_id join base b on b.id = g.location_b_id
    where g.duplicate_score >= 70
  ),
  upserted as (
    insert into public.location_duplicate_review(location_a_id, location_b_id, suggested_master_id, duplicate_score, match_reasons, updated_at)
    select location_a_id, location_b_id, suggested_master_id, duplicate_score, match_reasons, now() from enriched
    on conflict (location_a_id, location_b_id) do update
      set suggested_master_id = excluded.suggested_master_id,
          duplicate_score = greatest(public.location_duplicate_review.duplicate_score, excluded.duplicate_score),
          match_reasons = (select array_agg(distinct r) from unnest(public.location_duplicate_review.match_reasons || excluded.match_reasons) r),
          updated_at = now()
      where public.location_duplicate_review.status = 'pending'
        and public.location_duplicate_review.duplicate_score <= excluded.duplicate_score
    returning 1
  )
  select count(*) into v_changed from upserted;

  select count(*) into v_pending from public.location_duplicate_review where status = 'pending';
  return jsonb_build_object('scanned', v_limit, 'inserted_or_updated', v_changed, 'pending_total', v_pending, 'limit_used', v_limit);
end; $$;


ALTER FUNCTION "public"."oh_find_live_location_duplicates"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_find_live_location_duplicates_fast"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 500));
  v_changed integer := 0;
  v_pending integer := 0;
begin
  with candidates as (
    select least(a.id, b.id) as location_a_id,
           greatest(a.id, b.id) as location_b_id,
           case
             when public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)) = public.oh_normalize_text(coalesce(b.name,b.restaurant_name,b.activity_name)) then 100::numeric
             when similarity(public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)), public.oh_normalize_text(coalesce(b.name,b.restaurant_name,b.activity_name))) >= 0.60 then 98::numeric
             when similarity(public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)), public.oh_normalize_text(coalesce(b.name,b.restaurant_name,b.activity_name))) >= 0.30 then 85::numeric
             else 60::numeric
           end as duplicate_score,
           case
             when public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)) = public.oh_normalize_text(coalesce(b.name,b.restaurant_name,b.activity_name))
               or similarity(public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)), public.oh_normalize_text(coalesce(b.name,b.restaurant_name,b.activity_name))) >= 0.60
             then array['same_google_place_id']::text[]
             else array['same_google_place_id','google_place_id_name_mismatch']::text[]
           end as match_reasons
    from public.locations a
    join public.locations b
      on a.id < b.id
     and nullif(a.google_place_id, '') is not null
     and a.google_place_id = b.google_place_id
    where coalesce(a.duplicate_status, '') <> 'duplicate'
      and a.duplicate_of is null
      and coalesce(b.duplicate_status, '') <> 'duplicate'
      and b.duplicate_of is null
      and coalesce(a.is_hidden, false) = false
      and coalesce(b.is_hidden, false) = false

    union all

    select least(a.id, b.id), greatest(a.id, b.id), 100::numeric,
           array['same_location_key_live']::text[]
    from public.locations a
    join public.locations b
      on a.id < b.id
     and public.oh_location_key(coalesce(a.name,a.restaurant_name,a.activity_name), a.address, a.city, a.state) is not null
     and public.oh_location_key(coalesce(a.name,a.restaurant_name,a.activity_name), a.address, a.city, a.state)
         = public.oh_location_key(coalesce(b.name,b.restaurant_name,b.activity_name), b.address, b.city, b.state)
    where coalesce(a.duplicate_status, '') <> 'duplicate'
      and a.duplicate_of is null
      and coalesce(b.duplicate_status, '') <> 'duplicate'
      and b.duplicate_of is null
      and coalesce(a.is_hidden, false) = false
      and coalesce(b.is_hidden, false) = false
      and not (
        nullif(a.google_place_id, '') is not null
        and nullif(b.google_place_id, '') is not null
        and a.google_place_id <> b.google_place_id
      )

    union all

    select least(a.id, b.id), greatest(a.id, b.id), 98::numeric,
           array['same_live_name_address']::text[]
    from public.locations a
    join public.locations b
      on a.id < b.id
     and nullif(public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)), '') is not null
     and public.oh_normalize_text(coalesce(a.name,a.restaurant_name,a.activity_name)) = public.oh_normalize_text(coalesce(b.name,b.restaurant_name,b.activity_name))
     and nullif(public.oh_normalize_text(a.address), '') is not null
     and public.oh_normalize_text(a.address) = public.oh_normalize_text(b.address)
     and coalesce(public.oh_normalize_text(a.city), '') = coalesce(public.oh_normalize_text(b.city), '')
     and coalesce(upper(a.state), '') = coalesce(upper(b.state), '')
    where coalesce(a.duplicate_status, '') <> 'duplicate'
      and a.duplicate_of is null
      and coalesce(b.duplicate_status, '') <> 'duplicate'
      and b.duplicate_of is null
      and coalesce(a.is_hidden, false) = false
      and coalesce(b.is_hidden, false) = false
      and not (
        nullif(a.google_place_id, '') is not null
        and nullif(b.google_place_id, '') is not null
        and a.google_place_id <> b.google_place_id
      )
  ), grouped as (
    select location_a_id,
           location_b_id,
           max(duplicate_score) as duplicate_score,
           array_agg(distinct reason) as match_reasons
    from candidates c
    cross join lateral unnest(c.match_reasons) reason
    group by location_a_id, location_b_id
    order by max(duplicate_score) desc, location_a_id, location_b_id
    limit v_limit
  ), enriched as (
    select g.location_a_id,
           g.location_b_id,
           g.duplicate_score,
           g.match_reasons
             || case when coalesce(a.is_searchable, false) and coalesce(b.is_searchable, false)
                     then array['both_searchable']::text[] else '{}'::text[] end as match_reasons,
           case
             when (
               case when a.claimed_by is not null or coalesce(a.claim_status, '') in ('claimed','approved') then 1 else 0 end,
               case when coalesce(a.profile_managed_by, '') = 'owner' then 1 else 0 end,
               case when coalesce(a.publish_ready, false) then 1 else 0 end,
               case when nullif(a.public_location_url, '') is not null then 1 else 0 end,
               case when nullif(a.google_place_id, '') is not null then 1 else 0 end,
               case when coalesce(cardinality(a.images), 0) > 0 or nullif(coalesce(a.main_image, a.image_url), '') is not null then 1 else 0 end,
               coalesce(a.quality_score, 0),
               coalesce(a.review_count, 0),
               case when coalesce(a.is_searchable, false) then 1 else 0 end
             ) >= (
               case when b.claimed_by is not null or coalesce(b.claim_status, '') in ('claimed','approved') then 1 else 0 end,
               case when coalesce(b.profile_managed_by, '') = 'owner' then 1 else 0 end,
               case when coalesce(b.publish_ready, false) then 1 else 0 end,
               case when nullif(b.public_location_url, '') is not null then 1 else 0 end,
               case when nullif(b.google_place_id, '') is not null then 1 else 0 end,
               case when coalesce(cardinality(b.images), 0) > 0 or nullif(coalesce(b.main_image, b.image_url), '') is not null then 1 else 0 end,
               coalesce(b.quality_score, 0),
               coalesce(b.review_count, 0),
               case when coalesce(b.is_searchable, false) then 1 else 0 end
             ) then a.id else b.id
           end as suggested_master_id
    from grouped g
    join public.locations a on a.id = g.location_a_id
    join public.locations b on b.id = g.location_b_id
  ), upserted as (
    insert into public.location_duplicate_review(
      location_a_id, location_b_id, suggested_master_id,
      duplicate_score, match_reasons, updated_at
    )
    select location_a_id, location_b_id, suggested_master_id,
           duplicate_score, match_reasons, now()
    from enriched
    on conflict (location_a_id, location_b_id) do update
      set suggested_master_id = excluded.suggested_master_id,
          duplicate_score = excluded.duplicate_score,
          match_reasons = excluded.match_reasons,
          updated_at = now()
      where public.location_duplicate_review.status = 'pending'
    returning 1
  )
  select count(*) into v_changed from upserted;

  update public.location_duplicate_review r
  set status = 'not_duplicate',
      decision_reason = 'auto_distinct_google_places_and_addresses',
      decided_at = now(),
      updated_at = now()
  from public.locations a, public.locations b
  where r.status = 'pending'
    and a.id = r.location_a_id
    and b.id = r.location_b_id
    and nullif(a.google_place_id, '') is not null
    and nullif(b.google_place_id, '') is not null
    and a.google_place_id <> b.google_place_id
    and public.oh_normalize_text(coalesce(a.address,'')) <> public.oh_normalize_text(coalesce(b.address,''))
    and public.oh_location_key(coalesce(a.name,a.restaurant_name,a.activity_name), a.address, a.city, a.state)
        is distinct from
        public.oh_location_key(coalesce(b.name,b.restaurant_name,b.activity_name), b.address, b.city, b.state);

  select count(*) into v_pending
  from public.location_duplicate_review
  where status = 'pending';

  return jsonb_build_object(
    'scan_mode', 'fast_indexed_live_identity_calibrated',
    'limit_used', v_limit,
    'inserted_or_updated', v_changed,
    'pending_total', v_pending
  );
end;
$$;


ALTER FUNCTION "public"."oh_find_live_location_duplicates_fast"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_find_staging_duplicates"("p_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare inserted_count integer; begin
  insert into public.location_duplicate_matches(staging_id, existing_location_id, duplicate_score, match_reasons)
  select s.id, l.id, greatest(case when s.location_key is not null and s.location_key = l.location_key then 100 else 0 end, case when s.normalized_phone is not null and l.normalized_phone is not null and s.normalized_phone = l.normalized_phone then 98 else 0 end, case when s.source = l.import_source and s.source_id = l.import_source_id then 100 else 0 end, case when s.source = 'google_places' and s.source_id = l.google_place_id then 100 else 0 end, (similarity(coalesce(s.normalized_name, ''), coalesce(l.normalized_name, '')) * 55 + similarity(coalesce(s.normalized_address, ''), coalesce(l.normalized_address, '')) * 45)),
  array_remove(array[case when s.location_key = l.location_key then 'same_location_key' end, case when s.normalized_phone is not null and l.normalized_phone is not null and s.normalized_phone = l.normalized_phone then 'same_phone' end, case when s.source = l.import_source and s.source_id = l.import_source_id then 'same_source_id' end, case when s.source = 'google_places' and s.source_id = l.google_place_id then 'same_google_place_id' end, case when similarity(coalesce(s.normalized_name, ''), coalesce(l.normalized_name, '')) >= 0.75 then 'similar_name' end, case when similarity(coalesce(s.normalized_address, ''), coalesce(l.normalized_address, '')) >= 0.75 then 'similar_address' end], null)
  from public.location_import_staging s join public.locations l on (s.location_key = l.location_key or (s.normalized_phone is not null and l.normalized_phone is not null and s.normalized_phone = l.normalized_phone) or (s.source = l.import_source and s.source_id = l.import_source_id) or (s.source = 'google_places' and s.source_id = l.google_place_id) or (similarity(coalesce(s.normalized_name, ''), coalesce(l.normalized_name, '')) >= 0.72 and similarity(coalesce(s.normalized_address, ''), coalesce(l.normalized_address, '')) >= 0.65))
  where p_batch_id is null or s.batch_id = p_batch_id on conflict (staging_id, existing_location_id) do update set duplicate_score = excluded.duplicate_score, match_reasons = excluded.match_reasons;
  get diagnostics inserted_count = row_count;
  update public.location_import_staging s set duplicate_status = case when d.duplicate_score >= 90 then 'duplicate' when d.duplicate_score >= 70 then 'possible_duplicate' else 'unique' end, duplicate_score = coalesce(d.duplicate_score, 0), matched_location_id = d.existing_location_id, import_status = case when d.duplicate_score >= 90 then 'duplicate' when s.quality_status = 'reject' then 'rejected' else s.import_status end, rejection_reason = case when d.duplicate_score >= 90 then 'duplicate_existing_location' when s.quality_status = 'reject' then 'low_quality' else s.rejection_reason end, updated_at = now() from (select distinct on (staging_id) staging_id, existing_location_id, duplicate_score from public.location_duplicate_matches order by staging_id, duplicate_score desc) d where s.id = d.staging_id and (p_batch_id is null or s.batch_id = p_batch_id);
  update public.location_import_staging s set duplicate_status = 'unique' where (p_batch_id is null or s.batch_id = p_batch_id) and duplicate_status = 'unchecked' and not exists (select 1 from public.location_duplicate_matches d where d.staging_id = s.id);
  update public.location_import_batches b set total_duplicates = x.duplicates, total_possible_duplicates = x.possible_duplicates, total_rejected = x.rejected, total_publish_ready = x.publish_ready from (select batch_id, count(*) filter (where duplicate_status = 'duplicate') as duplicates, count(*) filter (where duplicate_status = 'possible_duplicate') as possible_duplicates, count(*) filter (where import_status = 'rejected') as rejected, count(*) filter (where duplicate_status = 'unique' and quality_status = 'publish_ready' and import_status = 'staged') as publish_ready from public.location_import_staging where p_batch_id is null or batch_id = p_batch_id group by batch_id) x where b.id = x.batch_id;
  return inserted_count;
end; $$;


ALTER FUNCTION "public"."oh_find_staging_duplicates"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_ignore_live_location_duplicate"("p_location_a_id" "uuid", "p_location_b_id" "uuid", "p_status" "text" DEFAULT 'ignored'::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare a uuid := least(p_location_a_id,p_location_b_id); b uuid := greatest(p_location_a_id,p_location_b_id);
begin
  if p_status not in ('ignored','not_duplicate') then raise exception 'invalid duplicate review status'; end if;
  update public.location_duplicate_review set status=p_status, decision_reason=p_reason, decided_at=now(), updated_at=now() where location_a_id=a and location_b_id=b;
  return jsonb_build_object('success', true, 'location_a_id', a, 'location_b_id', b, 'status', p_status);
end; $$;


ALTER FUNCTION "public"."oh_ignore_live_location_duplicate"("p_location_a_id" "uuid", "p_location_b_id" "uuid", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_is_low_level_location"("p_location_type" "text", "p_text" "text", "p_rating" numeric, "p_review_count" integer, "p_has_photos" boolean, "p_photo_status" "text", "p_curation_tier" "text", "p_public_visibility_tier" "text", "p_source_text" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  t text := public.oh_safe_lower_text(p_text);
  lt text := public.oh_safe_lower_text(p_location_type);
  tier text := public.oh_safe_lower_text(p_curation_tier);
  vis text := public.oh_safe_lower_text(p_public_visibility_tier);
  photo text := public.oh_safe_lower_text(p_photo_status);
  source_text text := public.oh_safe_lower_text(p_source_text || ' ' || p_text);
begin
  if public.oh_is_qualified_wellness_activity(lt, t, p_rating, p_review_count, p_has_photos, photo, vis) then return false; end if;
  return public.oh_low_level_reason(lt, t, p_rating, p_review_count, p_has_photos, photo, tier, vis, source_text) is not null;
end;
$$;


