    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select public.oh_safe_lower_text(p_text) ~
    '(nyc|open data|opendata|dohmh|doh|inspection|restaurant inspection|nyc_open_data|nyc_restaurant|public data)';
$$;


ALTER FUNCTION "public"."oh_is_nyc_import_source"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_is_qualified_wellness_activity"("p_location_type" "text", "p_text" "text", "p_rating" numeric, "p_review_count" integer, "p_has_photos" boolean, "p_photo_status" "text", "p_public_visibility_tier" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select public.oh_is_wellness_activity(p_location_type, p_text)
    and p_has_photos is true
    and public.oh_safe_lower_text(p_photo_status) <> 'missing_photo'
    and coalesce(p_rating, 0) >= 4.0
    and coalesce(p_review_count, 0) >= 25
    and public.oh_safe_lower_text(p_public_visibility_tier) <> 'hidden';
$$;


ALTER FUNCTION "public"."oh_is_qualified_wellness_activity"("p_location_type" "text", "p_text" "text", "p_rating" numeric, "p_review_count" integer, "p_has_photos" boolean, "p_photo_status" "text", "p_public_visibility_tier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_is_valid_photo_text"("p_value" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select
    p_value is not null
    and length(trim(p_value)) >= 8
    and lower(trim(p_value)) not in (
      'null',
      'undefined',
      'none',
      'n/a',
      'na',
      'placeholder',
      'placeholder.jpg',
      '/placeholder.jpg',
      '#',
      '?'
    )
    and lower(trim(p_value)) not like '%placeholder%'
    and lower(trim(p_value)) not like '%missing%'
    and lower(trim(p_value)) not like '%no-image%'
    and lower(trim(p_value)) not like '%no_image%'
    and lower(trim(p_value)) not like '%default-image%'
    and lower(trim(p_value)) not like '%default_image%'
    and (
      lower(trim(p_value)) like 'http://%'
      or lower(trim(p_value)) like 'https://%'
      or left(trim(p_value), 1) = '/'
      or lower(trim(p_value)) like '%supabase%'
      or lower(trim(p_value)) like '%storage%'
      or lower(trim(p_value)) like '%googleusercontent%'
      or lower(trim(p_value)) like '%ggpht%'
      or lower(trim(p_value)) like '%googleapis%'
      or lower(trim(p_value)) like '%yelpcdn%'
      or lower(trim(p_value)) like '%cloudinary%'
    );
$$;


ALTER FUNCTION "public"."oh_is_valid_photo_text"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_is_wellness_activity"("p_location_type" "text", "p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select
    public.oh_safe_lower_text(coalesce(p_text,'')) ~ '(\mspa\M|massage|wellness|head spa|float spa|yoga spa|recovery spa)'
    and (
      public.oh_safe_lower_text(coalesce(p_location_type,'')) = 'activity'
      or public.oh_safe_lower_text(coalesce(p_text,'')) ~ '(activity|spa|massage|wellness|head spa|float spa|yoga spa|recovery spa)'
    );
$$;


ALTER FUNCTION "public"."oh_is_wellness_activity"("p_location_type" "text", "p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_jsonb_has_valid_photo"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when p_value is null then false

    when jsonb_typeof(p_value) = 'string'
      then public.oh_is_valid_photo_text(p_value #>> '{}')

    when jsonb_typeof(p_value) = 'array'
      then exists (
        select 1
        from jsonb_array_elements(p_value) item
        where
          (
            jsonb_typeof(item) = 'string'
            and public.oh_is_valid_photo_text(item #>> '{}')
          )
          or
          (
            jsonb_typeof(item) = 'object'
            and (
              public.oh_is_valid_photo_text(item->>'url')
              or public.oh_is_valid_photo_text(item->>'src')
              or public.oh_is_valid_photo_text(item->>'image_url')
              or public.oh_is_valid_photo_text(item->>'main_image')
            )
          )
      )

    when jsonb_typeof(p_value) = 'object'
      then (
        public.oh_is_valid_photo_text(p_value->>'url')
        or public.oh_is_valid_photo_text(p_value->>'src')
        or public.oh_is_valid_photo_text(p_value->>'image_url')
        or public.oh_is_valid_photo_text(p_value->>'main_image')
      )

    else false
  end;
$$;


ALTER FUNCTION "public"."oh_jsonb_has_valid_photo"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_location_duplicate_review_summary"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'pending', count(*) filter (where status = 'pending'),
    'highConfidencePending', count(*) filter (where status = 'pending' and duplicate_score >= 95),
    'bothSearchablePending', count(*) filter (where status = 'pending' and match_reasons @> array['both_searchable']::text[]),
    'merged', count(*) filter (where status = 'merged'),
    'ignored', count(*) filter (where status = 'ignored'),
    'notDuplicate', count(*) filter (where status = 'not_duplicate')
  )
  from public.location_duplicate_review;
$$;


