    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select md5(coalesce(public.oh_normalize_text(p_name), '') || '|' || coalesce(public.oh_normalize_text(p_address), '') || '|' || coalesce(public.oh_normalize_text(p_city), '') || '|' || coalesce(upper(trim(p_state)), ''));
$$;


ALTER FUNCTION "public"."oh_location_key"("p_name" "text", "p_address" "text", "p_city" "text", "p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_location_low_level_text"("p_name" "text", "p_restaurant_name" "text", "p_activity_name" "text", "p_location_type" "text", "p_primary_category" "text", "p_category" "text", "p_cuisine" "text", "p_cuisine_type" "text", "p_food_type" "text", "p_activity_type" "text", "p_description" "text", "p_search_document" "text", "p_tags" "text"[], "p_google_types" "text"[], "p_source_table" "text", "p_import_source" "text", "p_source" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select public.oh_safe_lower_text(
    concat_ws(
      ' ',
      p_name,
      p_restaurant_name,
      p_activity_name,
      p_location_type,
      p_primary_category,
      p_category,
      p_cuisine,
      p_cuisine_type,
      p_food_type,
      p_activity_type,
      p_description,
      p_search_document,
      array_to_string(coalesce(p_tags, array[]::text[]), ' '),
      array_to_string(coalesce(p_google_types, array[]::text[]), ' '),
      p_source_table,
      p_import_source,
      p_source
    )
  );
$$;


ALTER FUNCTION "public"."oh_location_low_level_text"("p_name" "text", "p_restaurant_name" "text", "p_activity_name" "text", "p_location_type" "text", "p_primary_category" "text", "p_category" "text", "p_cuisine" "text", "p_cuisine_type" "text", "p_food_type" "text", "p_activity_type" "text", "p_description" "text", "p_search_document" "text", "p_tags" "text"[], "p_google_types" "text"[], "p_source_table" "text", "p_import_source" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_low_level_reason"("p_location_type" "text", "p_text" "text", "p_rating" numeric, "p_review_count" integer, "p_has_photos" boolean, "p_photo_status" "text", "p_curation_tier" "text", "p_public_visibility_tier" "text", "p_source_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  t text := public.oh_safe_lower_text(p_text);
  lt text := public.oh_safe_lower_text(p_location_type);
  tier text := public.oh_safe_lower_text(p_curation_tier);
  vis text := public.oh_safe_lower_text(p_public_visibility_tier);
  photo text := public.oh_safe_lower_text(p_photo_status);
  source_text text := public.oh_safe_lower_text(p_source_text || ' ' || p_text);
  protected boolean := tier in ('premium','curated','date_worthy','featured','high_value') or vis in ('premium','curated');
  only_generic_restaurant boolean := lt = 'restaurant' and t ~ '(^|\s)restaurant(s)?(\s|$)' and t !~ '(cuisine|bar|grill|steak|seafood|sushi|ramen|thai|korean|japanese|italian|mexican|brunch|lounge|rooftop|date|curated|premium|featured|photo|reservation)';
begin
  if public.oh_is_qualified_wellness_activity(lt, t, p_rating, p_review_count, p_has_photos, photo, vis) then return null; end if;
  if t ~ '(smoke shop|liquor store|pharmacy|gas station|laundromat|check cashing)' then return 'smoke_liquor_pharmacy_gas'; end if;
  if t ~ '(grocery|convenience store|corner store|supermarket|mini market)' then return 'grocery_convenience'; end if;
  if t ~ '(deli|delicatessen|bodega|\mmarket\M)' then return 'deli_bodega_market'; end if;
  if t ~ '(food cart|food truck|halal cart)' then return 'food_cart_or_truck'; end if;
  if t ~ '(fast food|quick service|counter service|buffet|pizza by the slice)' then return 'fast_food'; end if;
  if t ~ '(takeout|take out|take-away|takeaway|carryout|delivery only|chinese takeout|\mexpress\M)' then return 'takeout_or_counter_service'; end if;
  if public.oh_is_nyc_import_source(source_text) and lt = 'restaurant' and (p_has_photos is not true or p_rating is null or p_review_count is null or p_review_count < 25) then return 'nyc_import_unverified'; end if;
  if only_generic_restaurant and (p_has_photos is not true or p_rating is null or p_review_count is null or p_review_count < 25) then return 'generic_restaurant_unverified'; end if;
  if protected then return null; end if;
  if p_has_photos is not true or photo = 'missing_photo' then return 'missing_photo'; end if;
  if lt = 'restaurant' and (p_rating is null or p_rating < 4.0 or p_review_count is null or p_review_count < 25) then return 'weak_quality'; end if;
  if t ~ '(parking|atm|bank|storage|warehouse|repair|auto shop)' then return 'low_experience_category'; end if;
  return null;
end;
$_$;


ALTER FUNCTION "public"."oh_low_level_reason"("p_location_type" "text", "p_text" "text", "p_rating" numeric, "p_review_count" integer, "p_has_photos" boolean, "p_photo_status" "text", "p_curation_tier" "text", "p_public_visibility_tier" "text", "p_source_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_merge_live_location_duplicate"("p_master_id" "uuid", "p_duplicate_id" "uuid", "p_reason" "text" DEFAULT 'admin_merge'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  merged text[] := '{}';
  a uuid;
  b uuid;

  v_master_id uuid := p_master_id;
  v_duplicate_id uuid := p_duplicate_id;

  v_master_type text;
  v_duplicate_type text;

  v_swapped_for_domain_safety boolean := false;
begin
  if p_master_id = p_duplicate_id then
    raise exception 'master and duplicate must differ';
  end if;

  if not exists (
    select 1
    from public.locations
    where id = p_master_id
  )
  or not exists (
    select 1
    from public.locations
    where id = p_duplicate_id
  ) then
    raise exception 'location not found';
  end if;

  select location_type
  into v_master_type
  from public.locations
  where id = v_master_id;

  select location_type
  into v_duplicate_type
  from public.locations
  where id = v_duplicate_id;

  -- Preserve restaurant-domain safety only when the two rows do not already share the same verified Google identity.
  -- If both rows share one non-empty Google Place ID, honor the explicit master chosen by the caller so current rebrands
  -- and correctly typed activity/nightlife records are not replaced by stale restaurant imports.
  if coalesce(v_master_type, '') in ('activity', 'nightlife')
    and coalesce(v_duplicate_type, '') = 'restaurant'
    and not exists (
      select 1
      from public.locations m
      join public.locations d on d.id = v_duplicate_id
      where m.id = v_master_id
        and nullif(m.google_place_id, '') is not null
        and nullif(d.google_place_id, '') is not null
        and m.google_place_id = d.google_place_id
    ) then

    v_master_id := p_duplicate_id;
    v_duplicate_id := p_master_id;
    v_swapped_for_domain_safety := true;
  end if;

  update public.locations m
  set
    tags = (
      select array(
        select distinct x
        from unnest(
          coalesce(m.tags, '{}')
          || coalesce(d.tags, '{}')
          || array_remove(
            array[
              d.primary_category,
              d.cuisine,
              d.cuisine_type,
              d.activity_type,
              d.primary_tag,
              d.location_type
            ],
            null
          )
        ) x
        where nullif(trim(x), '') is not null
      )
    ),

    vibe_tags = (
      select array(
        select distinct x
        from unnest(
          coalesce(m.vibe_tags, '{}')
          || coalesce(d.vibe_tags, '{}')
        ) x
        where nullif(trim(x), '') is not null
      )
    ),

    best_for_tags = (
      select array(
        select distinct x
        from unnest(
          coalesce(m.best_for_tags, '{}')
          || coalesce(d.best_for_tags, '{}')
        ) x
        where nullif(trim(x), '') is not null
      )
    ),

    search_keywords = (
      select array(
        select distinct x
        from unnest(
          coalesce(m.search_keywords, '{}')
          || coalesce(d.search_keywords, '{}')
          || array_remove(
            array[
              d.primary_category,
              d.cuisine,
              d.cuisine_type,
              d.activity_type,
              d.primary_tag,
              d.location_type
            ],
            null
          )
        ) x
        where nullif(trim(x), '') is not null
      )
    ),

    google_types = (
      select array(
        select distinct x
        from unnest(
          coalesce(m.google_types, '{}')
          || coalesce(d.google_types, '{}')
        ) x
        where nullif(trim(x), '') is not null
      )
    ),

    images = (
      select array(
        select distinct x
        from unnest(
          coalesce(m.images, '{}')
          || coalesce(d.images, '{}')
        ) x
        where nullif(trim(x), '') is not null
      )
    ),

    primary_category = coalesce(
      nullif(m.primary_category, ''),
      nullif(d.primary_category, '')
    ),

    cuisine = coalesce(
      nullif(m.cuisine, ''),
      nullif(d.cuisine, '')
    ),

    cuisine_type = coalesce(
      nullif(m.cuisine_type, ''),
      nullif(d.cuisine_type, '')
    ),

    activity_type = coalesce(
      nullif(m.activity_type, ''),
      nullif(d.activity_type, '')
    ),

    primary_tag = coalesce(
      nullif(m.primary_tag, ''),
      nullif(d.primary_tag, '')
    ),

    main_image = coalesce(
      nullif(m.main_image, ''),
      nullif(d.main_image, '')
    ),

    image_url = coalesce(
      nullif(m.image_url, ''),
      nullif(d.image_url, '')
    ),

    phone = coalesce(
      nullif(m.phone, ''),
      nullif(d.phone, '')
    ),

    website = coalesce(
      nullif(m.website, ''),
      nullif(d.website, '')
    ),

    instagram_url = coalesce(
      nullif(m.instagram_url, ''),
      nullif(d.instagram_url, '')
    ),

    reservation_url = coalesce(
      nullif(m.reservation_url, ''),
      nullif(d.reservation_url, '')
    ),

    reservation_link = coalesce(
      nullif(m.reservation_link, ''),
      nullif(d.reservation_link, '')
    ),

    external_reservation_url = coalesce(
      nullif(m.external_reservation_url, ''),
      nullif(d.external_reservation_url, '')
    ),

    quality_score = greatest(
      coalesce(m.quality_score, 0),
      coalesce(d.quality_score, 0)
    ),

    review_count = greatest(
      coalesce(m.review_count, 0),
      coalesce(d.review_count, 0)
    ),

    rating = greatest(
      coalesce(m.rating, 0),
      coalesce(d.rating, 0)
    ),

    updated_at = now()

  from public.locations d
  where m.id = v_master_id
    and d.id = v_duplicate_id;

  merged := array[
    'tags',
    'vibe_tags',
    'best_for_tags',
    'search_keywords',
    'google_types',
    'images',
    'category_fields',
    'photo_fields',
    'business_metadata',
    'scores'
  ];

  update public.locations
  set
    duplicate_status = 'duplicate',
    duplicate_of = v_master_id,
    is_searchable = false,
    is_hidden = true,
    last_deduped_at = now(),
    updated_at = now()
  where id = v_duplicate_id;

  a := least(v_master_id, v_duplicate_id);
  b := greatest(v_master_id, v_duplicate_id);

  update public.location_duplicate_review
  set
    status = 'merged',
    suggested_master_id = v_master_id,
    decision_reason = p_reason,
    decided_at = now(),
    updated_at = now()
  where location_a_id = a
    and location_b_id = b;

  return jsonb_build_object(
    'success', true,
    'master_id', v_master_id,
    'duplicate_id', v_duplicate_id,
    'merged_fields', merged,
    'hidden_duplicate', true,
    'preserved_location_type', (
      select location_type
      from public.locations
      where id = v_master_id
    ),
    'swapped_for_domain_safety', v_swapped_for_domain_safety
  );
end;
$$;


ALTER FUNCTION "public"."oh_merge_live_location_duplicate"("p_master_id" "uuid", "p_duplicate_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_normalize_phone"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select nullif(regexp_replace(coalesce(value, ''), '\D', '', 'g'), '');
$$;


ALTER FUNCTION "public"."oh_normalize_phone"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_normalize_text"("value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select trim(lower(regexp_replace(regexp_replace(unaccent(coalesce(value, '')), '[^a-zA-Z0-9\s]', ' ', 'g'), '\s+', ' ', 'g')));
$$;


ALTER FUNCTION "public"."oh_normalize_text"("value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_preserve_restaurant_duplicate_master"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_a_type text;
  v_b_type text;
begin
  select location_type
  into v_a_type
  from public.locations
  where id = new.location_a_id;

  select location_type
  into v_b_type
  from public.locations
  where id = new.location_b_id;

  if coalesce(v_a_type, '') = 'restaurant'
    and coalesce(v_b_type, '') in ('activity', 'nightlife') then
    new.suggested_master_id := new.location_a_id;

  elsif coalesce(v_b_type, '') = 'restaurant'
    and coalesce(v_a_type, '') in ('activity', 'nightlife') then
    new.suggested_master_id := new.location_b_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."oh_preserve_restaurant_duplicate_master"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_prevent_searchable_exact_duplicate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare existing_id uuid;
begin
  new.normalized_name := public.oh_normalize_text(coalesce(new.name, new.restaurant_name, new.activity_name));
  new.normalized_address := public.oh_normalize_text(new.address);
  new.normalized_phone := public.oh_normalize_phone(new.phone);
  new.location_key := public.oh_location_key(coalesce(new.name, new.restaurant_name, new.activity_name), new.address, new.city, new.state);

  if coalesce(new.is_searchable,false)
     and coalesce(new.duplicate_status,'') <> 'duplicate'
     and new.duplicate_of is null then
    select l.id into existing_id
    from public.locations l
    where l.id <> coalesce(new.id, gen_random_uuid())
      and coalesce(l.duplicate_status,'') <> 'duplicate'
      and l.duplicate_of is null
      and coalesce(l.is_searchable,false)
      and l.deleted_at is null
      and (
        (new.location_key is not null and l.location_key = new.location_key)
        or (
          new.normalized_name = l.normalized_name
          and new.normalized_address = l.normalized_address
          and coalesce(public.oh_normalize_text(new.city),'') = coalesce(public.oh_normalize_text(l.city),'')
          and coalesce(upper(new.state),'') = coalesce(upper(l.state),'')
        )
      )
    limit 1;

    if existing_id is not null then
      new.is_searchable := false;
      if coalesce(new.duplicate_status,'unknown') in ('unknown','unique','') then
        new.duplicate_status := 'possible_duplicate';
      end if;
      new.duplicate_of := null;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."oh_prevent_searchable_exact_duplicate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_publish_import_batch"("p_batch_id" "uuid", "p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare inserted_count integer := 0; skipped_count integer := 0; begin
  insert into public.locations(location_type,name,restaurant_name,activity_name,address,city,state,zip_code,phone,website,latitude,longitude,primary_category,cuisine,cuisine_type,activity_type,primary_tag,tags,vibe_tags,best_for_tags,search_keywords,google_types,rating,review_count,main_image,images,description,import_source,import_source_id,normalized_name,normalized_address,normalized_phone,location_key,quality_score,quality_status,duplicate_status,data_status,is_searchable,enrichment_status,enrichment_priority,last_cleaned_at,last_deduped_at)
  select s.location_type, coalesce(s.name, s.restaurant_name, s.activity_name), s.restaurant_name, s.activity_name, s.address, s.city, s.state, s.zip_code, s.phone, s.website, s.latitude, s.longitude, s.primary_category, s.cuisine, s.cuisine_type, s.activity_type, s.primary_tag, s.tags, s.vibe_tags, s.best_for_tags, s.search_keywords, s.google_types, s.rating, s.review_count, s.main_image, s.images, s.description, s.source, s.source_id, s.normalized_name, s.normalized_address, s.normalized_phone, s.location_key, s.quality_score, s.quality_status, 'unique', 'clean', true, case when s.quality_score >= 85 then 'queued' else 'not_started' end, case when coalesce(s.review_count, 0) >= 100 then 100 when coalesce(s.rating, 0) >= 4.5 then 90 when s.quality_score >= 85 then 80 else 50 end, now(), now()
  from public.location_import_staging s where s.batch_id = p_batch_id and s.import_status = 'staged' and s.quality_status = 'publish_ready' and s.duplicate_status = 'unique' and coalesce(trim(s.address), '') <> '' and s.latitude is not null and s.longitude is not null and coalesce(trim(s.primary_category), '') <> '' and not exists (select 1 from public.locations l where l.import_source = s.source and l.import_source_id = s.source_id)
  order by s.quality_score desc, s.review_count desc nulls last limit p_limit;
  get diagnostics inserted_count = row_count;
  update public.location_import_staging s set import_status = 'published', updated_at = now() where s.batch_id = p_batch_id and s.import_status = 'staged' and s.quality_status = 'publish_ready' and s.duplicate_status = 'unique' and exists (select 1 from public.locations l where l.import_source = s.source and l.import_source_id = s.source_id);
  update public.location_import_batches b set total_published = coalesce(total_published, 0) + inserted_count, status = 'published', completed_at = now() where b.id = p_batch_id;
  select count(*) into skipped_count from public.location_import_staging where batch_id = p_batch_id and import_status in ('duplicate', 'rejected');
  return jsonb_build_object('success', true, 'batch_id', p_batch_id, 'inserted', inserted_count, 'skipped', skipped_count);
end; $$;


ALTER FUNCTION "public"."oh_publish_import_batch"("p_batch_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_publish_ready_staged_locations"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_count integer := 0;
  marked_count integer := 0;
begin
  with ready as (
    select s.*
    from public.location_import_staging s
    where s.import_status = 'staged'
      and s.quality_status = 'publish_ready'
      and s.duplicate_status = 'unique'
      and coalesce(trim(s.address), '') <> ''
      and s.latitude is not null
      and s.longitude is not null
      and coalesce(trim(s.primary_category), '') <> ''
      and not exists (
        select 1
        from public.locations l
        where l.import_source = s.source
          and l.import_source_id = s.source_id
      )
    order by s.quality_score desc, s.created_at asc
    limit least(greatest(coalesce(p_limit, 500), 1), 1000)
  ),
  inserted as (
    insert into public.locations (
      location_type,
      name,
      restaurant_name,
      activity_name,
      address,
      city,
      state,
      zip_code,
      phone,
      website,
      latitude,
      longitude,
      primary_category,
      cuisine,
      cuisine_type,
      activity_type,
      primary_tag,
      tags,
      vibe_tags,
      best_for_tags,
      search_keywords,
      google_types,
      rating,
      review_count,
      main_image,
      images,
      description,
      import_source,
      import_source_id,
      normalized_name,
      normalized_address,
      normalized_phone,
      location_key,
      quality_score,
      quality_status,
      duplicate_status,
      data_status,
      is_searchable,
      enrichment_status,
      enrichment_priority,
      last_cleaned_at,
      last_deduped_at
    )
    select
      r.location_type,
      coalesce(r.name, r.restaurant_name, r.activity_name),
      r.restaurant_name,
      r.activity_name,
      r.address,
      r.city,
      r.state,
      r.zip_code,
      r.phone,
      r.website,
      r.latitude,
      r.longitude,
      r.primary_category,
      r.cuisine,
      r.cuisine_type,
      r.activity_type,
      r.primary_tag,
      r.tags,
      r.vibe_tags,
      r.best_for_tags,
      r.search_keywords,
      r.google_types,
      r.rating,
      r.review_count,
      r.main_image,
      r.images,
      r.description,
      r.source,
      r.source_id,
      r.normalized_name,
      r.normalized_address,
      r.normalized_phone,
      r.location_key,
      r.quality_score,
      r.quality_status,
      'unique',
      'clean',
      true,
      case
        when r.quality_score >= 85 then 'queued'
        else 'not_started'
      end,
      case
        when coalesce(r.review_count, 0) >= 100 then 100
        when coalesce(r.rating, 0) >= 4.5 then 90
        when r.quality_score >= 85 then 80
        else 50
      end,
      now(),
      now()
    from ready r
    on conflict do nothing
    returning import_source, import_source_id
  ),
  marked as (
    update public.location_import_staging s
    set import_status = 'published',
        updated_at = now()
    where exists (
      select 1
      from inserted i
      where i.import_source = s.source
        and i.import_source_id = s.source_id
    )
    returning s.id
  )
  select
    (select count(*) from inserted),
    (select count(*) from marked)
  into inserted_count, marked_count;

  return jsonb_build_object(
    'success', true,
    'inserted', inserted_count,
    'markedPublished', marked_count
  );
end;
$$;


ALTER FUNCTION "public"."oh_publish_ready_staged_locations"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."oh_refresh_location_identity"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare updated_count integer;
begin
  update public.locations l
  set normalized_name = public.oh_normalize_text(coalesce(l.name, l.restaurant_name, l.activity_name)),
      normalized_address = public.oh_normalize_text(l.address),
      normalized_phone = public.oh_normalize_phone(l.phone),
      location_key = public.oh_location_key(coalesce(l.name, l.restaurant_name, l.activity_name), l.address, l.city, l.state)
  where l.normalized_name is distinct from public.oh_normalize_text(coalesce(l.name, l.restaurant_name, l.activity_name))
     or l.normalized_address is distinct from public.oh_normalize_text(l.address)
     or l.normalized_phone is distinct from public.oh_normalize_phone(l.phone)
     or l.location_key is distinct from public.oh_location_key(coalesce(l.name, l.restaurant_name, l.activity_name), l.address, l.city, l.state);
  get diagnostics updated_count = row_count;
  return updated_count;
end; $$;


