CREATE TABLE IF NOT EXISTS "public"."location_enrichment_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "mode" "text" DEFAULT 'repair'::"text" NOT NULL,
    "source_table" "text" DEFAULT 'locations'::"text" NOT NULL,
    "stale_days" integer DEFAULT 90 NOT NULL,
    "batch_size" integer DEFAULT 5 NOT NULL,
    "enable_food_probe" boolean DEFAULT false NOT NULL,
    "max_food_probes_per_row" integer DEFAULT 0 NOT NULL,
    "max_api_calls" integer,
    "estimated_records" integer DEFAULT 0 NOT NULL,
    "estimated_api_calls" integer DEFAULT 0 NOT NULL,
    "processed_records" integer DEFAULT 0 NOT NULL,
    "matched_records" integer DEFAULT 0 NOT NULL,
    "review_records" integer DEFAULT 0 NOT NULL,
    "no_match_records" integer DEFAULT 0 NOT NULL,
    "failed_records" integer DEFAULT 0 NOT NULL,
    "actual_api_calls" integer DEFAULT 0 NOT NULL,
    "batches_completed" integer DEFAULT 0 NOT NULL,
    "settings" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "before_quality" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "after_quality" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_batch" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "last_error" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "paused_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "enriched_records" integer DEFAULT 0 NOT NULL,
    "unchanged_records" integer DEFAULT 0 NOT NULL,
    "skipped_records" integer DEFAULT 0 NOT NULL,
    "profiles_queued_records" integer DEFAULT 0 NOT NULL,
    "photos_cached_records" integer DEFAULT 0 NOT NULL,
    "cursor_location_id" "uuid",
    CONSTRAINT "location_enrichment_runs_batch_size_check" CHECK ((("batch_size" >= 1) AND ("batch_size" <= 25))),
    CONSTRAINT "location_enrichment_runs_max_food_probes_per_row_check" CHECK ((("max_food_probes_per_row" >= 0) AND ("max_food_probes_per_row" <= 3))),
    CONSTRAINT "location_enrichment_runs_mode_check" CHECK (("mode" = ANY (ARRAY['repair'::"text", 'full_refresh'::"text"]))),
    CONSTRAINT "location_enrichment_runs_source_table_check" CHECK (("source_table" = 'locations'::"text")),
    CONSTRAINT "location_enrichment_runs_stale_days_check" CHECK ((("stale_days" >= 1) AND ("stale_days" <= 3650))),
    CONSTRAINT "location_enrichment_runs_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'queued'::"text", 'running'::"text", 'paused'::"text", 'completed'::"text", 'cancelled'::"text", 'failed'::"text", 'budget_stopped'::"text"])))
);


ALTER TABLE "public"."location_enrichment_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_location_enrichment_run"("p_run_id" "uuid") RETURNS "public"."location_enrichment_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run public.location_enrichment_runs;
  v_cutoff timestamptz;
  v_records integer;
  v_calls integer;
  v_market text;
  v_source_type text;
  v_target_limit integer;
  v_gaps text[];
  v_has_gap_filter boolean;
begin
  select * into v_run
  from public.location_enrichment_runs
  where id = p_run_id
  for update;

  if v_run.id is null then
    raise exception 'Enrichment run not found';
  end if;

  if v_run.status not in ('planned', 'paused') then
    raise exception 'Run cannot be prepared from status %', v_run.status;
  end if;

  v_cutoff := now() - make_interval(days => v_run.stale_days);
  v_market := nullif(
    upper(trim(coalesce(v_run.settings ->> 'market', ''))),
    'ALL'
  );
  v_source_type := lower(
    coalesce(
      nullif(trim(v_run.settings ->> 'sourceType'), ''),
      'both'
    )
  );
  v_target_limit := greatest(
    1,
    least(
      coalesce(
        nullif(v_run.settings ->> 'targetLimit', '')::integer,
        100
      ),
      250
    )
  );

  select coalesce(array_agg(value), array[]::text[])
    into v_gaps
  from jsonb_array_elements_text(
    coalesce(v_run.settings -> 'gaps', '[]'::jsonb)
  );

  v_has_gap_filter := coalesce(array_length(v_gaps, 1), 0) > 0;

  delete from public.location_enrichment_run_items
  where run_id = p_run_id
    and status = 'pending';

  with eligible as (
    select
      l.id,
      l.google_place_id,
      l.operating_hours,
      l.main_image,
      l.image_url,
      l.images,
      array_remove(
        array[
          case
            when l.google_place_id is null
            then 'missing_google_place_id'
          end,

          case
            when l.operating_hours is null
              or l.operating_hours in ('{}'::jsonb, '[]'::jsonb)
            then 'missing_hours'
          end,

          case
            when coalesce(
              nullif(trim(l.main_image), ''),
              nullif(trim(l.image_url), '')
            ) is null
            and coalesce(cardinality(l.images), 0) = 0
            then 'missing_photos'
          end,

          case
            when coalesce(
              nullif(trim(l.website), ''),
              nullif(trim(l.google_website_uri), '')
            ) is null
            then 'missing_website'
          end,

          case
            when nullif(trim(l.phone), '') is null
            then 'missing_phone'
          end,

          case
            when (
              (
                coalesce(lower(l.location_type), '') = 'restaurant'
                and coalesce(
                  nullif(trim(l.primary_category), ''),
                  nullif(trim(l.cuisine), ''),
                  nullif(trim(l.cuisine_type), '')
                ) is null
              )
              or
              (
                coalesce(lower(l.location_type), '') <> 'restaurant'
                and coalesce(
                  nullif(trim(l.primary_category), ''),
                  nullif(trim(l.activity_type), '')
                ) is null
              )
            )
            then 'missing_category'
          end,

          case
            when coalesce(
              nullif(trim(l.external_reservation_url), ''),
              nullif(trim(l.reservation_url), ''),
              nullif(trim(l.reservation_link), ''),
              nullif(trim(l.booking_url), '')
            ) is null
            then 'missing_reservation'
          end,

          case
            when l.latitude is null
              or l.longitude is null
            then 'missing_coordinates'
          end,

          case
            when l.search_keywords is null
              or cardinality(l.search_keywords) = 0
              or l.semantic_tags is null
              or cardinality(l.semantic_tags) = 0
              or l.intent_tags is null
              or cardinality(l.intent_tags) = 0
            then 'weak_search_metadata'
          end,

          case
            when l.google_enriched_at is null
              then 'never_enriched'
            when l.google_enriched_at < v_cutoff
              then 'stale_google_enrichment'
          end
        ],
        null
      ) as reasons
    from public.locations l
    where
      (
        v_market is null
        or upper(coalesce(l.market, '')) = v_market
      )
      and (
        v_source_type = 'both'
        or (
          v_source_type = 'restaurants'
          and coalesce(lower(l.location_type), '') = 'restaurant'
        )
        or (
          v_source_type = 'activities'
          and coalesce(lower(l.location_type), '') <> 'restaurant'
        )
      )
  ),
  targeted as (
    select
      e.*,
      case
        when 'missing_google_place_id' = any(e.reasons)
          then 10
        when 'missing_coordinates' = any(e.reasons)
          then 20
        when 'missing_category' = any(e.reasons)
          then 30
        when 'missing_hours' = any(e.reasons)
          or 'missing_photos' = any(e.reasons)
          then 40
        when 'missing_website' = any(e.reasons)
          or 'missing_phone' = any(e.reasons)
          or 'missing_reservation' = any(e.reasons)
          then 50
        when 'weak_search_metadata' = any(e.reasons)
          then 60
        else 70
      end as priority
    from eligible e
    where
      v_run.mode = 'full_refresh'
      or (
        not v_has_gap_filter
        and coalesce(array_length(e.reasons, 1), 0) > 0
      )
      or (
        v_has_gap_filter
        and exists (
          select 1
          from unnest(v_gaps) selected_gap
          where selected_gap = any(e.reasons)
        )
      )
    order by priority asc, e.id asc
    limit v_target_limit
  )
  insert into public.location_enrichment_run_items(
    run_id,
    location_id,
    priority,
    reasons
  )
  select
    p_run_id,
    t.id,
    t.priority,
    t.reasons
  from targeted t
  on conflict (run_id, location_id) do nothing;

  select
    count(*),
    coalesce(
      sum(
        case
          when l.google_place_id is null then 2
          else 1
        end
        +
        case
          when (
            (
              not v_has_gap_filter
              or 'missing_photos' = any(v_gaps)
            )
            and coalesce(
              nullif(trim(l.main_image), ''),
              nullif(trim(l.image_url), '')
            ) is null
            and coalesce(cardinality(l.images), 0) = 0
          )
          then 2
          else 0
        end
      ),
      0
    )
  into v_records, v_calls
  from public.location_enrichment_run_items i
  join public.locations l
    on l.id = i.location_id
  where i.run_id = p_run_id;

  update public.location_enrichment_runs
  set
    estimated_records = v_records,
    estimated_api_calls = v_calls,
    processed_records = 0,
    matched_records = 0,
    review_records = 0,
    no_match_records = 0,
    failed_records = 0,
    enriched_records = 0,
    unchanged_records = 0,
    skipped_records = 0,
    profiles_queued_records = 0,
    photos_cached_records = 0,
    actual_api_calls = 0,
    batches_completed = 0,
    cursor_location_id = null,
    last_batch = '{}'::jsonb,
    last_error = null,
    updated_at = now()
  where id = p_run_id
  returning * into v_run;

  insert into public.location_enrichment_run_events(
    run_id,
    event_type,
    message,
    metadata
  )
  values (
    p_run_id,
    'prepared',
    'Targeted location enrichment plan prepared',
    jsonb_build_object(
      'records', v_records,
      'estimated_api_calls', v_calls,
      'market', coalesce(v_market, 'ALL'),
      'sourceType', v_source_type,
      'targetLimit', v_target_limit,
      'gaps', to_jsonb(v_gaps)
    )
  );

  return v_run;
end
$$;


ALTER FUNCTION "public"."prepare_location_enrichment_run"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_photo_nudge_counter_regression"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.photo_nudge_count := greatest(coalesce(old.photo_nudge_count,0), coalesce(new.photo_nudge_count,0));
  if old.last_photo_nudge_at is not null and
     (new.last_photo_nudge_at is null or new.last_photo_nudge_at < old.last_photo_nudge_at) then
    new.last_photo_nudge_at := old.last_photo_nudge_at;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_photo_nudge_counter_regression"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_owner_photo_from_google_overwrite"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_google_attempt boolean;
  v_owner_hero text;
begin
  if coalesce(old.owner_photo_count,0) <= 0 then
    return new;
  end if;

  v_google_attempt :=
    lower(coalesce(new.photo_source,'')) like 'google%' or
    coalesce(new.main_image,'') like '%/api/public/google-place-photo%' or
    coalesce(new.image_url,'') like '%/api/public/google-place-photo%' or
    coalesce(new.main_image,'') like '%maps.googleapis.com/maps/api/place/photo%' or
    coalesce(new.image_url,'') like '%maps.googleapis.com/maps/api/place/photo%';

  if not v_google_attempt then
    return new;
  end if;

  v_owner_hero := coalesce(
    nullif(btrim(old.owner_primary_photo_url),''),
    nullif(btrim(old.main_image),''),
    nullif(btrim(old.image_url),'')
  );

  if v_owner_hero is not null then
    new.main_image := v_owner_hero;
    new.image_url := v_owner_hero;
  end if;
  new.photo_source := old.photo_source;
  new.photo_status := old.photo_status;
  return new;
end;
$$;


ALTER FUNCTION "public"."protect_owner_photo_from_google_overwrite"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prune_completed_search_anchor_reconciliation"("p_retention_days" integer DEFAULT 30, "p_limit" integer DEFAULT 1000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  deleted_count integer := 0;
begin
  with doomed as (
    select id
    from public.search_anchor_reconciliation_queue
    where status = 'completed'
      and updated_at < now() - make_interval(days => greatest(1, p_retention_days))
    order by updated_at asc
    limit least(greatest(1, p_limit), 5000)
  )
  delete from public.search_anchor_reconciliation_queue q
  using doomed
  where q.id = doomed.id;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION "public"."prune_completed_search_anchor_reconciliation"("p_retention_days" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_location_search_anchor_reconciliation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.enqueue_search_anchor_reconciliation(
      old.id,
      'delete',
      'location_deleted',
      100,
      old.updated_at,
      jsonb_build_object('market', old.market)
    );

    return old;
  end if;

  perform public.enqueue_search_anchor_reconciliation(
    new.id,
    case
      when tg_op = 'INSERT' then 'insert'
      else 'update'
    end,
    case
      when tg_op = 'INSERT' then 'location_created'
      else 'location_updated'
    end,
    case
      when tg_op = 'INSERT' then 70
      else 60
    end,
    new.updated_at,
    jsonb_build_object('market', new.market)
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."queue_location_search_anchor_reconciliation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_stale_search_anchor_locations"("p_limit" integer DEFAULT 1000) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  with candidates as (
    select l.id, l.updated_at, l.market
    from public.locations l
    left join public.search_anchors a
      on a.linked_location_id = l.id
    where
      a.id is null
      or a.source_updated_at is distinct from l.updated_at
      or a.sync_status is distinct from 'current'
    order by l.updated_at desc nulls last
    limit greatest(1, least(coalesce(p_limit, 1000), 10000))
  ),
  queued as (
    insert into public.search_anchor_reconciliation_queue (
      location_id,
      event_type,
      reason_code,
      status,
      priority,
      source_updated_at,
      payload
    )
    select
      c.id,
      'nightly_reconciliation',
      'anchor_missing_or_stale',
      'pending',
      40,
      c.updated_at,
      jsonb_build_object(
        'market', c.market,
        'source', 'nightly_reconciliation'
      )
    from candidates c
    on conflict (location_id)
    where status in ('pending', 'processing')
    do update set
      event_type = excluded.event_type,
      reason_code = excluded.reason_code,
      status = 'pending',
      available_at = now(),
      source_updated_at = excluded.source_updated_at,
      payload =
        public.search_anchor_reconciliation_queue.payload
        || excluded.payload,
      updated_at = now()
    returning 1
  )
  select count(*) into v_count
  from queued;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."queue_stale_search_anchor_locations"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_behavioral_search_features"("p_window" interval DEFAULT '30 days'::interval) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  updated_count integer := 0;
begin
  with impression_totals as (
    select
      i.location_id,
      count(*)::int as impression_count
    from public.search_result_impressions i
    where i.location_id is not null
      and i.created_at >= now() - p_window
    group by i.location_id
  ),
  normalized_events as (
    select
      e.id,
      e.location_id,
      coalesce(
        e.user_id::text,
        e.session_id,
        'anonymous'
      ) as actor_key,
      case
        when e.event_name in ('location_clicked', 'result_clicked')
          or e.event_type = 'search_click'
          or e.metadata->>'location_event_type' = 'click'
          then 'click'

        when e.event_name in ('location_saved', 'result_saved')
          or e.metadata->>'location_event_type' = 'save'
          then 'save'

        when e.event_name = 'reservation_completed'
          or e.event_type = 'reservation_completed'
          or e.metadata->>'location_event_type' = 'booking'
          then 'reservation_complete'

        when e.event_name in ('phone_clicked', 'call_clicked')
          or e.event_type = 'phone_click'
          then 'call'

        when e.event_name = 'website_clicked'
          or e.event_type = 'website_click'
          then 'website_click'

        when e.event_name = 'outing_completed'
          then 'outing_complete'

        when e.event_name = 'immediate_research'
          then 'immediate_research'

        else null
      end as action_type,
      e.created_at,
      date_trunc('minute', e.created_at) as action_minute
    from public.location_analytics_events e
    where e.location_id is not null
      and e.created_at >= now() - p_window
  ),
  deduped_events as (
    select distinct on (
      location_id,
      actor_key,
      action_type,
      action_minute
    )
      location_id,
      action_type,
      created_at
    from normalized_events
    where action_type is not null
    order by
      location_id,
      actor_key,
      action_type,
      action_minute,
      created_at
  ),
  event_totals as (
    select
      location_id,
      count(*) filter (
        where action_type = 'click'
      )::int as click_count,
      count(*) filter (
        where action_type = 'save'
      )::int as save_count,
      count(*) filter (
        where action_type = 'reservation_complete'
      )::int as reservation_complete_count,
      count(*) filter (
        where action_type = 'call'
      )::int as call_count,
      count(*) filter (
        where action_type = 'website_click'
      )::int as website_click_count,
      count(*) filter (
        where action_type = 'outing_complete'
      )::int as outing_complete_count,
      count(*) filter (
        where action_type = 'immediate_research'
      )::int as immediate_research_count
    from deduped_events
    group by location_id
  ),
  negative_totals as (
    select
      n.location_id,
      count(*)::int as negative_feedback_count
    from public.search_negative_feedback n
    where n.location_id is not null
      and n.created_at >= now() - p_window
    group by n.location_id
  ),
  features as (
    select
      i.location_id,
      i.impression_count,
      coalesce(e.click_count, 0) as click_count,
      coalesce(e.save_count, 0) as save_count,
      coalesce(
        e.reservation_complete_count,
        0
      ) as reservation_complete_count,
      coalesce(e.call_count, 0) as call_count,
      coalesce(
        e.website_click_count,
        0
      ) as website_click_count,
      coalesce(
        e.outing_complete_count,
        0
      ) as outing_complete_count,
      coalesce(
        e.immediate_research_count,
        0
      ) as immediate_research_count,
      coalesce(
        n.negative_feedback_count,
        0
      ) as negative_feedback_count
    from impression_totals i
    left join event_totals e
      on e.location_id = i.location_id
    left join negative_totals n
      on n.location_id = i.location_id
  )
  insert into public.search_result_ml_features (
    location_id,
    feature_window,
    impression_count,
    seen_impression_count,
    click_count,
    save_count,
    reservation_complete_count,
    call_count,
    website_click_count,
    outing_complete_count,
    negative_feedback_count,
    immediate_research_count,
    seen_ctr,
    save_rate,
    conversion_rate,
    completion_rate,
    negative_feedback_rate,
    sample_size,
    confidence_score,
    calculated_at,
    data_window_start,
    data_window_end,
    feature_version,
    status,
    result_quality_score
  )
  select
    f.location_id,
    '30d',
    f.impression_count,
    f.impression_count,
    f.click_count,
    f.save_count,
    f.reservation_complete_count,
    f.call_count,
    f.website_click_count,
    f.outing_complete_count,
    f.negative_feedback_count,
    f.immediate_research_count,
    coalesce(
      f.click_count::numeric /
        nullif(f.impression_count, 0),
      0
    ),
    coalesce(
      f.save_count::numeric /
        nullif(f.impression_count, 0),
      0
    ),
    coalesce(
      (
        f.reservation_complete_count
        + f.call_count
        + f.website_click_count
      )::numeric /
        nullif(f.impression_count, 0),
      0
    ),
    coalesce(
      f.outing_complete_count::numeric /
        nullif(f.impression_count, 0),
      0
    ),
    coalesce(
      f.negative_feedback_count::numeric /
        nullif(f.impression_count, 0),
      0
    ),
    f.impression_count,
    least(
      1,
      ln(1 + f.impression_count) / ln(101)
    ),
    now(),
    now() - p_window,
    now(),
    'behavioral_phase2_v1',
    case
      when f.impression_count < 25 then 'low_sample'
      else 'ready'
    end,
    greatest(
      0,
      least(
        100,
        50
        + coalesce(
            f.click_count::numeric /
              nullif(f.impression_count, 0),
            0
          ) * 20
        + coalesce(
            f.save_count::numeric /
              nullif(f.impression_count, 0),
            0
          ) * 25
        + coalesce(
            f.outing_complete_count::numeric /
              nullif(f.impression_count, 0),
            0
          ) * 35
        - coalesce(
            f.negative_feedback_count::numeric /
              nullif(f.impression_count, 0),
            0
          ) * 35
      )
    )
  from features f
  on conflict (location_id, feature_version) do update set
    feature_window = excluded.feature_window,
    impression_count = excluded.impression_count,
    seen_impression_count = excluded.seen_impression_count,
    click_count = excluded.click_count,
    save_count = excluded.save_count,
    reservation_complete_count =
      excluded.reservation_complete_count,
    call_count = excluded.call_count,
    website_click_count =
      excluded.website_click_count,
    outing_complete_count =
      excluded.outing_complete_count,
    negative_feedback_count =
      excluded.negative_feedback_count,
    immediate_research_count =
      excluded.immediate_research_count,
    seen_ctr = excluded.seen_ctr,
    save_rate = excluded.save_rate,
    conversion_rate = excluded.conversion_rate,
    completion_rate = excluded.completion_rate,
    negative_feedback_rate =
      excluded.negative_feedback_rate,
    sample_size = excluded.sample_size,
    confidence_score = excluded.confidence_score,
    calculated_at = excluded.calculated_at,
    data_window_start = excluded.data_window_start,
    data_window_end = excluded.data_window_end,
    feature_version = excluded.feature_version,
    status = excluded.status,
    result_quality_score =
      excluded.result_quality_score;

  get diagnostics updated_count = row_count;

  insert into public.behavioral_feature_runs (
    run_type,
    status,
    completed_at,
    records_updated,
    feature_version,
    source_window_start,
    source_window_end
  )
  values (
    'recalculate_search_result_features',
    'completed',
    now(),
    updated_count,
    'behavioral_phase2_v1',
    now() - p_window,
    now()
  );

  return jsonb_build_object(
    'ok', true,
    'records_updated', updated_count,
    'event_source', 'location_analytics_events',
    'dedupe_window', '1 minute'
  );
end;
$$;


ALTER FUNCTION "public"."recalculate_behavioral_search_features"("p_window" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_business_crm_scores"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  update public.locations l
  set
    traffic_score = least(100, coalesce(s.profile_views_30d, 0) / 10.0),
    engagement_score = least(100, (coalesce(s.search_appearances_30d, 0) / 8.0) + (coalesce(s.saves_30d, 0) * 2.5)),
    conversion_score = least(100, coalesce(s.conversion_rate_30d, 0) * 1000),
    retention_score = case when l.is_claimed then 65 else 40 end + least(35, coalesce(s.reservation_completions_30d, 0) / 4.0),
    opportunity_score = greatest(0, least(100,
      coalesce(s.profile_views_30d, 0) / 10.0 * 0.35 +
      ((coalesce(s.search_appearances_30d, 0) / 8.0) + (coalesce(s.saves_30d, 0) * 2.5)) * 0.2 +
      (coalesce(s.conversion_rate_30d, 0) * 1000) * 0.25 +
      ((case when l.is_claimed then 65 else 40 end + least(35, coalesce(s.reservation_completions_30d, 0) / 4.0))) * 0.2
    )),
    upgrade_probability = greatest(0, least(100, coalesce(l.opportunity_score, 0) * 0.85 + case when l.is_claimed then 10 else 0 end)),
    churn_risk_score = greatest(0, least(100, 100 - coalesce(l.retention_score, 0))),
    crm_status = case
      when l.is_claimed and coalesce(l.opportunity_score, 0) >= 75 then 'Upgrade Opportunity'
      when l.is_claimed then 'Active Free'
      when not l.is_claimed then 'Unclaimed'
      else coalesce(l.crm_status, 'Unclaimed')
    end,
    retention_recommendation = case
      when (100 - coalesce(l.retention_score, 0)) >= 65 then 'High churn risk: start retention outreach'
      when coalesce(l.opportunity_score, 0) >= 75 then 'Upsell candidate: prioritize pro outreach'
      else 'Monitor weekly'
    end
  from public.business_crm_snapshot s
  where s.id = l.id;
end;
$$;


ALTER FUNCTION "public"."recalculate_business_crm_scores"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalculate_business_crm_scores"() IS 'Run nightly (pg_cron) to refresh business CRM and upgrade scores.';



CREATE OR REPLACE FUNCTION "public"."reconcile_stale_location_enrichment_runs"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  update public.location_enrichment_run_items i
  set
    status = 'pending',
    last_error = coalesce(i.last_error, 'Recovered from interrupted enrichment batch; queued for retry.'),
    updated_at = now()
  where i.status = 'processing'
    and i.updated_at < now() - interval '10 minutes'
    and exists (
      select 1
      from public.location_enrichment_runs r
      where r.id = i.run_id
        and r.status = 'running'
    );

  with stats as (
    select
      i.run_id,
      count(*) filter (where i.status in ('completed','unchanged','skipped','failed','review','no_match'))::integer as processed,
      count(*) filter (where i.status = 'review')::integer as review,
      count(*) filter (where i.status = 'no_match')::integer as no_match,
      count(*) filter (where i.status = 'failed')::integer as failed,
      count(*) filter (
        where i.status in ('completed','review')
          and jsonb_typeof(i.match_diagnostics -> 'changedFields') = 'array'
          and jsonb_array_length(i.match_diagnostics -> 'changedFields') > 0
      )::integer as enriched,
      count(*) filter (where i.status = 'unchanged')::integer as unchanged,
      count(*) filter (where i.status in ('skipped','no_match'))::integer as skipped
    from public.location_enrichment_run_items i
    group by i.run_id
  )
  update public.location_enrichment_runs r
  set
    processed_records = stats.processed,
    review_records = stats.review,
    no_match_records = stats.no_match,
    failed_records = stats.failed,
    enriched_records = stats.enriched,
    unchanged_records = stats.unchanged,
    skipped_records = stats.skipped,
    updated_at = now()
  from stats
  where stats.run_id = r.id
    and r.status = 'running';

  update public.location_enrichment_runs r
  set
    status = 'completed',
    completed_at = coalesce(r.completed_at, now()),
    updated_at = now()
  where r.status = 'running'
    and not exists (
      select 1
      from public.location_enrichment_run_items i
      where i.run_id = r.id
        and i.status in ('pending','processing')
    );
end;
$$;


ALTER FUNCTION "public"."reconcile_stale_location_enrichment_runs"() OWNER TO "postgres";


