CREATE TABLE IF NOT EXISTS "public"."search_anchor_discoveries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "raw_query" "text" NOT NULL,
    "raw_anchor_text" "text" NOT NULL,
    "normalized_anchor_text" "text" NOT NULL,
    "area_hint" "text",
    "requested_domain" "text",
    "status" "text" DEFAULT 'unresolved'::"text" NOT NULL,
    "provider" "text",
    "provider_place_id" "text",
    "suggested_name" "text",
    "suggested_type" "text",
    "suggested_latitude" double precision,
    "suggested_longitude" double precision,
    "confidence" numeric(5,4),
    "occurrence_count" bigint DEFAULT 1 NOT NULL,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "approved_anchor_id" "uuid",
    "review_notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "search_anchor_discoveries_confidence_check" CHECK ((("confidence" IS NULL) OR (("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric)))),
    CONSTRAINT "search_anchor_discoveries_coordinates_check" CHECK (((("suggested_latitude" IS NULL) AND ("suggested_longitude" IS NULL)) OR ((("suggested_latitude" >= ('-90'::integer)::double precision) AND ("suggested_latitude" <= (90)::double precision)) AND (("suggested_longitude" >= ('-180'::integer)::double precision) AND ("suggested_longitude" <= (180)::double precision))))),
    CONSTRAINT "search_anchor_discoveries_domain_check" CHECK ((("requested_domain" IS NULL) OR ("requested_domain" = ANY (ARRAY['restaurant'::"text", 'activity'::"text"])))),
    CONSTRAINT "search_anchor_discoveries_normalized_anchor_not_blank" CHECK (("length"(TRIM(BOTH FROM "normalized_anchor_text")) > 0)),
    CONSTRAINT "search_anchor_discoveries_occurrence_count_check" CHECK (("occurrence_count" >= 1)),
    CONSTRAINT "search_anchor_discoveries_raw_anchor_not_blank" CHECK (("length"(TRIM(BOTH FROM "raw_anchor_text")) > 0)),
    CONSTRAINT "search_anchor_discoveries_raw_query_not_blank" CHECK (("length"(TRIM(BOTH FROM "raw_query")) > 0)),
    CONSTRAINT "search_anchor_discoveries_status_check" CHECK (("status" = ANY (ARRAY['unresolved'::"text", 'pending_review'::"text", 'resolved'::"text", 'approved'::"text", 'rejected'::"text", 'ignored'::"text"]))),
    CONSTRAINT "search_anchor_discoveries_type_check" CHECK ((("suggested_type" IS NULL) OR ("suggested_type" = ANY (ARRAY['restaurant'::"text", 'activity'::"text", 'landmark'::"text", 'stadium'::"text", 'arena'::"text", 'park'::"text", 'beach'::"text", 'mall'::"text", 'theater'::"text", 'museum'::"text", 'hotel'::"text", 'transit_hub'::"text", 'university'::"text", 'event_venue'::"text", 'neighborhood'::"text", 'airport'::"text", 'attraction'::"text"]))))
);


ALTER TABLE "public"."search_anchor_discoveries" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_search_anchor_discovery"("p_raw_query" "text", "p_raw_anchor_text" "text", "p_area_hint" "text" DEFAULT NULL::"text", "p_requested_domain" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."search_anchor_discoveries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_normalized text;
  v_row public.search_anchor_discoveries;
begin
  v_normalized :=
    public.normalize_search_anchor_name(p_raw_anchor_text);

  if length(v_normalized) = 0 then
    raise exception 'Anchor text cannot be blank';
  end if;

  if p_requested_domain is not null
     and p_requested_domain not in ('restaurant', 'activity')
  then
    raise exception 'Invalid requested domain: %', p_requested_domain;
  end if;

  insert into public.search_anchor_discoveries (
    raw_query,
    raw_anchor_text,
    normalized_anchor_text,
    area_hint,
    requested_domain,
    status,
    occurrence_count,
    first_seen_at,
    last_seen_at,
    metadata
  )
  values (
    trim(p_raw_query),
    trim(p_raw_anchor_text),
    v_normalized,
    nullif(trim(coalesce(p_area_hint, '')), ''),
    p_requested_domain,
    'unresolved',
    1,
    now(),
    now(),
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (
    normalized_anchor_text,
    coalesce(area_hint, ''),
    coalesce(requested_domain, '')
  )
  do update
  set
    raw_query = excluded.raw_query,
    raw_anchor_text = excluded.raw_anchor_text,
    occurrence_count =
      public.search_anchor_discoveries.occurrence_count + 1,
    last_seen_at = now(),
    metadata =
      public.search_anchor_discoveries.metadata
      || excluded.metadata,
    updated_at = now()
  returning *
  into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."record_search_anchor_discovery"("p_raw_query" "text", "p_raw_anchor_text" "text", "p_area_hint" "text", "p_requested_domain" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_search_ranking_rollout_approval"("rollout_run_id" "uuid", "target_stage_key" "text", "actor_user_id" "uuid", "decision" "text", "reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  approval_id uuid;
  snapshot jsonb;
begin
  if decision not in (
    'approved',
    'rejected',
    'revoked'
  ) then
    raise exception
      'Invalid approval decision';
  end if;

  select to_jsonb(r)
  into snapshot
  from
    public.search_ranking_rollout_completion_readiness_v1 r
  limit 1;

  insert into public.search_ranking_rollout_approvals (
    rollout_run_id,
    target_stage_key,
    decision,
    reason,
    approved_by,
    revoked_at,
    revoked_by,
    metrics_snapshot
  )
  values (
    rollout_run_id,
    target_stage_key,
    decision,
    reason,
    actor_user_id,
    case
      when decision = 'revoked'
        then now()
      else null
    end,
    case
      when decision = 'revoked'
        then actor_user_id
      else null
    end,
    coalesce(
      snapshot,
      '{}'::jsonb
    )
  )
  on conflict (
    rollout_run_id,
    target_stage_key
  )
  do update set
    decision = excluded.decision,
    reason = excluded.reason,
    approved_by = excluded.approved_by,
    approved_at = now(),
    revoked_at = excluded.revoked_at,
    revoked_by = excluded.revoked_by,
    metrics_snapshot = excluded.metrics_snapshot
  returning id into approval_id;

  insert into public.search_ranking_rollout_audit_log (
    rollout_run_id,
    actor_user_id,
    action,
    to_stage_key,
    reason,
    metadata
  )
  values (
    rollout_run_id,
    actor_user_id,
    'rollout_approval_' || decision,
    target_stage_key,
    reason,
    jsonb_build_object(
      'approval_id',
      approval_id
    )
  );

  return approval_id;
end;
$$;


ALTER FUNCTION "public"."record_search_ranking_rollout_approval"("rollout_run_id" "uuid", "target_stage_key" "text", "actor_user_id" "uuid", "decision" "text", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_stale_worker_jobs"("p_stale_seconds" integer DEFAULT 300) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_count integer; begin update public.worker_jobs set status='queued', run_after=now(), lease_owner=null, lease_expires_at=null, updated_at=now(), last_error=coalesce(last_error,'stale lease recovered') where status='running' and coalesce(lease_expires_at, heartbeat_at + make_interval(secs=>p_stale_seconds)) < now(); get diagnostics v_count = row_count; return v_count; end $$;


ALTER FUNCTION "public"."recover_stale_worker_jobs"("p_stale_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_location_customer_insights"("p_start_date" "date" DEFAULT (CURRENT_DATE - 30), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.location_customer_insights (
    location_id,
    insight_date,
    top_search_terms,
    top_referrers,
    top_device_types,
    top_cities,
    conversion_rate,
    save_rate,
    reservation_rate,
    call_rate,
    repeat_user_rate,
    updated_at
  )
  select
    l.id as location_id,
    current_date as insight_date,

    coalesce((
      select jsonb_agg(jsonb_build_object('term', search_query, 'count', search_count))
      from (
        select search_query, count(*) as search_count
        from public.location_analytics_events e
        where e.location_id = l.id
          and e.search_query is not null
          and trim(e.search_query) <> ''
          and e.created_at::date between p_start_date and p_end_date
        group by search_query
        order by search_count desc
        limit 10
      ) s
    ), '[]'::jsonb) as top_search_terms,

    coalesce((
      select jsonb_agg(jsonb_build_object('referrer', referrer, 'count', referrer_count))
      from (
        select referrer, count(*) as referrer_count
        from public.location_analytics_events e
        where e.location_id = l.id
          and e.referrer is not null
          and trim(e.referrer) <> ''
          and e.created_at::date between p_start_date and p_end_date
        group by referrer
        order by referrer_count desc
        limit 10
      ) r
    ), '[]'::jsonb) as top_referrers,

    coalesce((
      select jsonb_agg(jsonb_build_object('device_type', device_type, 'count', device_count))
      from (
        select device_type, count(*) as device_count
        from public.location_analytics_events e
        where e.location_id = l.id
          and e.device_type is not null
          and trim(e.device_type) <> ''
          and e.created_at::date between p_start_date and p_end_date
        group by device_type
        order by device_count desc
        limit 10
      ) d
    ), '[]'::jsonb) as top_device_types,

    coalesce((
      select jsonb_agg(jsonb_build_object('city', city, 'count', city_count))
      from (
        select city, count(*) as city_count
        from public.location_analytics_events e
        where e.location_id = l.id
          and e.city is not null
          and trim(e.city) <> ''
          and e.created_at::date between p_start_date and p_end_date
        group by city
        order by city_count desc
        limit 10
      ) c
    ), '[]'::jsonb) as top_cities,

    coalesce((
      select
        case
          when count(*) filter (where event_name in ('view', 'location_view', 'card_view')) = 0 then 0
          else
            count(*) filter (
              where event_name in (
                'reservation_click',
                'reserve',
                'reserve_external',
                'call_click',
                'call',
                'completed_outing',
                'outing_completed'
              )
            )::numeric
            /
            nullif(count(*) filter (where event_name in ('view', 'location_view', 'card_view')), 0)::numeric
        end
      from public.location_analytics_events e
      where e.location_id = l.id
        and e.created_at::date between p_start_date and p_end_date
    ), 0) as conversion_rate,

    coalesce((
      select
        case
          when count(*) filter (where event_name in ('view', 'location_view', 'card_view')) = 0 then 0
          else
            count(*) filter (where event_name in ('save', 'location_save'))::numeric
            /
            nullif(count(*) filter (where event_name in ('view', 'location_view', 'card_view')), 0)::numeric
        end
      from public.location_analytics_events e
      where e.location_id = l.id
        and e.created_at::date between p_start_date and p_end_date
    ), 0) as save_rate,

    coalesce((
      select
        case
          when count(*) filter (where event_name in ('view', 'location_view', 'card_view')) = 0 then 0
          else
            count(*) filter (where event_name in ('reservation_click', 'reserve', 'reserve_external'))::numeric
            /
            nullif(count(*) filter (where event_name in ('view', 'location_view', 'card_view')), 0)::numeric
        end
      from public.location_analytics_events e
      where e.location_id = l.id
        and e.created_at::date between p_start_date and p_end_date
    ), 0) as reservation_rate,

    coalesce((
      select
        case
          when count(*) filter (where event_name in ('view', 'location_view', 'card_view')) = 0 then 0
          else
            count(*) filter (where event_name in ('call_click', 'call'))::numeric
            /
            nullif(count(*) filter (where event_name in ('view', 'location_view', 'card_view')), 0)::numeric
        end
      from public.location_analytics_events e
      where e.location_id = l.id
        and e.created_at::date between p_start_date and p_end_date
    ), 0) as call_rate,

    coalesce((
      select
        case
          when count(*) = 0 then 0
          else
            count(*) filter (where user_event_count > 1)::numeric
            /
            nullif(count(*), 0)::numeric
        end
      from (
        select user_id, count(*) as user_event_count
        from public.location_analytics_events e
        where e.location_id = l.id
          and e.user_id is not null
          and e.created_at::date between p_start_date and p_end_date
        group by user_id
      ) repeat_users
    ), 0) as repeat_user_rate,

    now()
  from public.locations l
  on conflict (location_id, insight_date)
  do update set
    top_search_terms = excluded.top_search_terms,
    top_referrers = excluded.top_referrers,
    top_device_types = excluded.top_device_types,
    top_cities = excluded.top_cities,
    conversion_rate = excluded.conversion_rate,
    save_rate = excluded.save_rate,
    reservation_rate = excluded.reservation_rate,
    call_rate = excluded.call_rate,
    repeat_user_rate = excluded.repeat_user_rate,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."refresh_location_customer_insights"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_location_daily_analytics"("p_start_date" "date" DEFAULT (CURRENT_DATE - 30), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.location_daily_analytics (
    location_id,
    analytics_date,
    views,
    saves,
    shares,
    website_clicks,
    reservation_clicks,
    call_clicks,
    direction_clicks,
    plan_adds,
    completed_outings,
    searches,
    unique_users,
    updated_at
  )
  select
    e.location_id,
    e.created_at::date as analytics_date,
    count(*) filter (where e.event_name in ('view', 'location_view', 'card_view'))::integer as views,
    count(*) filter (where e.event_name in ('save', 'location_save'))::integer as saves,
    count(*) filter (where e.event_name in ('share', 'location_share'))::integer as shares,
    count(*) filter (where e.event_name in ('website_click', 'website'))::integer as website_clicks,
    count(*) filter (where e.event_name in ('reservation_click', 'reserve', 'reserve_external'))::integer as reservation_clicks,
    count(*) filter (where e.event_name in ('call_click', 'call'))::integer as call_clicks,
    count(*) filter (where e.event_name in ('direction_click', 'directions'))::integer as direction_clicks,
    count(*) filter (where e.event_name in ('plan_add', 'add_to_plan'))::integer as plan_adds,
    count(*) filter (where e.event_name in ('completed_outing', 'outing_completed'))::integer as completed_outings,
    count(*) filter (where e.event_name in ('search_result', 'search'))::integer as searches,
    count(distinct e.user_id)::integer as unique_users,
    now()
  from public.location_analytics_events e
  where e.created_at::date between p_start_date and p_end_date
  group by e.location_id, e.created_at::date
  on conflict (location_id, analytics_date)
  do update set
    views = excluded.views,
    saves = excluded.saves,
    shares = excluded.shares,
    website_clicks = excluded.website_clicks,
    reservation_clicks = excluded.reservation_clicks,
    call_clicks = excluded.call_clicks,
    direction_clicks = excluded.direction_clicks,
    plan_adds = excluded.plan_adds,
    completed_outings = excluded.completed_outings,
    searches = excluded.searches,
    unique_users = excluded.unique_users,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."refresh_location_daily_analytics"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_location_hourly_analytics"("p_start_date" "date" DEFAULT (CURRENT_DATE - 7), "p_end_date" "date" DEFAULT CURRENT_DATE) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.location_hourly_analytics (
    location_id,
    analytics_date,
    analytics_hour,
    day_of_week,
    hour_of_day,
    views,
    saves,
    shares,
    website_clicks,
    reservation_clicks,
    call_clicks,
    direction_clicks,
    plan_adds,
    completed_outings,
    searches,
    unique_users,
    updated_at
  )
  select
    e.location_id,
    e.created_at::date as analytics_date,
    extract(hour from e.created_at)::integer as analytics_hour,
    extract(dow from e.created_at)::integer as day_of_week,
    extract(hour from e.created_at)::integer as hour_of_day,
    count(*) filter (where e.event_name in ('view', 'location_view', 'card_view'))::integer as views,
    count(*) filter (where e.event_name in ('save', 'location_save'))::integer as saves,
    count(*) filter (where e.event_name in ('share', 'location_share'))::integer as shares,
    count(*) filter (where e.event_name in ('website_click', 'website'))::integer as website_clicks,
    count(*) filter (where e.event_name in ('reservation_click', 'reserve', 'reserve_external'))::integer as reservation_clicks,
    count(*) filter (where e.event_name in ('call_click', 'call'))::integer as call_clicks,
    count(*) filter (where e.event_name in ('direction_click', 'directions'))::integer as direction_clicks,
    count(*) filter (where e.event_name in ('plan_add', 'add_to_plan'))::integer as plan_adds,
    count(*) filter (where e.event_name in ('completed_outing', 'outing_completed'))::integer as completed_outings,
    count(*) filter (where e.event_name in ('search_result', 'search'))::integer as searches,
    count(distinct e.user_id)::integer as unique_users,
    now()
  from public.location_analytics_events e
  where e.created_at::date between p_start_date and p_end_date
  group by
    e.location_id,
    e.created_at::date,
    extract(hour from e.created_at),
    extract(dow from e.created_at)
  on conflict (location_id, analytics_date, analytics_hour)
  do update set
    day_of_week = excluded.day_of_week,
    hour_of_day = excluded.hour_of_day,
    views = excluded.views,
    saves = excluded.saves,
    shares = excluded.shares,
    website_clicks = excluded.website_clicks,
    reservation_clicks = excluded.reservation_clicks,
    call_clicks = excluded.call_clicks,
    direction_clicks = excluded.direction_clicks,
    plan_adds = excluded.plan_adds,
    completed_outings = excluded.completed_outings,
    searches = excluded.searches,
    unique_users = excluded.unique_users,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."refresh_location_hourly_analytics"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_expired_experience_table_holds"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  affected integer;
begin
  update public.experience_table_blocks
     set status='released', updated_at=now()
   where status='held'
     and hold_expires_at is not null
     and hold_expires_at <= now();
  get diagnostics affected = row_count;
  return affected;
end;
$$;


ALTER FUNCTION "public"."release_expired_experience_table_holds"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_stale_search_anchor_reconciliation_locks"("p_stale_minutes" integer DEFAULT 15) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  update public.search_anchor_reconciliation_queue
  set
    status =
      case
        when attempts >= max_attempts
          then 'dead_letter'
        else 'failed'
      end,
    available_at = now(),
    locked_at = null,
    locked_by = null,
    last_error = coalesce(
      last_error,
      'Processing lock expired before completion.'
    ),
    updated_at = now()
  where status = 'processing'
    and locked_at <
      now() - make_interval(
        mins => greatest(
          1,
          least(coalesce(p_stale_minutes, 15), 1440)
        )
      );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."release_stale_search_anchor_reconciliation_locks"("p_stale_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_bar_assignments_before_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  terminal boolean;
  normalized_type text;
  requested_label text;
  anchor_label text;
  target_seat public.reservation_seating_resources%rowtype;
  parent_id uuid;
  party integer;
  anchor_index integer;
  chosen uuid[];
  chosen_labels text[];
  candidate_start integer;
  max_start integer;
  overlap_count integer;
  v_duration_minutes integer;
  reservation_start integer;
begin
  terminal := lower(coalesce(new.status,'')) in ('completed','cancelled','declined','no_show');
  if terminal then
    delete from public.reservation_resource_assignments where reservation_id = new.id;
    return new;
  end if;

  normalized_type := replace(lower(coalesce(new.bookable_item_type,'')), ' ', '_');
  if normalized_type not in ('bar','bar_seat','counter','counter_seat') then
    return new;
  end if;

  requested_label := trim(coalesce(new.bookable_item_name,''));
  anchor_label := trim(split_part(requested_label, ',', 1));
  party := greatest(1, coalesce(new.party_size,1));
  v_duration_minutes := greatest(1, coalesce(new.duration_minutes, new.turn_time_minutes, 90));
  reservation_start := public.reserve_minutes(coalesce(new.reservation_time::text,'00:00'));

  select s.* into target_seat
  from public.reservation_seating_resources s
  where s.location_id = new.location_id
    and lower(s.label) = lower(anchor_label)
    and s.is_active
  limit 1;

  if found then
    parent_id := target_seat.parent_layout_item_id;
    anchor_index := target_seat.seat_index;
  else
    select l.id into parent_id
    from public.layout_items l
    where l.location_id = new.location_id
      and public.reserve_is_bar_type(l.item_type)
      and lower(trim(l.item_name)) = lower(requested_label)
      and coalesce(l.is_active,true)
    limit 1;
    anchor_index := 1;
  end if;

  if parent_id is null then
    raise exception 'Bar seating resource was not found. Refresh the floor and try again.';
  end if;

  select greatest(1, max(s.seat_index) - party + 1)
    into max_start
  from public.reservation_seating_resources s
  where s.parent_layout_item_id = parent_id and s.is_active;

  for candidate_start in 1..max_start loop
    if candidate_start > anchor_index or candidate_start + party - 1 < anchor_index then
      continue;
    end if;

    select array_agg(s.id order by s.seat_index), array_agg(s.label order by s.seat_index)
      into chosen, chosen_labels
    from public.reservation_seating_resources s
    where s.parent_layout_item_id = parent_id
      and s.is_active
      and s.seat_index between candidate_start and candidate_start + party - 1;

    if coalesce(array_length(chosen,1),0) <> party then
      chosen := null; chosen_labels := null;
      continue;
    end if;

    select count(*) into overlap_count
    from public.reservation_resource_assignments a
    join public.location_reservations r on r.id = a.reservation_id
    where a.seating_resource_id = any(chosen)
      and r.id <> new.id
      and lower(coalesce(r.status,'')) in ('pending','confirmed','checked_in','waiting','arrived','seated')
      and r.reservation_date = new.reservation_date
      and reservation_start < public.reserve_minutes(coalesce(r.reservation_time::text,'00:00')) + greatest(1,coalesce(r.duration_minutes,r.turn_time_minutes,90))
      and public.reserve_minutes(coalesce(r.reservation_time::text,'00:00')) < reservation_start + v_duration_minutes;

    if overlap_count = 0 then exit; end if;
    chosen := null; chosen_labels := null;
  end loop;

  if coalesce(array_length(chosen,1),0) <> party then
    chosen := null; chosen_labels := null;
    for candidate_start in 1..max_start loop
      select array_agg(s.id order by s.seat_index), array_agg(s.label order by s.seat_index)
        into chosen, chosen_labels
      from public.reservation_seating_resources s
      where s.parent_layout_item_id = parent_id
        and s.is_active
        and s.seat_index between candidate_start and candidate_start + party - 1;

      if coalesce(array_length(chosen,1),0) <> party then
        chosen := null; chosen_labels := null;
        continue;
      end if;

      select count(*) into overlap_count
      from public.reservation_resource_assignments a
      join public.location_reservations r on r.id = a.reservation_id
      where a.seating_resource_id = any(chosen)
        and r.id <> new.id
        and lower(coalesce(r.status,'')) in ('pending','confirmed','checked_in','waiting','arrived','seated')
        and r.reservation_date = new.reservation_date
        and reservation_start < public.reserve_minutes(coalesce(r.reservation_time::text,'00:00')) + greatest(1,coalesce(r.duration_minutes,r.turn_time_minutes,90))
        and public.reserve_minutes(coalesce(r.reservation_time::text,'00:00')) < reservation_start + v_duration_minutes;

      if overlap_count = 0 then exit; end if;
      chosen := null; chosen_labels := null;
    end loop;
  end if;

  if coalesce(array_length(chosen,1),0) <> party then
    raise exception 'There are not enough adjacent bar seats available for this party at that time.';
  end if;

  delete from public.reservation_resource_assignments where reservation_id = new.id;
  insert into public.reservation_resource_assignments(reservation_id, location_id, seating_resource_id)
    select new.id, new.location_id, unnest(chosen);

  new.bookable_item_id := null;
  new.bookable_item_type := case when normalized_type like 'counter%' then 'counter_seat' else 'bar_seat' end;
  new.bookable_item_name := array_to_string(chosen_labels, ', ');
  return new;
end;
$$;


ALTER FUNCTION "public"."reserve_bar_assignments_before_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_google_photo_request"("p_google_place_id" "text", "p_monthly_cap" integer DEFAULT 15000) RETURNS TABLE("allowed" boolean, "month_count" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_month date := date_trunc('month', now())::date;
  v_count integer;
begin
  insert into public.google_photo_usage_monthly(usage_month, request_count, updated_at)
  values (v_month, 0, now())
  on conflict (usage_month) do nothing;

  select request_count into v_count
  from public.google_photo_usage_monthly
  where usage_month = v_month
  for update;

  if p_monthly_cap > 0 and v_count >= p_monthly_cap then
    allowed := false;
    month_count := v_count;
    return next;
    return;
  end if;

  update public.google_photo_usage_monthly
  set request_count = request_count + 1,
      updated_at = now()
  where usage_month = v_month
  returning request_count into v_count;

  insert into public.google_photo_usage_daily(usage_date, google_place_id, request_count, last_requested_at)
  values (current_date, coalesce(nullif(p_google_place_id,''),'unknown'), 1, now())
  on conflict (usage_date, google_place_id)
  do update set request_count = public.google_photo_usage_daily.request_count + 1,
                last_requested_at = now();

  allowed := true;
  month_count := v_count;
  return next;
end;
$$;


