CREATE OR REPLACE FUNCTION "public"."reserve_partner_pro_included_domain"("p_location_id" "uuid", "p_domain_name" "text", "p_idempotency_key" "text") RETURNS "public"."domain_registration_operations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_location public.locations%rowtype;
  v_existing public.domain_registration_operations%rowtype;
  v_operation public.domain_registration_operations%rowtype;
  v_domain text := lower(trim(p_domain_name));
begin
  if v_domain is null or v_domain = '' then raise exception 'invalid_domain'; end if;
  select * into v_existing from public.domain_registration_operations where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.location_id <> p_location_id or lower(v_existing.domain_name) <> v_domain then raise exception 'idempotency_key_reused'; end if;
    return v_existing;
  end if;
  select * into v_location from public.locations where id = p_location_id for update;
  if not found then raise exception 'location_not_found'; end if;
  if lower(coalesce(v_location.subscription_plan, '')) <> 'business_pro' or lower(coalesce(v_location.subscription_status, '')) not in ('active','trialing') then raise exception 'partner_pro_required'; end if;
  if v_location.included_domain_claimed_at is not null and v_location.included_domain_name is not null and lower(v_location.included_domain_name) <> v_domain then raise exception 'included_domain_already_claimed'; end if;
  select * into v_existing from public.domain_registration_operations where location_id = p_location_id and status in ('reserved','registering','active') order by created_at desc limit 1;
  if found then
    if lower(v_existing.domain_name) <> v_domain then raise exception 'domain_claim_in_progress'; end if;
    return v_existing;
  end if;
  insert into public.domain_registration_operations(location_id,domain_name,idempotency_key,status)
  values(p_location_id,v_domain,p_idempotency_key,'reserved') returning * into v_operation;
  update public.locations set included_domain_name = coalesce(included_domain_name,v_domain), included_domain_status='pending' where id=p_location_id;
  return v_operation;
end;$$;


ALTER FUNCTION "public"."reserve_partner_pro_included_domain"("p_location_id" "uuid", "p_domain_name" "text", "p_idempotency_key" "text") OWNER TO "postgres";


