CREATE OR REPLACE FUNCTION "public"."resolve_worker_configuration_events_after_success"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = 'succeeded'
     and old.status is distinct from new.status then

    update public.worker_job_events
    set metadata =
      jsonb_set(
        jsonb_set(
          coalesce(metadata, '{}'::jsonb),
          '{code}',
          to_jsonb('HISTORICAL_UNSUPPORTED_WORKER_JOB_TYPE'::text),
          true
        ),
        '{resolved_at}',
        to_jsonb(now()),
        true
      )
      || jsonb_build_object(
        'resolved_by_status', new.status,
        'resolved_job_id', new.id
      )
    where job_id = new.id
      and metadata ->> 'code' = 'UNSUPPORTED_WORKER_JOB_TYPE';

  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."resolve_worker_configuration_events_after_success"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_worker_job"("p_job_id" "uuid", "p_run_after" timestamp with time zone DEFAULT "now"(), "p_grant_attempt" boolean DEFAULT false) RETURNS "public"."worker_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.worker_jobs;
  v_next_max_attempts integer;
begin
  select *
  into v_job
  from public.worker_jobs
  where id = p_job_id
  for update;

  if not found then
    raise exception 'Worker job % was not found', p_job_id
      using errcode = 'P0002';
  end if;

  if v_job.status not in ('failed', 'dead_letter', 'cancelled') then
    raise exception 'Worker job % cannot be retried from status %', p_job_id, v_job.status
      using errcode = 'P0001';
  end if;

  if v_job.attempt_count >= v_job.max_attempts and not p_grant_attempt then
    raise exception 'Worker job % has exhausted its attempts (%/%). Retry with p_grant_attempt=true to grant one additional attempt.', p_job_id, v_job.attempt_count, v_job.max_attempts
      using errcode = 'P0001';
  end if;

  v_next_max_attempts := case
    when p_grant_attempt and v_job.attempt_count >= v_job.max_attempts
      then v_job.attempt_count + 1
    else v_job.max_attempts
  end;

  update public.worker_jobs
  set status = 'queued',
      max_attempts = v_next_max_attempts,
      run_after = coalesce(p_run_after, now()),
      completed_at = null,
      lease_owner = null,
      lease_expires_at = null,
      cancellation_requested_at = null,
      updated_at = now()
  where id = p_job_id
  returning * into v_job;

  insert into public.worker_job_events(
    job_id,
    event_type,
    message,
    metadata,
    created_by
  ) values (
    p_job_id,
    'retried',
    case when p_grant_attempt then 'Job returned to queue with one additional attempt' else 'Job returned to queue' end,
    jsonb_build_object(
      'grant_attempt', p_grant_attempt,
      'attempt_count', v_job.attempt_count,
      'max_attempts', v_job.max_attempts
    ),
    'retry_worker_job'
  );

  return v_job;
end
$$;


ALTER FUNCTION "public"."retry_worker_job"("p_job_id" "uuid", "p_run_after" timestamp with time zone, "p_grant_attempt" boolean) OWNER TO "postgres";


