CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_activities_enterprise"("query_embedding" "public"."vector", "requested_city" "text" DEFAULT NULL::"text", "requested_activity" "text" DEFAULT NULL::"text", "match_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "activity_name" "text", "city" "text", "neighborhood" "text", "activity_type" "text", "description" "text", "address" "text", "latitude" double precision, "longitude" double precision, "rating" numeric, "review_count" integer, "image_url" "text", "website" "text", "reservation_link" "text", "semantic_similarity" double precision, "final_score" double precision)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    a.id,
    a.activity_name,
    a.city,
    a.neighborhood,
    a.activity_type,
    a.description,
    a.address,
    a.latitude,
    a.longitude,
    a.rating,
    a.review_count,
    a.image_url,
    a.website,
    a.reservation_link,
    1 - (a.embedding <=> query_embedding) as semantic_similarity,
    (
      (1 - (a.embedding <=> query_embedding)) * 0.8 +
      ((coalesce(a.rating, 0) / 5.0) * 0.2)
    ) as final_score
  from activities a
  where a.embedding is not null
    and (
      requested_city is null
      or lower(a.city) like '%' || lower(requested_city) || '%'
      or lower(a.neighborhood) like '%' || lower(requested_city) || '%'
      or lower(a.search_document) like '%' || lower(requested_city) || '%'
    )
    and (
      requested_activity is null
      or lower(a.activity_type) like '%' || lower(requested_activity) || '%'
      or lower(a.search_document) like '%' || lower(requested_activity) || '%'
    )
  order by final_score desc
  limit match_limit;
$$;


ALTER FUNCTION "public"."search_activities_enterprise"("query_embedding" "public"."vector", "requested_city" "text", "requested_activity" "text", "match_limit" integer) OWNER TO "postgres";


