CREATE OR REPLACE FUNCTION "public"."search_restaurants_enterprise"("query_embedding" "public"."vector", "requested_city" "text" DEFAULT NULL::"text", "requested_cuisine" "text" DEFAULT NULL::"text", "match_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "restaurant_name" "text", "city" "text", "neighborhood" "text", "cuisine_type" "text", "description" "text", "address" "text", "latitude" double precision, "longitude" double precision, "rating" numeric, "review_count" integer, "image_url" "text", "website" "text", "reservation_link" "text", "semantic_similarity" double precision, "final_score" double precision)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    r.id,
    r.restaurant_name,
    r.city,
    r.neighborhood,
    r.cuisine_type,
    r.description,
    r.address,
    r.latitude,
    r.longitude,
    r.rating,
    r.review_count,
    r.image_url,
    r.website,
    r.reservation_link,
    1 - (r.embedding <=> query_embedding) as semantic_similarity,
    (
      (1 - (r.embedding <=> query_embedding)) * 0.8 +
      ((coalesce(r.rating, 0) / 5.0) * 0.2)
    ) as final_score
  from restaurants r
  where r.embedding is not null
    and (
      requested_city is null

      or (
        lower(requested_city) = 'queens'
        and r.state = 'NY'
        and r.latitude between 40.48 and 40.82
        and r.longitude between -73.96 and -73.68
      )

      or lower(r.city) like '%' || lower(requested_city) || '%'
      or lower(r.neighborhood) like '%' || lower(requested_city) || '%'
      or lower(r.search_document) like '%' || lower(requested_city) || '%'
    )
    and (
      requested_cuisine is null
      or lower(r.cuisine_type) like '%' || lower(requested_cuisine) || '%'
      or lower(r.search_document) like '%' || lower(requested_cuisine) || '%'
    )
  order by final_score desc
  limit match_limit;
$$;


ALTER FUNCTION "public"."search_restaurants_enterprise"("query_embedding" "public"."vector", "requested_city" "text", "requested_cuisine" "text", "match_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_restaurants_rpc"("query_text" "text", "query_embedding" "public"."vector", "requested_city" "text" DEFAULT NULL::"text", "requested_cuisine" "text" DEFAULT NULL::"text", "match_limit" integer DEFAULT 40) RETURNS TABLE("id" "uuid", "restaurant_name" "text", "city" "text", "neighborhood" "text", "cuisine_type" "text", "description" "text", "address" "text", "latitude" double precision, "longitude" double precision, "rating" numeric, "review_count" integer, "image_url" "text", "website" "text", "reservation_link" "text", "similarity" double precision, "semantic_score" double precision, "final_score" double precision)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    r.id,
    r.restaurant_name,
    r.city,
    r.neighborhood,
    r.cuisine_type,
    r.description,
    r.address,
    r.latitude,
    r.longitude,
    r.rating,
    r.review_count,
    r.image_url,
    r.website,
    r.reservation_link,

    1 - (r.embedding <=> query_embedding) as similarity,

    (
      coalesce(r.rating, 0) * 20 +
      ln(coalesce(r.review_count, 0) + 1) * 10
    ) as semantic_score,

    (
      (1 - (r.embedding <=> query_embedding)) * 0.75 +
      (
        (
          coalesce(r.rating, 0) * 20 +
          ln(coalesce(r.review_count, 0) + 1) * 10
        ) / 100
      ) * 0.25
    ) as final_score

  from restaurants r

  where
    r.embedding is not null

    and (
      requested_city is null
      or lower(r.city) like '%' || lower(requested_city) || '%'
      or lower(r.neighborhood) like '%' || lower(requested_city) || '%'
      or lower(r.search_document) like '%' || lower(requested_city) || '%'
    )

    and (
      requested_cuisine is null
      or lower(r.cuisine_type) like '%' || lower(requested_cuisine) || '%'
      or lower(r.search_document) like '%' || lower(requested_cuisine) || '%'
    )

  order by final_score desc

  limit match_limit;
$$;


ALTER FUNCTION "public"."search_restaurants_rpc"("query_text" "text", "query_embedding" "public"."vector", "requested_city" "text", "requested_cuisine" "text", "match_limit" integer) OWNER TO "postgres";


