CREATE OR REPLACE FUNCTION "public"."set_location_photo_profile_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_score integer;
begin
  v_score := public.location_profile_completion_score(new);
  new.profile_completion_score := v_score;
  new.profile_completion_status := case
    when v_score >= 100 then 'complete'
    when coalesce(new.owner_photo_count,0) >= 3 then 'photo_ready'
    when coalesce(new.owner_photo_count,0) >= 1 then 'getting_started'
    else 'using_public_imagery'
  end;
  new.google_gallery_limit := greatest(0, 5 - least(5, coalesce(new.owner_photo_count,0)));
  if coalesce(new.owner_photo_count,0) >= 3 then
    new.photo_nudge_status := 'completed';
    new.photo_nudge_completed_at := coalesce(new.photo_nudge_completed_at, now());
  end if;
  return new;
end;
$$;


