CREATE OR REPLACE FUNCTION "public"."start_search_ranking_rollout_run"("target_stage_key" "text", "actor_user_id" "uuid", "reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  run_id uuid;
  current_snapshot jsonb;
begin
  if exists (
    select 1
    from public.search_ranking_rollout_runs
    where status = 'active'
  ) then
    raise exception
      'An active rollout run already exists';
  end if;

  select to_jsonb(r)
  into current_snapshot
  from public.search_ranking_rollout_readiness_v1 r
  limit 1;

  insert into public.search_ranking_rollout_runs (
    stage_key,
    status,
    started_by,
    baseline_snapshot,
    completion_reason
  )
  values (
    target_stage_key,
    'active',
    actor_user_id,
    coalesce(
      current_snapshot,
      '{}'::jsonb
    ),
    reason
  )
  returning id into run_id;

  insert into public.search_ranking_rollout_audit_log (
    rollout_run_id,
    actor_user_id,
    action,
    to_stage_key,
    reason
  )
  values (
    run_id,
    actor_user_id,
    'rollout_run_started',
    target_stage_key,
    reason
  );

  return run_id;
end;
$$;


ALTER FUNCTION "public"."start_search_ranking_rollout_run"("target_stage_key" "text", "actor_user_id" "uuid", "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_team_work_session"("p_work_type" "text", "p_device_id" "text" DEFAULT NULL::"text", "p_device_name" "text" DEFAULT NULL::"text", "p_is_training" boolean DEFAULT false, "p_is_demo" boolean DEFAULT false, "p_demo_session_id" "uuid" DEFAULT NULL::"uuid", "p_user_notes" "text" DEFAULT NULL::"text") RETURNS "public"."team_work_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.team_member_profiles%rowtype;
  v_session public.team_work_sessions%rowtype;
  v_is_remote boolean := true;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;
  select * into v_profile from public.team_member_profiles where user_id = v_user_id and status in ('active','training') limit 1;
  if not found then
    raise exception 'A team member profile is required before clocking in.';
  end if;
  if coalesce(v_profile.can_clock_in, false) is not true or coalesce(v_profile.can_track_work, false) is not true then
    raise exception 'Clock-in is not enabled for your team profile.';
  end if;
  if not public.is_work_type_allowed_for_user(v_user_id, p_work_type) then
    raise exception 'This work type is not allowed for your team profile.';
  end if;
  if exists (select 1 from public.team_work_sessions where user_id = v_user_id and status = 'active') then
    raise exception 'You already have an active work session.';
  end if;
  v_is_remote := case when v_profile.team_type in ('experience_team','support_team') or p_work_type in ('social_outreach','phone_outreach','email_outreach','customer_support','owner_support','reservation_support','claim_support','support_ticket','admin_work') then true else false end;
  insert into public.team_work_sessions(team_member_id,user_id,team_type,work_type,device_id,device_name,is_remote,is_training,is_demo,demo_session_id,user_notes)
  values (v_profile.id, v_user_id, v_profile.team_type, p_work_type, p_device_id, p_device_name, v_is_remote, p_is_training, p_is_demo, p_demo_session_id, p_user_notes)
  returning * into v_session;
  return v_session;
end;
$$;


ALTER FUNCTION "public"."start_team_work_session"("p_work_type" "text", "p_device_id" "text", "p_device_name" "text", "p_is_training" boolean, "p_is_demo" boolean, "p_demo_session_id" "uuid", "p_user_notes" "text") OWNER TO "postgres";


