CREATE OR REPLACE FUNCTION "public"."sync_canonical_google_enrichment_to_source"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.google_enriched_at is null then
    return new;
  end if;

  if new.source_table = 'restaurants' and new.source_id is not null then
    update public.restaurants
    set google_place_id = coalesce(new.google_place_id, google_place_id),
        google_enrichment_status = new.google_enrichment_status,
        google_enriched_at = new.google_enriched_at,
        google_primary_type = new.google_primary_type,
        google_types = new.google_types,
        google_maps_uri = new.google_maps_uri,
        google_website_uri = new.google_website_uri,
        google_rating = new.google_rating,
        google_user_rating_count = new.google_user_rating_count,
        google_business_status = new.google_business_status,
        google_business_status_checked_at = new.google_business_status_checked_at,
        google_last_error = new.google_last_error
    where id = new.source_id and (google_enriched_at is null or google_enriched_at < new.google_enriched_at);
  elsif new.source_table = 'activities' and new.source_id is not null then
    update public.activities
    set google_place_id = coalesce(new.google_place_id, google_place_id),
        google_enrichment_status = new.google_enrichment_status,
        google_enriched_at = new.google_enriched_at,
        google_primary_type = new.google_primary_type,
        google_types = new.google_types,
        google_maps_uri = new.google_maps_uri,
        google_website_uri = new.google_website_uri,
        google_rating = new.google_rating,
        google_user_rating_count = new.google_user_rating_count,
        google_business_status = new.google_business_status,
        google_business_status_checked_at = new.google_business_status_checked_at,
        google_last_error = new.google_last_error
    where id = new.source_id and (google_enriched_at is null or google_enriched_at < new.google_enriched_at);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_canonical_google_enrichment_to_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_crm_call_to_location_communication_log"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing_id uuid;
  v_metadata jsonb;
begin
  if new.location_id is null then return new; end if;
  if lower(new.activity_type) not in ('call','phone_call') and lower(coalesce(new.channel,'')) not in ('call','phone') then return new; end if;

  v_metadata := jsonb_strip_nulls(jsonb_build_object(
    'canonical', true,
    'crm_activity_id', new.id::text,
    'activity_type', new.activity_type,
    'source_system', new.source_system,
    'source_table', new.source_table,
    'source_record_id', new.source_record_id,
    'outcome', new.outcome,
    'visibility', new.visibility,
    'is_system_generated', new.is_system_generated
  )) || coalesce(new.metadata, '{}'::jsonb);

  select id into v_existing_id from public.communication_logs where metadata->>'crm_activity_id'=new.id::text order by created_at desc nulls last limit 1;
  if v_existing_id is null then
    insert into public.communication_logs(channel,direction,recipient_type,recipient_id,subject,body,status,metadata,created_by,created_at)
    values('call',coalesce(new.direction,'outbound'),'location',new.location_id::text,coalesce(new.subject,new.summary),coalesce(new.body,new.summary),coalesce(new.outcome,'completed'),v_metadata,new.actor_user_id,coalesce(new.occurred_at,new.created_at,now()));
  else
    update public.communication_logs set channel='call',direction=coalesce(new.direction,direction),subject=coalesce(new.subject,new.summary,subject),body=coalesce(new.body,new.summary,body),status=coalesce(new.outcome,status),metadata=v_metadata,created_by=coalesce(new.actor_user_id,created_by) where id=v_existing_id;
  end if;
  return new;
end; $$;


ALTER FUNCTION "public"."sync_crm_call_to_location_communication_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_crm_message_to_location_communication_log"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_conversation public.crm_conversations%rowtype;
  v_existing_id uuid;
  v_metadata jsonb;
begin
  select * into v_conversation from public.crm_conversations where id = new.conversation_id;
  if v_conversation.id is null or v_conversation.location_id is null then return new; end if;

  v_metadata := jsonb_strip_nulls(jsonb_build_object(
    'canonical', true,
    'canonical_crm_message_id', new.id::text,
    'conversation_id', new.conversation_id::text,
    'source_system', new.source_system,
    'message_type', new.message_type,
    'assigned_team', v_conversation.assigned_team,
    'reservation_id', v_conversation.reservation_id,
    'support_ticket_id', v_conversation.support_ticket_id,
    'conversation_key', v_conversation.conversation_key,
    'is_internal', new.is_internal,
    'is_ai_assisted', new.is_ai_assisted,
    'failure_code', new.failure_code,
    'failure_reason', new.failure_reason,
    'opened_at', new.opened_at,
    'clicked_at', new.clicked_at,
    'replied_at', new.replied_at,
    'delivered_at', new.delivered_at,
    'sent_at', new.sent_at
  )) || coalesce(new.metadata, '{}'::jsonb);

  select id into v_existing_id from public.communication_logs
  where metadata->>'canonical_crm_message_id' = new.id::text
  order by created_at desc nulls last limit 1;

  if v_existing_id is null then
    insert into public.communication_logs(channel,direction,from_address,to_address,recipient_type,recipient_id,subject,body,status,provider_message_id,metadata,created_by,created_at)
    values(new.channel,new.direction,coalesce(new.metadata->>'from',new.metadata->>'from_address'),coalesce(new.metadata->>'to',new.metadata->>'to_address'),'location',v_conversation.location_id::text,coalesce(new.subject,v_conversation.subject),coalesce(new.body_text,new.preview_text,''),new.status,new.provider_message_id,v_metadata,new.sender_user_id,coalesce(new.created_at,now()));
  else
    update public.communication_logs set
      channel=new.channel,
      direction=new.direction,
      from_address=coalesce(new.metadata->>'from',new.metadata->>'from_address',from_address),
      to_address=coalesce(new.metadata->>'to',new.metadata->>'to_address',to_address),
      subject=coalesce(new.subject,v_conversation.subject,subject),
      body=coalesce(new.body_text,new.preview_text,body),
      status=new.status,
      provider_message_id=coalesce(new.provider_message_id,provider_message_id),
      metadata=v_metadata,
      created_by=coalesce(new.sender_user_id,created_by)
    where id=v_existing_id;
  end if;
  return new;
end; $$;


ALTER FUNCTION "public"."sync_crm_message_to_location_communication_log"() OWNER TO "postgres";


