  if new.status = 'confirmed' and new.payment_status in ('paid','not_required') then
    update public.experience_table_blocks set status='confirmed', hold_expires_at=null, updated_at=now()
      where experience_booking_id=new.id and status <> 'released';
  elsif new.status in ('cancelled','no_show','completed') then
    update public.experience_table_blocks set status='released', updated_at=now()
      where experience_booking_id=new.id and status <> 'released';
  end if;
  return new;
end;
