CREATE OR REPLACE FUNCTION "public"."sync_group_dining_booking_to_host_view"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  exp_row public.experiences%rowtype;
  slot_row public.experience_slots%rowtype;
  host_status text;
begin
  select * into exp_row from public.experiences where id = new.experience_id;
  if not found or exp_row.experience_type <> 'group_dining' or exp_row.location_id is null then
    return new;
  end if;

  select * into slot_row from public.experience_slots where id = new.slot_id;
  if not found then return new; end if;

  host_status := case new.status
    when 'pending_payment' then 'pending'
    when 'confirmed' then 'confirmed'
    when 'completed' then 'completed'
    when 'cancelled' then 'cancelled'
    when 'no_show' then 'no_show'
    else 'confirmed'
  end;

  if new.status = 'pending_payment' then
    delete from public.location_reservations where experience_booking_id = new.id;
    return new;
  end if;

  insert into public.location_reservations (
    location_id, location_type, bookable_item_id, bookable_item_name, bookable_item_type,
    customer_name, customer_email, customer_phone, reservation_date, reservation_time,
    party_size, status, source, special_request, special_requests, duration_minutes,
    checked_in_at, completed_at, cancelled_at, updated_at, experience_booking_id
  ) values (
    exp_row.location_id, 'location', exp_row.id, exp_row.title, 'experience',
    new.customer_name, new.customer_email, new.customer_phone,
    (slot_row.starts_at at time zone 'America/New_York')::date,
    (slot_row.starts_at at time zone 'America/New_York')::time,
    new.party_size, host_status, 'experience_prepaid',
    'Prepaid Group Dining Experience', 'Prepaid Group Dining Experience', exp_row.duration_minutes,
    new.checked_in_at, case when new.status='completed' then coalesce(new.checked_in_at, now()) else null end,
    case when new.status='cancelled' then now() else null end, now(), new.id
  )
  on conflict (experience_booking_id) where experience_booking_id is not null do update set
    customer_name = excluded.customer_name,
    customer_email = excluded.customer_email,
    customer_phone = excluded.customer_phone,
    reservation_date = excluded.reservation_date,
    reservation_time = excluded.reservation_time,
    party_size = excluded.party_size,
    status = excluded.status,
    bookable_item_name = excluded.bookable_item_name,
    duration_minutes = excluded.duration_minutes,
    checked_in_at = excluded.checked_in_at,
    completed_at = excluded.completed_at,
    cancelled_at = excluded.cancelled_at,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_group_dining_booking_to_host_view"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_location_neighborhood_from_coordinates"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v record;
begin
  if new.latitude is null or new.longitude is null then
    return new;
  end if;

  if tg_op = 'INSERT'
     or new.latitude is distinct from old.latitude
     or new.longitude is distinct from old.longitude
     or new.state is distinct from old.state
     or new.neighborhood is null
     or new.local_area_code is null then
    select * into v
    from public.lookup_local_area(new.latitude::double precision, new.longitude::double precision, new.state)
    limit 1;

    if found then
      new.neighborhood := v.area_name;
      new.local_area_code := v.area_code;
      new.local_area_type := v.area_type;
      new.neighborhood_source := v.area_source;
      new.neighborhood_resolved_at := now();

      if v.area_type = 'nyc_nta' then
        new.neighborhood_nta_code := v.area_code;
        new.borough := v.borough;
      else
        new.neighborhood_nta_code := null;
      end if;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_location_neighborhood_from_coordinates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_location_photo_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner_count integer;
  v_previous_component numeric := 0;
  v_next_component numeric := 0;
  v_base_search_boost numeric := 0;
begin
  new.owner_photo_urls := coalesce((
    select array_agg(distinct u order by u)
    from unnest(coalesce(new.owner_photo_urls, '{}'::text[])) as u
    where nullif(btrim(u),'') is not null
  ), '{}'::text[]);

  v_owner_count := cardinality(new.owner_photo_urls);
  new.owner_photo_count := v_owner_count;
  new.has_owner_photos := v_owner_count > 0;

  if v_owner_count >= 3 then
    new.photo_nudges_completed := true;
  elsif tg_op = 'UPDATE' then
    new.photo_nudges_completed := coalesce(old.photo_nudges_completed,false);
  end if;

  new.profile_completion_score := public.location_profile_completion_score(new);

  v_next_component := case
    when v_owner_count >= 5 then 3.0
    when v_owner_count >= 3 then 2.0
    when v_owner_count >= 1 then 1.0
    else 0.0
  end;

  if tg_op = 'UPDATE' then
    v_previous_component := coalesce(old.profile_photo_search_boost,0);
  end if;
  v_base_search_boost := coalesce(new.search_boost,0) - v_previous_component;
  new.profile_photo_search_boost := v_next_component;
  new.search_boost := v_base_search_boost + v_next_component;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_location_photo_ownership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_location_signature_search_text"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
declare
  v_marker constant text := '__menu_signature_items__';
  v_signature_text text;
  v_search_base text;
  v_semantic_base text;
begin
  v_signature_text := trim(array_to_string(coalesce(new.signature_items, '{}'::text[]), ' '));
  v_search_base := trim(regexp_replace(coalesce(new.search_document, ''), '\s*__menu_signature_items__\s+.*$', '', 'i'));
  v_semantic_base := trim(regexp_replace(coalesce(new.semantic_search_text, ''), '\s*__menu_signature_items__\s+.*$', '', 'i'));
  if v_signature_text <> '' then
    new.search_document := trim(concat_ws(' ', nullif(v_search_base, ''), v_marker, v_signature_text));
    new.semantic_search_text := trim(concat_ws(' ', nullif(v_semantic_base, ''), v_marker, v_signature_text));
  else
    new.search_document := nullif(v_search_base, '');
    new.semantic_search_text := nullif(v_semantic_base, '');
  end if;
  return new;
end;
$_$;


ALTER FUNCTION "public"."sync_location_signature_search_text"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_outing_external_booking_requirements"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_outing_id uuid := new.outing_id;
  v_followup_phone text := new.followup_phone;
  v_required integer := 0;
  v_confirmed integer := 0;
  v_url text;
begin
  if pg_trigger_depth() = 1 then
    insert into public.outing_external_bookings (
      outing_id,
      location_id,
      location_type,
      provider,
      status,
      followup_phone,
      metadata,
      updated_at
    )
    select
      o.id,
      l.id,
      case when l.id = o.restaurant_location_id then 'restaurant' else 'activity' end,
      case
        when lower(v.url) like '%opentable%' then 'OpenTable'
        when lower(v.url) like '%resy%' then 'Resy'
        when lower(v.url) like '%sevenrooms%' then 'SevenRooms'
        when lower(v.url) like '%tock%' then 'Tock'
        when lower(v.url) like '%yelp%' then 'Yelp'
        else 'External provider'
      end,
      'available',
      v_followup_phone,
      jsonb_build_object('source', 'booking_requirement_sync'),
      now()
    from public.outings o
    join public.locations l
      on l.id = o.restaurant_location_id or l.id = o.activity_location_id
    cross join lateral (
      select nullif(btrim(coalesce(l.external_reservation_url, l.reservation_url, l.reservation_link, l.booking_url, '')), '') as url
    ) v
    where o.id = v_outing_id
      and v.url is not null
      and v.url ~* '^https?://'
      and lower(v.url) not like '%theouthaven.com%'
      and lower(v.url) not like '%outhvn.com%'
    on conflict (outing_id, location_id) do update
      set followup_phone = coalesce(excluded.followup_phone, public.outing_external_bookings.followup_phone),
          updated_at = now()
      where public.outing_external_bookings.status = 'available';
  end if;

  select
    count(*)::integer,
    count(*) filter (where status = 'confirmed')::integer
  into v_required, v_confirmed
  from public.outing_external_bookings
  where outing_id = v_outing_id;

  update public.outings
  set external_bookings_required_count = v_required,
      external_bookings_confirmed_count = v_confirmed,
      external_bookings_complete = (v_required > 0 and v_required = v_confirmed)
  where id = v_outing_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_outing_external_booking_requirements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_photo_nudge_delivery_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_sent_count integer;
  v_last_sent timestamptz;
begin
  if new.message_type not in ('photo_reminder_day3','photo_reminder_day7') then
    return new;
  end if;

  if new.status <> 'sent' then
    return new;
  end if;

  select count(*)::integer, max(sent_at)
  into v_sent_count, v_last_sent
  from public.profile_completion_nurture_queue
  where location_id = new.location_id
    and message_type in ('photo_reminder_day3','photo_reminder_day7')
    and status = 'sent';

  update public.locations
  set photo_nudge_count = greatest(coalesce(photo_nudge_count,0), coalesce(v_sent_count,0)),
      last_photo_nudge_at = greatest(coalesce(last_photo_nudge_at,'epoch'::timestamptz), coalesce(v_last_sent,new.sent_at,now())),
      updated_at = greatest(coalesce(updated_at,'epoch'::timestamptz), now())
  where id = new.location_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_photo_nudge_delivery_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_search_log_replay_query"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if nullif(btrim(new.query), '') is null then
    new.query := coalesce(
      nullif(btrim(to_jsonb(new) ->> 'normalized_query'), ''),
      nullif(btrim(to_jsonb(new) ->> 'raw_query'), '')
    );
  end if;

  return new;
end;
$$;


