CREATE OR REPLACE FUNCTION "public"."sync_search_profile_run_compatibility"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.configuration := coalesce(new.configuration, '{}'::jsonb);
  new.filters := coalesce(new.filters, '{}'::jsonb);

  if new.mode is null and new.run_type is not null then
    new.mode := case new.run_type
      when 'full_backfill' then 'all_eligible'
      when 'filtered_backfill' then 'filtered'
      when 'missing_only' then 'missing_only'
      when 'stale_only' then 'stale_only'
      when 'selected_locations' then 'selected_locations'
      when 'validation' then 'validation'
      when 'single_location' then 'single_location'
      else 'all_eligible'
    end;
  end if;

  if new.run_type is null then
    new.run_type := case new.mode
      when 'all_eligible' then 'full_backfill'
      when 'filtered' then 'filtered_backfill'
      when 'missing_only' then 'missing_only'
      when 'stale_only' then 'stale_only'
      when 'selected_locations' then 'selected_locations'
      when 'validation' then 'validation'
      when 'single_location' then 'single_location'
      else 'filtered_backfill'
    end;
  end if;

  new.batch_size := coalesce(
    nullif(new.configuration ->> 'batchSize', '')::integer,
    new.batch_size,
    50
  );

  new.current_batch := coalesce(new.current_batch, 0);
  new.error_summary := coalesce(new.error_summary, '{}'::jsonb);
  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  new.requested_at := coalesce(new.requested_at, now());
  new.created_at := coalesce(new.created_at, now());
  new.updated_at := now();

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_search_profile_run_compatibility"() OWNER TO "postgres";


