CREATE OR REPLACE FUNCTION "public"."sync_support_message_to_location_communication_log"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_ticket public.support_tickets%rowtype;
  v_location_id uuid;
  v_existing_id uuid;
  v_channel text;
  v_direction text;
  v_metadata jsonb;
begin
  if coalesce(new.internal_note,false) then return new; end if;
  select * into v_ticket from public.support_tickets where id=new.ticket_id;
  v_location_id := coalesce(v_ticket.location_id,v_ticket.related_location_id);
  if v_location_id is null then return new; end if;
  v_channel := lower(coalesce(nullif(new.channel,''),'web'));
  if v_channel not in ('email','sms','web') then v_channel := 'web'; end if;
  v_direction := lower(coalesce(nullif(new.direction,''),case when lower(coalesce(new.actor_type,'')) in ('admin','system') then 'outbound' else 'inbound' end));
  if v_direction not in ('outbound','inbound') then v_direction := 'inbound'; end if;

  v_metadata := jsonb_strip_nulls(jsonb_build_object(
    'canonical', true,
    'support_ticket_message_id', new.id::text,
    'support_ticket_id', new.ticket_id::text,
    'ticket_number', v_ticket.ticket_number,
    'department', v_ticket.department,
    'assigned_group', v_ticket.assigned_group,
    'actor_type', new.actor_type,
    'sender_role', new.sender_role,
    'provider', new.provider,
    'delivered_at', new.delivered_at,
    'failed_at', new.failed_at
  )) || coalesce(new.metadata,'{}'::jsonb);

  select id into v_existing_id from public.communication_logs where metadata->>'support_ticket_message_id'=new.id::text order by created_at desc nulls last limit 1;
  if v_existing_id is null then
    insert into public.communication_logs(channel,direction,from_address,to_address,recipient_type,recipient_id,subject,body,status,provider_message_id,metadata,created_by,created_at)
    values(v_channel,v_direction,new.from_address,new.to_address,'location',v_location_id::text,coalesce(new.subject,v_ticket.subject),coalesce(new.message,new.body,''),coalesce(new.delivery_status,'sent'),new.provider_message_id,v_metadata,new.sender_user_id,new.created_at);
  else
    update public.communication_logs set channel=v_channel,direction=v_direction,from_address=coalesce(new.from_address,from_address),to_address=coalesce(new.to_address,to_address),subject=coalesce(new.subject,v_ticket.subject,subject),body=coalesce(new.message,new.body,body),status=coalesce(new.delivery_status,status),provider_message_id=coalesce(new.provider_message_id,provider_message_id),metadata=v_metadata,created_by=coalesce(new.sender_user_id,created_by) where id=v_existing_id;
  end if;
  return new;
end; $$;


