CREATE OR REPLACE FUNCTION "public"."toh_clean_street_address"("p_address" "text", "p_city" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_zip" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  v text := trim(coalesce(p_address, ''));
  c text := trim(coalesce(p_city, ''));
  s text := trim(coalesce(p_state, ''));
  z text := trim(coalesce(p_zip, ''));
begin
  if v = '' then
    return null;
  end if;

  -- Remove trailing "City, ST ZIP"
  if c <> '' and s <> '' and z <> '' then
    v := regexp_replace(
      v,
      ',?\s*' || c || '\s*,\s*' || s || '\s*,?\s*' || z || '\s*$',
      '',
      'i'
    );
  end if;

  -- Remove trailing "City, ST"
  if c <> '' and s <> '' then
    v := regexp_replace(
      v,
      ',?\s*' || c || '\s*,\s*' || s || '\s*$',
      '',
      'i'
    );
  end if;

  -- Remove trailing "ST ZIP"
  if s <> '' and z <> '' then
    v := regexp_replace(
      v,
      ',?\s*' || s || '\s*,?\s*' || z || '\s*$',
      '',
      'i'
    );
  end if;

  -- Remove trailing ZIP only
  if z <> '' then
    v := regexp_replace(
      v,
      ',?\s*' || z || '\s*$',
      '',
      'i'
    );
  end if;

  v := regexp_replace(v, '\s*,\s*$', '', 'g');
  v := regexp_replace(v, '\s+', ' ', 'g');

  return nullif(trim(v), '');
end;
$_$;


ALTER FUNCTION "public"."toh_clean_street_address"("p_address" "text", "p_city" "text", "p_state" "text", "p_zip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toh_guard_reservation_token_expiry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  reservation_start timestamptz;
  minimum_expiry timestamptz;
  lifecycle_expiry timestamptz;
begin
  if new.customer_token is null then
    return new;
  end if;

  reservation_start := public.toh_reservation_start_at_ny(new.reservation_date, new.reservation_time);
  minimum_expiry := now() + interval '72 hours';
  lifecycle_expiry := reservation_start + interval '24 hours';

  new.customer_token_expires_at := greatest(
    coalesce(new.customer_token_expires_at, '-infinity'::timestamptz),
    minimum_expiry,
    lifecycle_expiry
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."toh_guard_reservation_token_expiry"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."toh_guard_reservation_token_expiry"() IS 'Keeps customer management tokens valid for at least 72 hours and through 24 hours after the reservation.';



CREATE OR REPLACE FUNCTION "public"."toh_infer_market"("input_city" "text", "input_state" "text", "input_borough" "text", "input_address" "text", "input_postal_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  city_text text := lower(trim(coalesce(input_city, '')));
  state_text text := upper(trim(coalesce(input_state, '')));
  borough_text text := lower(trim(coalesce(input_borough, '')));
  address_text text := lower(trim(coalesce(input_address, '')));
  postal_text text := trim(coalesce(input_postal_code, ''));
  haystack text;
begin
  haystack := trim(
    concat_ws(
      ' ',
      city_text,
      state_text,
      borough_text,
      address_text,
      postal_text
    )
  );

  -- NYC_CORE: all 5 boroughs and NYC neighborhoods
  if state_text = 'NY'
    and (
      borough_text in (
        'manhattan',
        'brooklyn',
        'queens',
        'bronx',
        'the bronx',
        'staten island'
      )
      or city_text in (
        'new york',
        'new york city',
        'manhattan',
        'brooklyn',
        'queens',
        'bronx',
        'the bronx',
        'staten island',
        'astoria',
        'long island city',
        'lic',
        'flushing',
        'jamaica',
        'forest hills',
        'harlem',
        'williamsburg',
        'bushwick',
        'dumbo',
        'riverdale',
        'fordham',
        'pelham bay',
        'st george',
        'st. george',
        'stapleton'
      )
      or haystack like '%new york city%'
      or haystack like '%nyc%'
      or haystack like '%manhattan%'
      or haystack like '%brooklyn%'
      or haystack like '%queens%'
      or haystack like '%bronx%'
      or haystack like '%staten island%'
      or haystack like '%astoria%'
      or haystack like '%long island city%'
      or haystack like '%flushing%'
      or haystack like '%jamaica%'
      or haystack like '%forest hills%'
      or haystack like '%harlem%'
      or haystack like '%williamsburg%'
      or haystack like '%bushwick%'
      or haystack like '%riverdale%'
      or haystack like '%fordham%'
      or haystack like '%pelham bay%'
      or haystack like '%st george%'
      or haystack like '%st. george%'
      or haystack like '%stapleton%'
    )
  then
    return 'NYC_CORE';
  end if;

  -- LONG_ISLAND
  if state_text = 'NY'
    and (
      haystack like '%long island%'
      or haystack like '%nassau county%'
      or haystack like '%suffolk county%'
      or city_text in (
        'garden city',
        'huntington',
        'rockville centre',
        'farmingdale',
        'wantagh',
        'seaford',
        'east rockaway',
        'hempstead',
        'mineola',
        'westbury',
        'uniondale',
        'freeport',
        'bay shore',
        'patchogue',
        'melville',
        'roslyn',
        'great neck',
        'massapequa',
        'levittown',
        'hicksville',
        'commack',
        'babylon',
        'islip',
        'smithtown',
        'port jefferson'
      )
      or haystack like '%garden city%'
      or haystack like '%huntington%'
      or haystack like '%rockville centre%'
      or haystack like '%farmingdale%'
      or haystack like '%wantagh%'
      or haystack like '%seaford%'
      or haystack like '%east rockaway%'
      or haystack like '%hempstead%'
      or haystack like '%mineola%'
      or haystack like '%westbury%'
      or haystack like '%uniondale%'
      or haystack like '%freeport%'
      or haystack like '%bay shore%'
      or haystack like '%patchogue%'
      or haystack like '%melville%'
      or haystack like '%roslyn%'
      or haystack like '%great neck%'
      or haystack like '%massapequa%'
      or haystack like '%levittown%'
      or haystack like '%hicksville%'
      or haystack like '%commack%'
      or haystack like '%babylon%'
      or haystack like '%islip%'
      or haystack like '%smithtown%'
      or haystack like '%port jefferson%'
    )
  then
    return 'LONG_ISLAND';
  end if;

  -- WESTCHESTER
  if state_text = 'NY'
    and (
      haystack like '%westchester%'
      or haystack like '%westchester county%'
      or city_text in (
        'white plains',
        'yonkers',
        'new rochelle',
        'mount vernon',
        'scarsdale',
        'rye',
        'tarrytown',
        'peekskill',
        'dobbs ferry',
        'bronxville',
        'mamaroneck',
        'port chester',
        'ossining',
        'sleepy hollow',
        'hastings-on-hudson',
        'hastings on hudson'
      )
      or haystack like '%white plains%'
      or haystack like '%yonkers%'
      or haystack like '%new rochelle%'
      or haystack like '%mount vernon%'
      or haystack like '%scarsdale%'
      or haystack like '%tarrytown%'
      or haystack like '%peekskill%'
      or haystack like '%dobbs ferry%'
      or haystack like '%bronxville%'
      or haystack like '%mamaroneck%'
      or haystack like '%port chester%'
      or haystack like '%ossining%'
      or haystack like '%sleepy hollow%'
      or haystack like '%hastings-on-hudson%'
      or haystack like '%hastings on hudson%'
    )
  then
    return 'WESTCHESTER';
  end if;

  -- NORTH JERSEY
  -- Your current repo uses NORTHERN_NJ as the stored key.
  if state_text = 'NJ'
    and (
      haystack like '%north jersey%'
      or haystack like '%northern nj%'
      or haystack like '%bergen county%'
      or haystack like '%hudson county%'
      or haystack like '%essex county%'
      or haystack like '%union county%'
      or haystack like '%passaic county%'
      or city_text in (
        'jersey city',
        'hoboken',
        'newark',
        'montclair',
        'fort lee',
        'edgewater',
        'weehawken',
        'union city',
        'elizabeth',
        'hackensack',
        'paterson',
        'clifton',
        'secaucus',
        'teaneck',
        'englewood'
      )
      or haystack like '%jersey city%'
      or haystack like '%hoboken%'
      or haystack like '%newark%'
      or haystack like '%montclair%'
      or haystack like '%fort lee%'
      or haystack like '%edgewater%'
      or haystack like '%weehawken%'
      or haystack like '%union city%'
      or haystack like '%elizabeth%'
      or haystack like '%hackensack%'
      or haystack like '%paterson%'
      or haystack like '%clifton%'
      or haystack like '%secaucus%'
      or haystack like '%teaneck%'
      or haystack like '%englewood%'
    )
  then
    return 'NORTHERN_NJ';
  end if;

  -- CONNECTICUT
  if state_text = 'CT'
    and (
      haystack like '%connecticut%'
      or haystack like '%fairfield county%'
      or haystack like '%new haven county%'
      or haystack like '%hartford county%'
      or city_text in (
        'stamford',
        'norwalk',
        'greenwich',
        'bridgeport',
        'new haven',
        'fairfield',
        'westport',
        'danbury',
        'hartford',
        'milford',
        'stratford',
        'trumbull',
        'darien',
        'new canaan'
      )
      or haystack like '%stamford%'
      or haystack like '%norwalk%'
      or haystack like '%greenwich%'
      or haystack like '%bridgeport%'
      or haystack like '%new haven%'
      or haystack like '%fairfield%'
      or haystack like '%westport%'
      or haystack like '%danbury%'
      or haystack like '%hartford%'
      or haystack like '%milford%'
      or haystack like '%stratford%'
      or haystack like '%trumbull%'
      or haystack like '%darien%'
      or haystack like '%new canaan%'
    )
  then
    return 'CONNECTICUT';
  end if;

  return 'UNKNOWN';
end;
$$;


