CREATE OR REPLACE FUNCTION "public"."toh_reservation_start_at_ny"("p_reservation_date" "date", "p_reservation_time" time without time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public'
    AS $$
  select (p_reservation_date + p_reservation_time) at time zone 'America/New_York';
$$;


