CREATE OR REPLACE FUNCTION "public"."track_location_analytics_event"("p_location_id" "uuid", "p_event_name" "text", "p_event_source" "text" DEFAULT NULL::"text", "p_session_id" "text" DEFAULT NULL::"text", "p_search_query" "text" DEFAULT NULL::"text", "p_referrer" "text" DEFAULT NULL::"text", "p_device_type" "text" DEFAULT NULL::"text", "p_browser" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  new_event_id uuid;
  normalized_event_name text;
begin
  if p_location_id is null then
    raise exception 'location_id is required';
  end if;

  if p_event_name is null or trim(p_event_name) = '' then
    raise exception 'event_name is required';
  end if;

  normalized_event_name := lower(trim(p_event_name));

  insert into public.location_analytics_events (
    location_id,
    user_id,
    event_type,
    event_name,
    event_source,
    session_id,
    search_query,
    referrer,
    device_type,
    browser,
    city,
    region,
    metadata,
    created_at
  )
  values (
    p_location_id,
    auth.uid(),
    normalized_event_name,
    normalized_event_name,
    p_event_source,
    p_session_id,
    p_search_query,
    p_referrer,
    p_device_type,
    p_browser,
    p_city,
    p_region,
    coalesce(p_metadata, '{}'::jsonb),
    now()
  )
  returning id into new_event_id;

  return new_event_id;
end;
$$;


