CREATE OR REPLACE FUNCTION "public"."track_mailing_claim_request"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  update public.mailing_batch_items
  set claim_started_at = coalesce(claim_started_at, now()),
      status = case
        when status in ('claimed','returned','cancelled') then status
        else 'claim_started'
      end
  where location_id = new.location_id
    and mailed_at is not null
    and claim_started_at is null;
  return new;
end;
$$;


ALTER FUNCTION "public"."track_mailing_claim_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."track_mailing_location_claimed"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  became_claimed boolean;
begin
  became_claimed :=
    coalesce(new.is_claimed, false)
    or coalesce(new.claimed, false)
    or lower(coalesce(new.claim_status, '')) = 'claimed';

  if became_claimed then
    update public.mailing_batch_items
    set claimed_at = coalesce(claimed_at, now()),
        status = case
          when status in ('returned','cancelled') then status
          else 'claimed'
        end
    where location_id = new.id
      and claimed_at is null
      and (first_scan_at is not null or claim_started_at is not null);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."track_mailing_location_claimed"() OWNER TO "postgres";


