CREATE OR REPLACE FUNCTION "public"."trg_territory_scope_resync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare r record; tid uuid;
begin
  tid := coalesce(new.territory_id, old.territory_id);
  for r in select id from public.locations loop
    if public.crm_location_matches_territory(r.id, tid) then
      perform public.crm_sync_location_territory_assignments(r.id);
    else
      perform public.crm_sync_location_territory_assignments(r.id);
    end if;
  end loop;
  return coalesce(new,old);
end;
$$;


