CREATE OR REPLACE VIEW "public"."admin_beta_overview" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."beta_applications") AS "total_applications",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_applications"
          WHERE ("beta_applications"."status" = 'new'::"text")) AS "new_applications",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_applications"
          WHERE ("beta_applications"."status" = 'approved'::"text")) AS "approved_applications",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_testers") AS "total_testers",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_testers"
          WHERE ("beta_testers"."status" = 'active'::"text")) AS "active_testers",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_feedback") AS "total_feedback",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_feedback"
          WHERE ("beta_feedback"."status" = ANY (ARRAY['new'::"text", 'reviewing'::"text", 'needs_more_info'::"text"]))) AS "open_feedback",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_feedback"
          WHERE ("beta_feedback"."status" = 'fixed'::"text")) AS "fixed_feedback",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_bug_reports") AS "total_bugs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_bug_reports"
          WHERE ("beta_bug_reports"."severity" = 'critical'::"text")) AS "critical_bugs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_bug_reports"
          WHERE ("beta_bug_reports"."status" = ANY (ARRAY['new'::"text", 'confirmed'::"text", 'in_progress'::"text"]))) AS "open_bugs",
    ( SELECT "avg"("search_performance_logs"."total_ms") AS "avg"
           FROM "public"."search_performance_logs"
          WHERE ("search_performance_logs"."created_at" > ("now"() - '24:00:00'::interval))) AS "avg_search_ms_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."search_performance_logs"
          WHERE (("search_performance_logs"."created_at" > ("now"() - '24:00:00'::interval)) AND ("search_performance_logs"."speed_status" = ANY (ARRAY['slow'::"text", 'critical'::"text"])))) AS "slow_searches_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."search_performance_logs"
          WHERE (("search_performance_logs"."created_at" > ("now"() - '24:00:00'::interval)) AND ("search_performance_logs"."speed_status" = ANY (ARRAY['failed'::"text", 'timeout'::"text"])))) AS "failed_searches_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."search_performance_logs"
          WHERE ("search_performance_logs"."created_at" > ("now"() - '24:00:00'::interval))) AS "search_count_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."search_performance_logs"
          WHERE (("search_performance_logs"."created_at" > ("now"() - '24:00:00'::interval)) AND "search_performance_logs"."used_custom_prompt")) AS "custom_prompt_searches_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."turnstile_verification_logs"
          WHERE (("turnstile_verification_logs"."created_at" > ("now"() - '24:00:00'::interval)) AND (NOT "turnstile_verification_logs"."success"))) AS "turnstile_failures_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_email_reminders"
          WHERE (("beta_email_reminders"."created_at" > "date_trunc"('week'::"text", "now"())) AND ("beta_email_reminders"."status" = 'sent'::"text"))) AS "reminder_emails_sent_week",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_email_reminders"
          WHERE (("beta_email_reminders"."created_at" > "date_trunc"('week'::"text", "now"())) AND ("beta_email_reminders"."status" = 'failed'::"text"))) AS "reminder_emails_failed_week",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_testers"
          WHERE (("beta_testers"."status" = 'active'::"text") AND ("beta_testers"."weekly_completed_tests" < "beta_testers"."weekly_required_tests"))) AS "testers_with_incomplete_weekly_tasks",
    ( SELECT "count"(*) AS "count"
           FROM "public"."beta_testers"
          WHERE (("beta_testers"."status" = 'active'::"text") AND ("beta_testers"."weekly_completed_tests" >= 5))) AS "testers_completed_5_of_5";


ALTER VIEW "public"."admin_beta_overview" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."admin_beta_slowest_searches" WITH ("security_invoker"='true') AS
 SELECT "id",
    "created_at",
    "source",
    "route",
    "search_query",
    "beta_assignment_id",
    "beta_tester_id",
    "used_custom_prompt",
    "total_ms",
    "llm_ms",
    "rpc_ms",
    "pairing_ms",
    "photo_filter_ms",
    "result_count",
    "restaurant_count",
    "activity_count",
    "pair_count",
    "speed_status",
    "success",
    "error_message"
   FROM "public"."search_performance_logs"
  WHERE ("speed_status" = ANY (ARRAY['slow'::"text", 'critical'::"text", 'failed'::"text", 'timeout'::"text"]))
  ORDER BY "created_at" DESC
 LIMIT 200;


ALTER VIEW "public"."admin_beta_slowest_searches" OWNER TO "postgres";


