CREATE OR REPLACE VIEW "public"."admin_crm_locations_view" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."id" AS "location_id",
    COALESCE(NULLIF("l"."name", ''::"text"), NULLIF("l"."restaurant_name", ''::"text"), NULLIF("l"."activity_name", ''::"text"), 'Untitled Location'::"text") AS "name",
    COALESCE(NULLIF("l"."name", ''::"text"), NULLIF("l"."restaurant_name", ''::"text"), NULLIF("l"."activity_name", ''::"text"), 'Untitled Location'::"text") AS "location_name",
    "l"."restaurant_name",
    "l"."activity_name",
    "l"."location_type",
    "l"."address",
    "l"."city",
    COALESCE(NULLIF("l"."borough", ''::"text"), NULLIF("l"."neighborhood", ''::"text"), "l"."city") AS "borough",
    "l"."neighborhood",
    "l"."state",
    "l"."zip_code",
    "l"."latitude",
    "l"."longitude",
    "l"."phone",
    "l"."website",
    "l"."google_maps_url",
    "l"."reservation_url",
    "l"."reservation_link",
    "l"."booking_url",
    "l"."external_reservation_url",
    COALESCE(NULLIF("l"."reservation_url", ''::"text"), NULLIF("l"."reservation_link", ''::"text"), NULLIF("l"."booking_url", ''::"text"), NULLIF("l"."external_reservation_url", ''::"text")) AS "best_reservation_url",
    "l"."image_url",
    "l"."main_image",
    "l"."images",
    "l"."gallery_images",
    "l"."rating",
    "l"."review_count",
    "l"."review_score",
    "l"."quality_score",
    "l"."popularity_score",
    "l"."roseout_score",
    "l"."theouthaven_score",
    "l"."search_score",
    "l"."recommendation_score",
    "l"."analytics_score",
    "l"."primary_category" AS "category",
    "l"."primary_category",
    "l"."cuisine",
    "l"."cuisine_type",
    "l"."activity_type",
    "l"."atmosphere",
    "l"."price_range",
    "l"."primary_tag",
    "l"."tags",
    "l"."vibe_tags",
    "l"."best_for_tags",
    "l"."date_style_tags",
    "l"."search_keywords",
    "l"."best_for",
    "l"."special_features",
    "l"."signature_items",
    "l"."google_types",
    "l"."description",
    "l"."is_searchable",
    "l"."active",
    "l"."is_hidden",
    "l"."data_status",
    "l"."status",
    "l"."crm_status",
    "l"."outreach_status",
    "l"."outreach_notes",
    "l"."crm_priority",
    "l"."priority_level",
    "l"."follow_up_date",
    "l"."last_contacted_at",
    "l"."internal_notes",
    "l"."plan",
    "l"."plan_status",
    "l"."subscription_plan",
    "l"."subscription_status",
    "l"."current_period_end",
    "l"."trial_ends_at",
    "l"."is_pro",
    "l"."pro_until",
    "l"."upgrade_score",
    "l"."churn_risk",
    COALESCE("l"."opportunity_score", "l"."upgrade_score", (0)::numeric) AS "opportunity_score",
    COALESCE("l"."churn_risk_score", "l"."churn_risk", (0)::numeric) AS "churn_risk_score",
    COALESCE("l"."upgrade_probability", (0)::numeric) AS "upgrade_probability",
    COALESCE("l"."engagement_score", (0)::numeric) AS "engagement_score",
    COALESCE("l"."traffic_score", (0)::numeric) AS "traffic_score",
    COALESCE("l"."conversion_score", (0)::numeric) AS "conversion_score",
    COALESCE("l"."retention_score", (0)::numeric) AS "retention_score",
    COALESCE("l"."trend_score", (0)::numeric) AS "trending_score",
    "l"."retention_recommendation",
    COALESCE("analytics"."profile_views_30d", (0)::bigint) AS "profile_views_30d",
    COALESCE("analytics"."search_appearances_30d", (0)::bigint) AS "search_appearances_30d",
    COALESCE("analytics"."reservation_completions_30d", (0)::bigint) AS "reservation_completions_30d",
    COALESCE("analytics"."saves_30d", (0)::bigint) AS "saves_30d",
    COALESCE("analytics"."conversion_rate_30d", (0)::numeric) AS "conversion_rate_30d",
    "l"."owner_email",
    "l"."owner_user_id",
    "l"."owner_name",
    "l"."owner_phone",
    "l"."is_claimed",
    "l"."is_verified",
    "l"."claim_status",
    "l"."claim_verification_status",
    "l"."claimed_by",
    "l"."claimed_by_email",
    "l"."claimed_at",
    "l"."claim_code",
    "l"."claim_token",
    "l"."claim_url",
    "l"."claim_qr_url",
    "l"."qr_link",
    "l"."qr_code_data_url",
    "l"."reservation_enabled",
    "l"."uses_internal_reservations",
    "l"."internal_reservations_enabled",
    "l"."reservation_source",
    "l"."reservation_type",
    "l"."reservation_settings",
    "l"."reservation_embed_enabled",
    "l"."reservation_layout",
    "l"."reservation_embed_settings",
    "l"."max_party_size",
    "l"."reservation_interval_minutes",
    "l"."turn_time_minutes",
    "l"."booking_cutoff_minutes",
    "l"."cancellation_policy",
    "l"."operating_hours",
    "l"."special_hours",
    "l"."holiday_closures",
    "l"."reservation_upgrade_opportunity",
    "l"."reservation_upgrade_reason",
    "l"."reservation_upgrade_detected_at",
    "l"."reservation_outreach_status",
    "l"."reservation_outreach_notes",
    "l"."is_featured",
    "l"."is_promoted",
    "l"."promotion_tier",
    "l"."promotion_starts_at",
    "l"."promotion_ends_at",
    "l"."promotion_budget",
    "l"."deposits_enabled",
    "l"."default_deposit_amount",
    "l"."deposit_type",
    "l"."promo_code",
    "l"."promo_code_used",
    "l"."promo_campaign",
    "l"."billing_notes",
    "l"."stripe_customer_id",
    "l"."stripe_subscription_id",
    "l"."source_table",
    "l"."source_id",
    "l"."google_place_id",
    "l"."ranking_badge",
    "l"."created_at",
    "l"."updated_at",
    "l"."deleted_at"
   FROM ("public"."locations" "l"
     LEFT JOIN ( SELECT "lda"."location_id",
            "sum"(COALESCE("lda"."profile_views", 0)) AS "profile_views_30d",
            "sum"(COALESCE("lda"."search_appearances", 0)) AS "search_appearances_30d",
            "sum"(COALESCE("lda"."reservation_completions", 0)) AS "reservation_completions_30d",
            "sum"(COALESCE("lda"."share_clicks", 0)) AS "saves_30d",
                CASE
                    WHEN ("sum"(COALESCE("lda"."profile_views", 0)) > 0) THEN (("sum"(COALESCE("lda"."reservation_completions", 0)))::numeric / ("sum"(COALESCE("lda"."profile_views", 0)))::numeric)
                    ELSE (0)::numeric
                END AS "conversion_rate_30d"
           FROM "public"."location_daily_analytics" "lda"
          WHERE ("lda"."analytics_date" >= (CURRENT_DATE - '30 days'::interval))
          GROUP BY "lda"."location_id") "analytics" ON (("analytics"."location_id" = "l"."id")))
  WHERE (COALESCE("l"."deleted_at", NULL::timestamp with time zone) IS NULL);


