    "expires_at" timestamp with time zone NOT NULL,
    "used_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "ip_address" "inet",
    "user_agent" "text",
    CONSTRAINT "auth_email_tokens_email_not_blank" CHECK (("length"(TRIM(BOTH FROM "email")) > 0)),
    CONSTRAINT "auth_email_tokens_expires_after_created" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "auth_email_tokens_token_hash_not_blank" CHECK (("length"(TRIM(BOTH FROM "token_hash")) > 0)),
    CONSTRAINT "auth_email_tokens_valid_purpose" CHECK (("purpose" = ANY (ARRAY['signup_verify'::"text", 'password_reset'::"text", 'password_setup'::"text"])))
);


ALTER TABLE "public"."auth_email_tokens" OWNER TO "postgres";


COMMENT ON TABLE "public"."auth_email_tokens" IS 'Stores hashed, single-use, expiring tokens for custom TheOutHaven auth emails. Raw tokens are never stored.';



COMMENT ON COLUMN "public"."auth_email_tokens"."token_hash" IS 'Hash of the raw email token. The raw token is only sent in the email URL and never stored.';



COMMENT ON COLUMN "public"."auth_email_tokens"."purpose" IS 'Token purpose allowlist: signup_verify, password_reset, password_setup.';



COMMENT ON COLUMN "public"."auth_email_tokens"."metadata" IS 'Optional server-controlled context such as redirect path or source flow. Do not store secrets here.';



