CREATE OR REPLACE VIEW "public"."business_crm_snapshot" WITH ("security_invoker"='true') AS
 WITH "analytics" AS (
         SELECT "lda"."location_id",
            "sum"(COALESCE("lda"."profile_views", 0)) AS "profile_views_30d",
            "sum"(COALESCE("lda"."search_appearances", 0)) AS "search_appearances_30d",
            "sum"(COALESCE("lda"."share_clicks", 0)) AS "saves_30d",
            "sum"(COALESCE("lda"."reservation_completions", 0)) AS "reservation_completions_30d",
                CASE
                    WHEN ("sum"(COALESCE("lda"."profile_views", 0)) > 0) THEN (("sum"(COALESCE("lda"."reservation_completions", 0)))::numeric / ("sum"(COALESCE("lda"."profile_views", 0)))::numeric)
                    ELSE (0)::numeric
                END AS "conversion_rate_30d"
           FROM "public"."location_daily_analytics" "lda"
          WHERE ("lda"."analytics_date" >= (CURRENT_DATE - '30 days'::interval))
          GROUP BY "lda"."location_id"
        )
 SELECT "l"."id" AS "location_id",
    "l"."id",
    COALESCE("l"."name", "l"."restaurant_name", "l"."activity_name", 'Untitled Location'::"text") AS "location_name",
    COALESCE("l"."name", "l"."restaurant_name", "l"."activity_name", 'Untitled Location'::"text") AS "name",
    "l"."city",
    COALESCE("l"."borough", "l"."neighborhood", "l"."city") AS "borough",
    "l"."state",
    "l"."zip_code",
    "l"."zip_code" AS "zip",
    "l"."address",
    "l"."phone",
    "l"."website",
    "l"."primary_category" AS "category",
    COALESCE("l"."cuisine", "l"."cuisine_type") AS "cuisine",
    "l"."description",
    "l"."status",
    "l"."is_searchable",
    "l"."is_claimed",
    COALESCE("l"."reservation_url", "l"."reservation_link", "l"."booking_url", "l"."external_reservation_url") AS "reservation_url",
    "l"."external_reservation_url",
    "l"."location_type",
    "l"."owner_user_id",
    "l"."crm_status",
    "l"."opportunity_score",
    "l"."upgrade_probability",
    "l"."engagement_score",
    "l"."traffic_score",
    "l"."conversion_score",
    "l"."retention_score",
    "l"."churn_risk_score",
    COALESCE("l"."trend_score", "l"."theouthaven_score", "l"."roseout_score", (0)::numeric) AS "trending_score",
    COALESCE("analytics"."profile_views_30d", (0)::bigint) AS "profile_views_30d",
    COALESCE("analytics"."search_appearances_30d", (0)::bigint) AS "search_appearances_30d",
    COALESCE("analytics"."saves_30d", (0)::bigint) AS "saves_30d",
    COALESCE("analytics"."reservation_completions_30d", (0)::bigint) AS "reservation_completions_30d",
    COALESCE("analytics"."conversion_rate_30d", (0)::numeric) AS "conversion_rate_30d",
    "l"."follow_up_date",
    "l"."outreach_status",
    "l"."last_contacted_at",
    "l"."outreach_notes",
    "l"."retention_recommendation",
    NULL::"text" AS "priority_level",
    NULL::"text" AS "internal_notes",
    "l"."created_at",
    "l"."updated_at"
   FROM ("public"."locations" "l"
     LEFT JOIN "analytics" ON (("analytics"."location_id" = "l"."id")))
  WHERE (("l"."owner_user_id" = ( SELECT "auth"."uid"() AS "uid")) OR ("public"."current_admin_role"() = ANY (ARRAY['superadmin'::"text", 'admin'::"text", 'editor'::"text", 'reviewer'::"text", 'viewer'::"text"])));


ALTER VIEW "public"."business_crm_snapshot" OWNER TO "postgres";


