CREATE OR REPLACE VIEW "public"."crm_location_territories" WITH ("security_invoker"='true') AS
 SELECT "l"."id" AS "location_id",
    "l"."name" AS "location_name",
    "l"."neighborhood",
    "l"."neighborhood_nta_code",
    "l"."borough",
    "t"."id" AS "territory_id",
    "t"."name" AS "territory_name",
    "t"."owner_user_id"
   FROM (("public"."locations" "l"
     LEFT JOIN "public"."crm_territory_neighborhoods" "tn" ON (("tn"."nta_code" = "l"."neighborhood_nta_code")))
     LEFT JOIN "public"."crm_territories" "t" ON ((("t"."id" = "tn"."territory_id") AND ("t"."status" = 'active'::"text"))));


