    CONSTRAINT "crm_tasks_check1" CHECK (((("status" = 'completed'::"text") AND ("completed_at" IS NOT NULL)) OR (("status" <> 'completed'::"text") AND ("completed_at" IS NULL)))),
    CONSTRAINT "crm_tasks_escalation_check" CHECK (("escalation_level" = ANY (ARRAY['none'::"text", 'attention'::"text", 'manager'::"text", 'critical'::"text"]))),
