    CONSTRAINT "crm_tasks_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'blocked'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "crm_tasks_task_type_check" CHECK (("task_type" = ANY (ARRAY['follow_up'::"text", 'outreach'::"text", 'claim_review'::"text", 'onboarding'::"text", 'support'::"text", 'billing'::"text", 'reservation'::"text", 'site_visit'::"text", 'data_correction'::"text", 'profile_review'::"text", 'renewal'::"text", 'sales'::"text", 'internal'::"text", 'other'::"text"]))),
    CONSTRAINT "crm_tasks_title_check" CHECK (("btrim"("title") <> ''::"text")),
    CONSTRAINT "crm_tasks_version_check" CHECK (("version" > 0))
);


