    CONSTRAINT "events_platform_fee_bps_check" CHECK ((("platform_fee_bps" >= 0) AND ("platform_fee_bps" <= 2500))),
    CONSTRAINT "events_price_max_check" CHECK ((("price_max" IS NULL) OR ("price_max" >= (0)::numeric))),
    CONSTRAINT "events_price_min_check" CHECK ((("price_min" IS NULL) OR ("price_min" >= (0)::numeric))),
    CONSTRAINT "events_price_order_check" CHECK ((("price_min" IS NULL) OR ("price_max" IS NULL) OR ("price_max" >= "price_min"))),
    CONSTRAINT "events_source_kind_check" CHECK (("source_kind" = ANY (ARRAY['provider'::"text", 'native'::"text"]))),
    CONSTRAINT "events_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'scheduled'::"text", 'postponed'::"text", 'cancelled'::"text", 'completed'::"text"]))),
    CONSTRAINT "events_title_not_blank" CHECK (("length"(TRIM(BOTH FROM "title")) > 0))
);


