    CONSTRAINT "experiences_seats_per_table_check" CHECK ((("seats_per_table" IS NULL) OR ("seats_per_table" > 0))),
    CONSTRAINT "experiences_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'paused'::"text", 'archived'::"text"])))
);


