CREATE OR REPLACE VIEW "public"."location_photo_health" WITH ("security_invoker"='true') AS
 SELECT "id",
    COALESCE(NULLIF("name", ''::"text"), NULLIF("restaurant_name", ''::"text"), NULLIF("activity_name", ''::"text"), 'TheOutHaven location'::"text") AS "location_name",
    "claim_status",
    "claimed_at",
    "owner_user_id",
    "owner_photo_count",
    "has_owner_photos",
    "profile_completion_score",
    "profile_completion_status",
    "photo_nudge_status",
    "last_photo_nudge_at",
    "photo_source",
    "google_place_id",
        CASE
            WHEN (COALESCE("owner_photo_count", 0) >= 5) THEN 'gallery_complete'::"text"
            WHEN (COALESCE("owner_photo_count", 0) >= 3) THEN 'photo_ready'::"text"
            WHEN (COALESCE("owner_photo_count", 0) >= 1) THEN 'getting_started'::"text"
            WHEN ("google_place_id" IS NOT NULL) THEN 'using_google_fallback'::"text"
            ELSE 'missing_owner_photos'::"text"
        END AS "photo_health_status"
   FROM "public"."locations" "l"
  WHERE (COALESCE("is_claimed", false) OR ("owner_user_id" IS NOT NULL) OR ("claim_status" = ANY (ARRAY['approved'::"text", 'claimed'::"text", 'redeemed'::"text"])));


