CREATE OR REPLACE VIEW "public"."location_publishability_audit" WITH ("security_invoker"='true') AS
 SELECT "id",
    "name",
    "restaurant_name",
    "activity_name",
    "business_name",
    "location_type",
    "address",
    "formatted_address",
    "city",
    "borough",
    "neighborhood",
    "state",
    "postal_code",
    "latitude",
    "longitude",
    "google_place_id",
    "is_searchable",
    "publish_ready",
    "data_status",
    "quality_status",
    "source_quality_status",
    "import_confidence",
    "public_visibility_tier",
    "duplicate_status",
    "is_hidden",
    "is_low_level",
    "has_photos",
    "photo_status",
    "main_image",
    "image_url",
    "images",
    "status",
    "updated_at",
    (COALESCE("name", "restaurant_name", "activity_name", "business_name", ''::"text") = ''::"text") AS "missing_name",
    (COALESCE("address", "formatted_address", ''::"text") = ''::"text") AS "missing_address",
    (("latitude" IS NULL) OR ("longitude" IS NULL)) AS "missing_coordinates",
    (COALESCE("google_place_id", ''::"text") = ''::"text") AS "missing_google_place_id",
    ((COALESCE("has_photos", false) = false) OR ((COALESCE("main_image", "image_url", ''::"text") = ''::"text") AND (COALESCE("array_length"("images", 1), 0) = 0))) AS "missing_photo",
    (COALESCE("duplicate_status", 'unknown'::"text") = 'duplicate'::"text") AS "is_duplicate",
    (COALESCE("is_hidden", false) OR COALESCE("is_low_level", false) OR (COALESCE("public_visibility_tier", 'standard'::"text") = ANY (ARRAY['hidden'::"text", 'low_level'::"text", 'internal'::"text", 'pending_review'::"text", 'rejected'::"text"])) OR (COALESCE("source_quality_status", ''::"text") = ANY (ARRAY['low_level_review'::"text", 'imported_unverified'::"text"])) OR (COALESCE("import_confidence", ''::"text") = 'low'::"text") OR (COALESCE("status", 'approved'::"text") = ANY (ARRAY['closed'::"text", 'archived'::"text", 'rejected'::"text"]))) AS "blocked_by_quality",
    ("location_type" <> ALL (ARRAY['restaurant'::"text", 'activity'::"text"])) AS "invalid_location_type",
    ((COALESCE("name", "restaurant_name", "activity_name", "business_name", ''::"text") <> ''::"text") AND (COALESCE("address", "formatted_address", ''::"text") <> ''::"text") AND ("latitude" IS NOT NULL) AND ("longitude" IS NOT NULL) AND ("location_type" = ANY (ARRAY['restaurant'::"text", 'activity'::"text"])) AND COALESCE("has_photos", false) AND ((COALESCE("main_image", "image_url", ''::"text") <> ''::"text") OR (COALESCE("array_length"("images", 1), 0) > 0)) AND (COALESCE("duplicate_status", 'unknown'::"text") <> 'duplicate'::"text") AND (COALESCE("is_hidden", false) = false) AND (COALESCE("is_low_level", false) = false) AND (COALESCE("public_visibility_tier", 'standard'::"text") = 'standard'::"text") AND (COALESCE("source_quality_status", ''::"text") <> ALL (ARRAY['low_level_review'::"text", 'imported_unverified'::"text"])) AND (COALESCE("import_confidence", ''::"text") <> 'low'::"text") AND (COALESCE("status", 'approved'::"text") <> ALL (ARRAY['closed'::"text", 'archived'::"text", 'rejected'::"text"]))) AS "ready_to_approve",
        CASE
            WHEN (COALESCE("name", "restaurant_name", "activity_name", "business_name", ''::"text") = ''::"text") THEN 'missing_name'::"text"
            WHEN (COALESCE("address", "formatted_address", ''::"text") = ''::"text") THEN 'missing_address'::"text"
            WHEN (("latitude" IS NULL) OR ("longitude" IS NULL)) THEN 'missing_coordinates'::"text"
            WHEN ("location_type" <> ALL (ARRAY['restaurant'::"text", 'activity'::"text"])) THEN 'invalid_location_type'::"text"
            WHEN (COALESCE("duplicate_status", 'unknown'::"text") = 'duplicate'::"text") THEN 'duplicate'::"text"
            WHEN ((COALESCE("has_photos", false) = false) OR ((COALESCE("main_image", "image_url", ''::"text") = ''::"text") AND (COALESCE("array_length"("images", 1), 0) = 0))) THEN 'missing_photo'::"text"
            WHEN COALESCE("is_hidden", false) THEN 'hidden'::"text"
            WHEN COALESCE("is_low_level", false) THEN 'low_level'::"text"
            WHEN (COALESCE("public_visibility_tier", 'standard'::"text") <> 'standard'::"text") THEN ('visibility_tier_'::"text" || COALESCE("public_visibility_tier", 'unknown'::"text"))
            WHEN (COALESCE("source_quality_status", ''::"text") = ANY (ARRAY['low_level_review'::"text", 'imported_unverified'::"text"])) THEN ('source_quality_'::"text" || "source_quality_status")
            WHEN (COALESCE("import_confidence", ''::"text") = 'low'::"text") THEN 'low_import_confidence'::"text"
            WHEN (COALESCE("status", 'approved'::"text") = ANY (ARRAY['closed'::"text", 'archived'::"text", 'rejected'::"text"])) THEN ('status_'::"text" || COALESCE("status", 'unknown'::"text"))
            ELSE 'ready'::"text"
        END AS "not_searchable_reason"
   FROM "public"."locations" "l"
  WHERE ("public"."current_admin_role"() = ANY (ARRAY['superadmin'::"text", 'admin'::"text", 'editor'::"text", 'reviewer'::"text", 'viewer'::"text"]));


ALTER VIEW "public"."location_publishability_audit" OWNER TO "postgres";


COMMENT ON VIEW "public"."location_publishability_audit" IS 'Admin review view showing why a location is not searchable and whether it is safe to approve.';



