CREATE OR REPLACE VIEW "public"."mailing_batch_summary" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"text" AS "name",
    NULL::"text" AS "status",
    NULL::"date" AS "planned_mail_date",
    NULL::timestamp with time zone AS "mailed_at",
    NULL::timestamp with time zone AS "completed_at",
    NULL::"text" AS "notes",
    NULL::"uuid" AS "created_by",
    NULL::timestamp with time zone AS "created_at",
    NULL::timestamp with time zone AS "updated_at",
    NULL::bigint AS "item_count",
    NULL::bigint AS "printed_count",
