    CONSTRAINT "outings_created_by_type_check" CHECK (("created_by_type" = ANY (ARRAY['guest'::"text", 'user'::"text", 'admin'::"text", 'ambassador'::"text"]))),
    CONSTRAINT "outings_external_booking_counts_check" CHECK ((("external_bookings_required_count" >= 0) AND ("external_bookings_confirmed_count" >= 0) AND ("external_bookings_confirmed_count" <= "external_bookings_required_count"))),
    CONSTRAINT "outings_external_booking_status_check" CHECK ((("external_booking_status" IS NULL) OR ("external_booking_status" = ANY (ARRAY['available'::"text", 'started'::"text", 'confirmed'::"text", 'failed'::"text", 'abandoned'::"text"])))),
    CONSTRAINT "outings_guest_requires_plan_token_check" CHECK ((("created_by_type" <> 'guest'::"text") OR ("plan_access_token" IS NOT NULL))),
    CONSTRAINT "outings_planned_time_consistency_check" CHECK (((("outing_time_confidence" = 'exact'::"text") AND ("planned_for" IS NOT NULL)) OR (("outing_time_confidence" = ANY (ARRAY['none'::"text", 'date_only'::"text"])) AND ("planned_for" IS NULL)) OR ("outing_time_confidence" IS NULL))),
    CONSTRAINT "outings_reminders_require_planned_for_check" CHECK ((("reminders_enabled" = false) OR ("planned_for" IS NOT NULL))),
    CONSTRAINT "outings_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'saved'::"text", 'reservation_clicked'::"text", 'call_clicked'::"text", 'link_clicked'::"text", 'reminder_scheduled'::"text", 'reminder_sent'::"text", 'feedback_requested'::"text", 'completed'::"text", 'completed_no_feedback'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "outings_time_confidence_check" CHECK ((("outing_time_confidence" = ANY (ARRAY['none'::"text", 'date_only'::"text", 'exact'::"text"])) OR ("outing_time_confidence" IS NULL))),
    CONSTRAINT "outings_visit_verification_level_check" CHECK ((("visit_verification_level" = ANY (ARRAY['planned'::"text", 'intent_confirmed'::"text", 'likely_visited'::"text", 'verified_visited'::"text"])) OR ("visit_verification_level" IS NULL))),
    CONSTRAINT "outings_visit_verification_source_check" CHECK ((("visit_verification_source" = ANY (ARRAY['internal_reservation'::"text", 'check_in'::"text", 'admin'::"text", 'ambassador'::"text", 'guest_self_confirmed'::"text", 'user_self_confirmed'::"text", 'external_clicks'::"text"])) OR ("visit_verification_source" IS NULL)))
);


