CREATE TABLE IF NOT EXISTS "public"."promo_codes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "name" "text",
    "description" "text",
    "audience" "text" DEFAULT 'users'::"text" NOT NULL,
    "promo_type" "text" DEFAULT 'premium_access'::"text" NOT NULL,
    "plan_granted" "text",
    "duration_days" integer,
    "search_limit_override" integer,
    "discount_percent" numeric,
    "discount_amount" numeric,
    "max_redemptions" integer,
    "redemption_count" integer DEFAULT 0 NOT NULL,
    "max_redemptions_per_user" integer DEFAULT 1 NOT NULL,
    "starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "target_scope" "text" DEFAULT 'any'::"text" NOT NULL,
    "assigned_user_id" "uuid",
    "assigned_location_id" "uuid",
    "assigned_location_name" "text",
    "signup_context" "text",
    "auto_generated" boolean DEFAULT false NOT NULL,
    "internal_notes" "text",
    CONSTRAINT "promo_codes_audience_check" CHECK (("audience" = ANY (ARRAY['users'::"text", 'locations'::"text", 'both'::"text"]))),
    CONSTRAINT "promo_codes_promo_type_check" CHECK (("promo_type" = ANY (ARRAY['premium_access'::"text", 'search_boost'::"text", 'location_pro_trial'::"text", 'discount'::"text"]))),
    CONSTRAINT "promo_codes_signup_context_check" CHECK ((("signup_context" IS NULL) OR ("signup_context" = ANY (ARRAY['user_signup'::"text", 'location_owner_signup'::"text", 'both_signups'::"text"])))),
    CONSTRAINT "promo_codes_target_scope_check" CHECK (("target_scope" = ANY (ARRAY['any'::"text", 'specific_user'::"text", 'specific_location'::"text", 'signup_user'::"text", 'signup_location_owner'::"text"])))
);


ALTER TABLE "public"."promo_codes" OWNER TO "postgres";


