CREATE TABLE IF NOT EXISTS "public"."reservation_sms_learned_rules" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "learning_cue" "text" NOT NULL,
    "intent" "text" NOT NULL,
    "field_type" "text" NOT NULL,
    "status" "text" DEFAULT 'candidate'::"text" NOT NULL,
    "occurrence_count" integer DEFAULT 0 NOT NULL,
    "confirmed_count" integer DEFAULT 0 NOT NULL,
    "consistency_rate" numeric(5,4) DEFAULT 0 NOT NULL,
    "average_confidence" numeric(5,4) DEFAULT 0 NOT NULL,
    "promoted_at" timestamp with time zone,
    "demoted_at" timestamp with time zone,
    "last_seen_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reservation_sms_learned_rules_field_type_check" CHECK (("field_type" = ANY (ARRAY['time'::"text", 'date'::"text", 'party'::"text"]))),
    CONSTRAINT "reservation_sms_learned_rules_intent_check" CHECK (("intent" = ANY (ARRAY['change_time'::"text", 'change_date'::"text", 'change_party'::"text"]))),
    CONSTRAINT "reservation_sms_learned_rules_status_check" CHECK (("status" = ANY (ARRAY['candidate'::"text", 'active'::"text", 'disabled'::"text"])))
);


ALTER TABLE "public"."reservation_sms_learned_rules" OWNER TO "postgres";


COMMENT ON TABLE "public"."reservation_sms_learned_rules" IS 'Server-only deterministic reservation SMS phrase cues promoted automatically after repeated consistent confirmed outcomes.';



CREATE TABLE IF NOT EXISTS "public"."reservation_sms_phrase_observations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "raw_text" "text" NOT NULL,
    "normalized_text" "text" NOT NULL,
    "learning_cue" "text" NOT NULL,
    "intent" "text" NOT NULL,
    "field_type" "text" NOT NULL,
    "confidence" numeric(5,4) NOT NULL,
    "source" "text" DEFAULT 'ai'::"text" NOT NULL,
    "outcome" "text" DEFAULT 'pending'::"text" NOT NULL,
    "matched_reservation_id" "uuid",
    "matched_message_id" "uuid",
    "confirmed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "reservation_sms_phrase_observations_confidence_check" CHECK ((("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric))),
    CONSTRAINT "reservation_sms_phrase_observations_field_type_check" CHECK (("field_type" = ANY (ARRAY['time'::"text", 'date'::"text", 'party'::"text"]))),
    CONSTRAINT "reservation_sms_phrase_observations_intent_check" CHECK (("intent" = ANY (ARRAY['change_time'::"text", 'change_date'::"text", 'change_party'::"text"]))),
    CONSTRAINT "reservation_sms_phrase_observations_outcome_check" CHECK (("outcome" = ANY (ARRAY['pending'::"text", 'confirmed'::"text", 'unconfirmed'::"text"]))),
    CONSTRAINT "reservation_sms_phrase_observations_source_check" CHECK (("source" = ANY (ARRAY['ai'::"text", 'learned'::"text"])))
);


ALTER TABLE "public"."reservation_sms_phrase_observations" OWNER TO "postgres";


COMMENT ON TABLE "public"."reservation_sms_phrase_observations" IS 'Server-only observations of AI and learned-rule reservation SMS interpretations used for guarded automatic phrase learning.';



