    "sum"("impression_count") AS "impressions",
    "sum"("click_count") AS "clicks",
    "sum"("profile_open_count") AS "profile_opens",
    "sum"("save_count") AS "saves",
    "sum"("booking_action_count") AS "booking_actions",
    "sum"("call_count") AS "calls",
    "sum"("directions_count") AS "directions",
    "sum"("share_count") AS "shares",
    "sum"("abandonment_count") AS "abandonments",
    "sum"("query_reformulation_count") AS "query_reformulations"
   FROM "public"."search_outcome_aggregates"
