CREATE OR REPLACE VIEW "public"."search_profile_refresh_queue_health" WITH ("security_invoker"='true') AS
 SELECT "count"(*) FILTER (WHERE ("status" = 'pending'::"text")) AS "pending_count",
    "count"(*) FILTER (WHERE ("status" = 'processing'::"text")) AS "processing_count",
    "count"(*) FILTER (WHERE ("status" = 'succeeded'::"text")) AS "succeeded_count",
    "count"(*) FILTER (WHERE ("status" = 'failed'::"text")) AS "failed_count",
    "count"(*) FILTER (WHERE (("status" = 'pending'::"text") AND ("attempts" = 0) AND ("available_at" < ("now"() - '00:10:00'::interval)))) AS "stalled_unattempted_count",
    "min"("created_at") FILTER (WHERE ("status" = 'pending'::"text")) AS "oldest_pending_created_at",
    "max"("updated_at") AS "latest_queue_update"
   FROM "public"."location_search_profile_refresh_queue";


