CREATE OR REPLACE VIEW "public"."search_ranking_guardrail_health_v1" WITH ("security_invoker"='true') AS
 WITH "settings" AS (
         SELECT "search_ranking_guardrail_settings"."id",
            "search_ranking_guardrail_settings"."enabled",
            "search_ranking_guardrail_settings"."evaluation_window_minutes",
            "search_ranking_guardrail_settings"."minimum_sample_size",
            "search_ranking_guardrail_settings"."max_no_result_rate_delta",
            "search_ranking_guardrail_settings"."max_p95_latency_ms",
            "search_ranking_guardrail_settings"."max_pair_count_drop",
            "search_ranking_guardrail_settings"."updated_by",
            "search_ranking_guardrail_settings"."updated_at"
           FROM "public"."search_ranking_guardrail_settings"
          WHERE ("search_ranking_guardrail_settings"."id" = true)
        ), "metrics" AS (
         SELECT "search_ranking_experiments"."variant",
            ("count"(*))::integer AS "sample_size",
            ("avg"(("search_ranking_experiments"."no_results")::integer))::numeric(8,4) AS "no_result_rate",
            "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("search_ranking_experiments"."latency_ms")::double precision)) AS "p95_latency_ms",
            ("avg"("search_ranking_experiments"."pair_count"))::numeric(12,2) AS "avg_pair_count"
           FROM "public"."search_ranking_experiments",
            "settings" "settings_1"
          WHERE (("search_ranking_experiments"."created_at" >= ("now"() - "make_interval"("mins" => "settings_1"."evaluation_window_minutes"))) AND (COALESCE((("search_ranking_experiments"."metadata" ->> 'test_mode'::"text"))::boolean, false) = false))
          GROUP BY "search_ranking_experiments"."variant"
        )
 SELECT "settings"."enabled",
    "settings"."evaluation_window_minutes",
    "settings"."minimum_sample_size",
    "settings"."max_no_result_rate_delta",
    "settings"."max_p95_latency_ms",
    "settings"."max_pair_count_drop",
    COALESCE("control"."sample_size", 0) AS "control_sample_size",
    COALESCE("hybrid"."sample_size", 0) AS "hybrid_sample_size",
    "control"."no_result_rate" AS "control_no_result_rate",
    "hybrid"."no_result_rate" AS "hybrid_no_result_rate",
    "control"."p95_latency_ms" AS "control_p95_latency_ms",
    "hybrid"."p95_latency_ms" AS "hybrid_p95_latency_ms",
    "control"."avg_pair_count" AS "control_avg_pair_count",
    "hybrid"."avg_pair_count" AS "hybrid_avg_pair_count"
   FROM (("settings"
     LEFT JOIN "metrics" "control" ON (("control"."variant" = 'control'::"text")))
     LEFT JOIN "metrics" "hybrid" ON (("hybrid"."variant" = 'hybrid'::"text")));


ALTER VIEW "public"."search_ranking_guardrail_health_v1" OWNER TO "postgres";


