CREATE OR REPLACE VIEW "public"."search_ranking_shadow_validation_v2" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "shadow_searches",
    ("count"(*) FILTER (WHERE ("lower"(COALESCE(("e"."metadata" ->> 'test_mode'::"text"), 'false'::"text")) = ANY (ARRAY['true'::"text", '1'::"text", 'yes'::"text", 'on'::"text"]))))::integer AS "test_mode_searches",
    ("count"(*) FILTER (WHERE (("e"."restaurant_control_order" IS DISTINCT FROM "e"."restaurant_hybrid_order") OR ("e"."activity_control_order" IS DISTINCT FROM "e"."activity_hybrid_order"))))::integer AS "changed_order_searches",
    ("avg"(
        CASE
            WHEN (("e"."restaurant_control_order" IS DISTINCT FROM "e"."restaurant_hybrid_order") OR ("e"."activity_control_order" IS DISTINCT FROM "e"."activity_hybrid_order")) THEN 1
            ELSE 0
        END))::numeric(8,4) AS "changed_order_rate",
    ("avg"("e"."latency_ms"))::numeric(12,2) AS "avg_latency_ms",
    "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("e"."latency_ms")::double precision)) AS "p95_latency_ms",
    ("avg"(("e"."no_results")::integer))::numeric(8,4) AS "no_result_rate",
    ("avg"("e"."pair_count"))::numeric(12,2) AS "avg_pair_count",
    ("count"("r"."id"))::integer AS "reviewed_searches",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'better'::"text")))::integer AS "better_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'same'::"text")))::integer AS "same_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'worse'::"text")))::integer AS "worse_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'unsafe'::"text")))::integer AS "unsafe_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'needs_review'::"text")))::integer AS "needs_review_reviews"
   FROM ("public"."search_ranking_experiments" "e"
     LEFT JOIN "public"."search_ranking_experiment_reviews" "r" ON (("r"."experiment_id" = "e"."id")))
  WHERE ("lower"(COALESCE(("e"."metadata" ->> 'test_mode'::"text"), 'false'::"text")) = ANY (ARRAY['true'::"text", '1'::"text", 'yes'::"text", 'on'::"text"]));


ALTER VIEW "public"."search_ranking_shadow_validation_v2" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."search_ranking_rollout_completion_readiness_v1" WITH ("security_invoker"='true') AS
 WITH "current_state" AS (
         SELECT "s"."stage_key",
            "s"."stage_started_at",
            "s"."last_decision",
            "s"."last_decision_reasons"
           FROM "public"."search_ranking_rollout_stage_state" "s"
          WHERE ("s"."id" = true)
        ), "active_run" AS (
         SELECT "search_ranking_rollout_runs"."id",
            "search_ranking_rollout_runs"."stage_key",
            "search_ranking_rollout_runs"."status",
            "search_ranking_rollout_runs"."started_by",
            "search_ranking_rollout_runs"."started_at",
            "search_ranking_rollout_runs"."completed_at",
            "search_ranking_rollout_runs"."completion_reason",
            "search_ranking_rollout_runs"."baseline_snapshot",
            "search_ranking_rollout_runs"."final_snapshot",
            "search_ranking_rollout_runs"."created_at",
            "search_ranking_rollout_runs"."updated_at"
           FROM "public"."search_ranking_rollout_runs"
          WHERE ("search_ranking_rollout_runs"."status" = 'active'::"text")
         LIMIT 1
        ), "validation" AS (
         SELECT "search_ranking_shadow_validation_v2"."shadow_searches",
            "search_ranking_shadow_validation_v2"."test_mode_searches",
            "search_ranking_shadow_validation_v2"."changed_order_searches",
            "search_ranking_shadow_validation_v2"."changed_order_rate",
            "search_ranking_shadow_validation_v2"."avg_latency_ms",
            "search_ranking_shadow_validation_v2"."p95_latency_ms",
            "search_ranking_shadow_validation_v2"."no_result_rate",
            "search_ranking_shadow_validation_v2"."avg_pair_count",
            "search_ranking_shadow_validation_v2"."reviewed_searches",
            "search_ranking_shadow_validation_v2"."better_reviews",
            "search_ranking_shadow_validation_v2"."same_reviews",
            "search_ranking_shadow_validation_v2"."worse_reviews",
            "search_ranking_shadow_validation_v2"."unsafe_reviews",
            "search_ranking_shadow_validation_v2"."needs_review_reviews"
           FROM "public"."search_ranking_shadow_validation_v2"
        ), "health" AS (
         SELECT "search_ranking_guardrail_health_v1"."enabled",
            "search_ranking_guardrail_health_v1"."evaluation_window_minutes",
            "search_ranking_guardrail_health_v1"."minimum_sample_size",
            "search_ranking_guardrail_health_v1"."max_no_result_rate_delta",
            "search_ranking_guardrail_health_v1"."max_p95_latency_ms",
            "search_ranking_guardrail_health_v1"."max_pair_count_drop",
            "search_ranking_guardrail_health_v1"."control_sample_size",
            "search_ranking_guardrail_health_v1"."hybrid_sample_size",
            "search_ranking_guardrail_health_v1"."control_no_result_rate",
            "search_ranking_guardrail_health_v1"."hybrid_no_result_rate",
            "search_ranking_guardrail_health_v1"."control_p95_latency_ms",
            "search_ranking_guardrail_health_v1"."hybrid_p95_latency_ms",
            "search_ranking_guardrail_health_v1"."control_avg_pair_count",
            "search_ranking_guardrail_health_v1"."hybrid_avg_pair_count"
           FROM "public"."search_ranking_guardrail_health_v1"
         LIMIT 1
        ), "open_alerts" AS (
         SELECT ("count"(*))::integer AS "critical_alerts"
           FROM "public"."search_ranking_rollout_alerts"
          WHERE (("search_ranking_rollout_alerts"."acknowledged_at" IS NULL) AND ("search_ranking_rollout_alerts"."severity" = 'critical'::"text"))
        ), "approval" AS (
         SELECT (EXISTS ( SELECT 1
                   FROM "public"."search_ranking_rollout_approvals" "a_1",
                    "active_run" "r_1"
                  WHERE (("a_1"."rollout_run_id" = "r_1"."id") AND ("a_1"."target_stage_key" = 'admin_5'::"text") AND ("a_1"."decision" = 'approved'::"text") AND ("a_1"."revoked_at" IS NULL)))) AS "admin_5_approved"
        )
 SELECT "c"."stage_key" AS "current_stage",
    "r"."id" AS "rollout_run_id",
    "r"."status" AS "rollout_run_status",
    "v"."shadow_searches",
    "v"."reviewed_searches",
    "v"."unsafe_reviews",
        CASE
            WHEN ("v"."reviewed_searches" > 0) THEN (("v"."worse_reviews")::numeric / ("v"."reviewed_searches")::numeric)
            ELSE (0)::numeric
        END AS "worse_rate",
    "v"."p95_latency_ms",
    COALESCE("o"."critical_alerts", 0) AS "open_critical_alerts",
    "a"."admin_5_approved",
    (("c"."stage_key" = 'admin_shadow'::"text") AND ("v"."shadow_searches" >= 25) AND ("v"."reviewed_searches" >= 10) AND ("v"."unsafe_reviews" = 0) AND (
        CASE
            WHEN ("v"."reviewed_searches" > 0) THEN (("v"."worse_reviews")::numeric / ("v"."reviewed_searches")::numeric)
            ELSE (0)::numeric
        END <= 0.20) AND (COALESCE("v"."p95_latency_ms", (0)::double precision) <= (2500)::double precision) AND (COALESCE("o"."critical_alerts", 0) = 0) AND "a"."admin_5_approved") AS "ready_for_admin_5",
    "array_remove"(ARRAY[
        CASE
            WHEN ("c"."stage_key" <> 'admin_shadow'::"text") THEN 'admin_shadow_not_active'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("r"."id" IS NULL) THEN 'no_active_rollout_run'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("v"."shadow_searches" < 25) THEN 'insufficient_shadow_searches'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("v"."reviewed_searches" < 10) THEN 'insufficient_manual_reviews'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("v"."unsafe_reviews" > 0) THEN 'unsafe_review_present'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("v"."reviewed_searches" > 0) AND ((("v"."worse_reviews")::numeric / ("v"."reviewed_searches")::numeric) > 0.20)) THEN 'worse_rate_too_high'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("v"."p95_latency_ms", (0)::double precision) > (2500)::double precision) THEN 'latency_too_high'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("o"."critical_alerts", 0) > 0) THEN 'critical_alert_open'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT "a"."admin_5_approved") THEN 'superadmin_approval_required'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "blocking_reasons"
   FROM ((((("current_state" "c"
     LEFT JOIN "active_run" "r" ON (true))
     LEFT JOIN "validation" "v" ON (true))
     LEFT JOIN "health" "h" ON (true))
     LEFT JOIN "open_alerts" "o" ON (true))
     LEFT JOIN "approval" "a" ON (true));


