CREATE OR REPLACE VIEW "public"."search_ranking_rollout_readiness_v1" WITH ("security_invoker"='true') AS
 WITH "current_state" AS (
         SELECT "state"."id",
            "state"."stage_key",
            "state"."stage_started_at",
            "state"."automatic_promotion_enabled",
            "state"."last_evaluated_at",
            "state"."last_decision",
            "state"."last_decision_reasons",
            "state"."updated_by",
            "state"."updated_at",
            "definition"."sort_order",
            "definition"."rollout_percent",
            "definition"."admin_only",
            "definition"."minimum_sample_size",
            "definition"."minimum_observation_minutes"
           FROM ("public"."search_ranking_rollout_stage_state" "state"
             JOIN "public"."search_ranking_rollout_stages" "definition" ON (("definition"."stage_key" = "state"."stage_key")))
          WHERE ("state"."id" = true)
        ), "next_stage" AS (
         SELECT "definition"."stage_key",
            "definition"."sort_order",
            "definition"."rollout_percent",
            "definition"."admin_only",
            "definition"."eligible_markets",
            "definition"."minimum_sample_size",
            "definition"."minimum_observation_minutes",
            "definition"."automatic_promotion_allowed",
            "definition"."enabled",
            "definition"."created_at",
            "definition"."updated_at"
           FROM "public"."search_ranking_rollout_stages" "definition",
            "current_state" "current_1"
          WHERE (("definition"."enabled" = true) AND ("definition"."sort_order" > "current_1"."sort_order"))
          ORDER BY "definition"."sort_order"
         LIMIT 1
        ), "health" AS (
         SELECT "search_ranking_guardrail_health_v1"."enabled",
            "search_ranking_guardrail_health_v1"."evaluation_window_minutes",
            "search_ranking_guardrail_health_v1"."minimum_sample_size",
            "search_ranking_guardrail_health_v1"."max_no_result_rate_delta",
            "search_ranking_guardrail_health_v1"."max_p95_latency_ms",
            "search_ranking_guardrail_health_v1"."max_pair_count_drop",
            "search_ranking_guardrail_health_v1"."control_sample_size",
            "search_ranking_guardrail_health_v1"."hybrid_sample_size",
            "search_ranking_guardrail_health_v1"."control_no_result_rate",
            "search_ranking_guardrail_health_v1"."hybrid_no_result_rate",
            "search_ranking_guardrail_health_v1"."control_p95_latency_ms",
            "search_ranking_guardrail_health_v1"."hybrid_p95_latency_ms",
            "search_ranking_guardrail_health_v1"."control_avg_pair_count",
            "search_ranking_guardrail_health_v1"."hybrid_avg_pair_count"
           FROM "public"."search_ranking_guardrail_health_v1"
         LIMIT 1
        )
 SELECT "current"."stage_key" AS "current_stage",
    "current"."stage_started_at",
    (EXTRACT(epoch FROM ("now"() - "current"."stage_started_at")) / 60.0) AS "minutes_in_stage",
    "current"."minimum_observation_minutes",
    "current"."minimum_sample_size",
    COALESCE("health"."control_sample_size", 0) AS "control_sample_size",
    COALESCE("health"."hybrid_sample_size", 0) AS "hybrid_sample_size",
    "current"."last_evaluated_at",
    "current"."last_decision",
    "current"."last_decision_reasons",
    "next"."stage_key" AS "next_stage",
    "next"."rollout_percent" AS "next_rollout_percent",
    (((EXTRACT(epoch FROM ("now"() - "current"."stage_started_at")) / 60.0) >= ("current"."minimum_observation_minutes")::numeric) AND (COALESCE("health"."control_sample_size", 0) >= "current"."minimum_sample_size") AND (COALESCE("health"."hybrid_sample_size", 0) >= "current"."minimum_sample_size") AND (COALESCE("current"."last_decision", ''::"text") = 'healthy'::"text")) AS "ready_to_promote",
    "array_remove"(ARRAY[
        CASE
            WHEN ((EXTRACT(epoch FROM ("now"() - "current"."stage_started_at")) / 60.0) < ("current"."minimum_observation_minutes")::numeric) THEN 'observation_window_incomplete'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("health"."control_sample_size", 0) < "current"."minimum_sample_size") THEN 'insufficient_control_sample'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("health"."hybrid_sample_size", 0) < "current"."minimum_sample_size") THEN 'insufficient_hybrid_sample'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("current"."last_decision", ''::"text") <> 'healthy'::"text") THEN 'guardrail_not_healthy'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "blocking_reasons",
    false AS "automatic_promotion_enabled"
   FROM (("current_state" "current"
     LEFT JOIN "next_stage" "next" ON (true))
     LEFT JOIN "health" ON (true));


