CREATE OR REPLACE VIEW "public"."search_ranking_shadow_validation_v1" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "shadow_searches",
    ("count"(*) FILTER (WHERE COALESCE((("e"."metadata" ->> 'test_mode'::"text"))::boolean, false)))::integer AS "test_mode_searches",
    ("count"(*) FILTER (WHERE (("e"."restaurant_control_order" IS DISTINCT FROM "e"."restaurant_hybrid_order") OR ("e"."activity_control_order" IS DISTINCT FROM "e"."activity_hybrid_order"))))::integer AS "changed_order_searches",
    ("avg"(
        CASE
            WHEN (("e"."restaurant_control_order" IS DISTINCT FROM "e"."restaurant_hybrid_order") OR ("e"."activity_control_order" IS DISTINCT FROM "e"."activity_hybrid_order")) THEN 1
            ELSE 0
        END))::numeric(8,4) AS "changed_order_rate",
    ("avg"("e"."latency_ms"))::numeric(12,2) AS "avg_latency_ms",
    "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("e"."latency_ms")::double precision)) AS "p95_latency_ms",
    ("avg"(("e"."no_results")::integer))::numeric(8,4) AS "no_result_rate",
    ("avg"("e"."pair_count"))::numeric(12,2) AS "avg_pair_count",
    ("count"("r"."id"))::integer AS "reviewed_searches",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'better'::"text")))::integer AS "better_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'same'::"text")))::integer AS "same_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'worse'::"text")))::integer AS "worse_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'unsafe'::"text")))::integer AS "unsafe_reviews",
    ("count"("r"."id") FILTER (WHERE ("r"."decision" = 'needs_review'::"text")))::integer AS "needs_review_reviews"
   FROM ("public"."search_ranking_experiments" "e"
     LEFT JOIN "public"."search_ranking_experiment_reviews" "r" ON (("r"."experiment_id" = "e"."id")))
  WHERE (COALESCE((("e"."metadata" ->> 'test_mode'::"text"))::boolean, false) = true);


ALTER VIEW "public"."search_ranking_shadow_validation_v1" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."search_ranking_shadow_readiness_v1" WITH ("security_invoker"='true') AS
 WITH "validation" AS (
         SELECT "search_ranking_shadow_validation_v1"."shadow_searches",
            "search_ranking_shadow_validation_v1"."test_mode_searches",
            "search_ranking_shadow_validation_v1"."changed_order_searches",
            "search_ranking_shadow_validation_v1"."changed_order_rate",
            "search_ranking_shadow_validation_v1"."avg_latency_ms",
            "search_ranking_shadow_validation_v1"."p95_latency_ms",
            "search_ranking_shadow_validation_v1"."no_result_rate",
            "search_ranking_shadow_validation_v1"."avg_pair_count",
            "search_ranking_shadow_validation_v1"."reviewed_searches",
            "search_ranking_shadow_validation_v1"."better_reviews",
            "search_ranking_shadow_validation_v1"."same_reviews",
            "search_ranking_shadow_validation_v1"."worse_reviews",
            "search_ranking_shadow_validation_v1"."unsafe_reviews",
            "search_ranking_shadow_validation_v1"."needs_review_reviews"
           FROM "public"."search_ranking_shadow_validation_v1"
        ), "approval" AS (
         SELECT (EXISTS ( SELECT 1
                   FROM "public"."search_ranking_rollout_stage_history"
                  WHERE (("search_ranking_rollout_stage_history"."to_stage_key" = 'admin_5'::"text") AND ("search_ranking_rollout_stage_history"."reason" ~~* '%shadow approval%'::"text")))) AS "superadmin_approved"
        )
 SELECT "validation"."shadow_searches",
    "validation"."test_mode_searches",
    "validation"."changed_order_searches",
    "validation"."changed_order_rate",
    "validation"."avg_latency_ms",
    "validation"."p95_latency_ms",
    "validation"."no_result_rate",
    "validation"."avg_pair_count",
    "validation"."reviewed_searches",
    "validation"."better_reviews",
    "validation"."same_reviews",
    "validation"."worse_reviews",
    "validation"."unsafe_reviews",
    "validation"."needs_review_reviews",
    "approval"."superadmin_approved",
        CASE
            WHEN ("validation"."reviewed_searches" > 0) THEN (("validation"."worse_reviews")::numeric / ("validation"."reviewed_searches")::numeric)
            ELSE (0)::numeric
        END AS "worse_rate",
    (("validation"."shadow_searches" >= 25) AND ("validation"."reviewed_searches" >= 10) AND ("validation"."unsafe_reviews" = 0) AND (
        CASE
            WHEN ("validation"."reviewed_searches" > 0) THEN (("validation"."worse_reviews")::numeric / ("validation"."reviewed_searches")::numeric)
            ELSE (0)::numeric
        END <= 0.20) AND (COALESCE("validation"."p95_latency_ms", (0)::double precision) <= (2500)::double precision) AND "approval"."superadmin_approved") AS "ready_for_admin_5",
    "array_remove"(ARRAY[
        CASE
            WHEN ("validation"."shadow_searches" < 25) THEN 'insufficient_shadow_searches'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("validation"."reviewed_searches" < 10) THEN 'insufficient_manual_reviews'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("validation"."unsafe_reviews" > 0) THEN 'unsafe_review_present'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("validation"."reviewed_searches" > 0) AND ((("validation"."worse_reviews")::numeric / ("validation"."reviewed_searches")::numeric) > 0.20)) THEN 'worse_rate_too_high'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (COALESCE("validation"."p95_latency_ms", (0)::double precision) > (2500)::double precision) THEN 'latency_too_high'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (NOT "approval"."superadmin_approved") THEN 'superadmin_approval_required'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "blocking_reasons"
   FROM "validation",
    "approval";


