    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "requester_type" "text" NOT NULL,
    "requester_name" "text",
    "requester_email" "text",
    "related_user_id" "uuid",
    "related_location_id" "uuid",
    "related_location_type" "text",
    "subject" "text" NOT NULL,
    "description" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "source" "text" DEFAULT 'user_dashboard'::"text" NOT NULL,
    "assigned_admin_id" "uuid",
    "created_by_admin_id" "uuid",
    "created_by_admin_email" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_activity_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ticket_number" "text",
    "requester_phone" "text",
    "topic" "text" DEFAULT 'General Support'::"text",
    "public_access_token" "text",
    "last_message_at" timestamp with time zone DEFAULT "now"(),
    "department" "text",
    "assigned_admin_email" "text",
    "assigned_admin_name" "text",
    "department_route" "text" DEFAULT 'general'::"text",
    "provider_thread_id" "text",
    "provider_message_id" "text",
    "assigned_team_member_id" "uuid",
    "last_work_session_id" "uuid",
    "total_tracked_minutes" integer DEFAULT 0,
    "answered_at" timestamp with time zone,
    "marked_complete_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "completed_by_team_member_id" "uuid",
    "manager_review_status" "text",
    "payroll_eligible" boolean DEFAULT true,
    "assigned_to" "uuid",
    "user_id" "uuid",
    "email" "text",
    "name" "text",
    "category" "text",
    "related_outing_id" "uuid",
    "related_saved_plan_id" "uuid",
    "related_reservation_id" "uuid",
    "location_id" "uuid",
    "assigned_group" "text",
    "first_response_at" timestamp with time zone,
    "reopened_at" timestamp with time zone,
    "escalated_at" timestamp with time zone,
    "sla_first_response_due_at" timestamp with time zone,
    "sla_resolution_due_at" timestamp with time zone,
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "sms_consent_at" timestamp with time zone,
    "sms_consent_source" "text",
    CONSTRAINT "support_tickets_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"]))),
    CONSTRAINT "support_tickets_related_location_type_check" CHECK (("related_location_type" = ANY (ARRAY['restaurants'::"text", 'activities'::"text"]))),
    CONSTRAINT "support_tickets_requester_contact_check" CHECK (((NULLIF("btrim"(COALESCE("requester_email", ''::"text")), ''::"text") IS NOT NULL) OR (NULLIF("btrim"(COALESCE("requester_phone", ''::"text")), ''::"text") IS NOT NULL))),
    CONSTRAINT "support_tickets_requester_type_check" CHECK (("requester_type" = ANY (ARRAY['user'::"text", 'location'::"text", 'employee'::"text", 'admin'::"text", 'system'::"text"]))),
    CONSTRAINT "support_tickets_status_check" CHECK (("status" = ANY (ARRAY['new'::"text", 'open'::"text", 'pending'::"text", 'waiting_on_customer'::"text", 'waiting_on_internal'::"text", 'escalated'::"text", 'resolved'::"text", 'closed'::"text", 'reopened'::"text"])))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


COMMENT ON COLUMN "public"."support_tickets"."requester_type" IS 'user, location, employee, admin, or system.';



COMMENT ON COLUMN "public"."support_tickets"."location_id" IS 'Canonical location associated with a location-account support case.';



COMMENT ON COLUMN "public"."support_tickets"."assigned_group" IS 'Support routing group such as customer_support, location_success, technical_support, billing, or reservations.';



