CREATE TABLE IF NOT EXISTS "public"."website_hosting_nodes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "provider" "text" DEFAULT 'lightsail'::"text" NOT NULL,
    "instance_name" "text" NOT NULL,
    "region" "text",
    "public_ip" "inet",
    "status" "text" DEFAULT 'provisioning'::"text" NOT NULL,
    "accepting_new_sites" boolean DEFAULT false NOT NULL,
    "max_sites" integer DEFAULT 20 NOT NULL,
    "cpu_percent" numeric(5,2),
    "memory_percent" numeric(5,2),
    "disk_percent" numeric(5,2),
    "last_health_check_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "role" "text" DEFAULT 'primary'::"text" NOT NULL,
    "deploy_url" "text",
    "healthy_since" timestamp with time zone,
    "caddy_status" "text",
    "certbot_timer_status" "text",
    "tls_status" "text",
    "tls_wildcard" boolean,
    "tls_cert_subject" "text",
    "tls_cert_expires_at" timestamp with time zone,
    "tls_last_checked_at" timestamp with time zone,
    "cert_last_renewed_at" timestamp with time zone,
    "node_role" "text" DEFAULT 'web'::"text" NOT NULL,
    "proxy_type" "text",
    "proxy_status" "text",
    "app_service_status" "text",
    "app_health_status" "text",
    "app_health_checked_at" timestamp with time zone,
    "health_endpoint" "text",
    CONSTRAINT "website_hosting_nodes_cpu_percent_check" CHECK ((("cpu_percent" IS NULL) OR (("cpu_percent" >= (0)::numeric) AND ("cpu_percent" <= (100)::numeric)))),
    CONSTRAINT "website_hosting_nodes_disk_percent_check" CHECK ((("disk_percent" IS NULL) OR (("disk_percent" >= (0)::numeric) AND ("disk_percent" <= (100)::numeric)))),
    CONSTRAINT "website_hosting_nodes_max_sites_check" CHECK ((("max_sites" >= 1) AND ("max_sites" <= 500))),
    CONSTRAINT "website_hosting_nodes_memory_percent_check" CHECK ((("memory_percent" IS NULL) OR (("memory_percent" >= (0)::numeric) AND ("memory_percent" <= (100)::numeric)))),
    CONSTRAINT "website_hosting_nodes_node_role_check" CHECK (("node_role" = ANY (ARRAY['web'::"text", 'domain_gateway'::"text"]))),
    CONSTRAINT "website_hosting_nodes_provider_check" CHECK (("provider" = 'lightsail'::"text")),
    CONSTRAINT "website_hosting_nodes_role_check" CHECK (("role" = ANY (ARRAY['primary'::"text", 'failover'::"text"]))),
    CONSTRAINT "website_hosting_nodes_status_check" CHECK (("status" = ANY (ARRAY['provisioning'::"text", 'healthy'::"text", 'degraded'::"text", 'offline'::"text", 'maintenance'::"text"])))
);


ALTER TABLE "public"."website_hosting_nodes" OWNER TO "postgres";


