    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "website_hosting_replicas_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'syncing'::"text", 'synced'::"text", 'failed'::"text", 'stale'::"text"])))
);


