CREATE OR REPLACE VIEW "public"."mailing_batch_summary" WITH ("security_invoker"='true') AS
 SELECT "b"."id",
    "b"."name",
    "b"."status",
    "b"."planned_mail_date",
    "b"."mailed_at",
    "b"."completed_at",
    "b"."notes",
    "b"."created_by",
    "b"."created_at",
    "b"."updated_at",
    "count"("i"."id") AS "item_count",
    "count"("i"."id") FILTER (WHERE ("i"."printed_at" IS NOT NULL)) AS "printed_count",
    "count"("i"."id") FILTER (WHERE ("i"."mailed_at" IS NOT NULL)) AS "mailed_count",
    "count"("i"."id") FILTER (WHERE ("i"."first_scan_at" IS NOT NULL)) AS "scanned_count",
    "count"("i"."id") FILTER (WHERE ("i"."claim_started_at" IS NOT NULL)) AS "claim_started_count",
    "count"("i"."id") FILTER (WHERE ("i"."claimed_at" IS NOT NULL)) AS "claimed_count",
    "count"("i"."id") FILTER (WHERE ("i"."returned_at" IS NOT NULL)) AS "returned_count"
   FROM ("public"."mailing_batches" "b"
     LEFT JOIN "public"."mailing_batch_items" "i" ON (("i"."batch_id" = "b"."id")))
  GROUP BY "b"."id";



CREATE OR REPLACE VIEW "public"."search_internal_test_run_scorecard_v1" WITH ("security_invoker"='true') AS
 SELECT "run"."id",
    "run"."run_key",
    "run"."status",
    "run"."started_at",
    "run"."completed_at",
    "run"."scenario_count",
    "run"."passed_count",
    "run"."failed_count",
    "run"."warning_count",
    "run"."evaluation_score",
    COALESCE("avg"("result"."attribution_rate"), (0)::numeric) AS "average_attribution_rate",
    COALESCE("avg"("result"."duplicate_rate"), (0)::numeric) AS "average_duplicate_rate",
    COALESCE("max"("result"."max_rank_shift"), 0) AS "maximum_rank_shift",
    COALESCE("avg"("result"."mean_absolute_rank_shift"), (0)::numeric) AS "average_rank_shift",
    COALESCE("avg"("result"."top3_overlap_rate"), (0)::numeric) AS "average_top3_overlap",
    "run"."summary"
   FROM ("public"."search_internal_test_runs" "run"
     LEFT JOIN "public"."search_internal_test_results" "result" ON (("result"."run_id" = "run"."id")))
  GROUP BY "run"."id";



